INSERT INTO "classifications" VALUES(975,'claude-haiku-5-5','2026-10-16T15:57:45Z',0,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["NP"], "dissemination_channels": [], "event_date": "2026-08-26", "event_location": "Rasuwa District, Nepal", "event_name": null, "ew4all_pillars": [], "hazard": "glacial_lake_outburst", "impacts": {"affected": null, "deaths": 1300, "economic_losses": null, "evacuated": null, "injured": null, "missing": 5000, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "ネパール洪水 、 温暖化が一因なら排出した国や企業は補償すべき ？", "outcome": "not_reported", "outcome_justification": "The snippet covers the disaster''s death toll and climate attribution/compensation debate but says nothing about monitoring, warnings, forecasts or their dissemination.", "relevant": false, "review": false, "summary_en": "A glacier ice and rock collapse from Langtang Lirung in Rasuwa District, Nepal, on 26 August triggered a debris flow that killed over 1,300 people and left more than 5,000 missing as of 14 September. The article focuses on whether climate change attribution should lead to compensation for emitting countries and companies. The snippet contains no information on early warning monitoring, warnings or response.", "summary_original": "8月26日、ネパール・ラスワ郡のランタン・リルン山で約2平方キロメートルの氷河の氷と岩塊が崩落し土石流が発生。9月14日時点で1300人以上が死亡、5000人以上が行方不明。気候変動の責任と補償をめぐる記事。", "title_en": "Nepal floods: should countries and companies that emitted greenhouse gases compensate if climate change is a cause?", "wmo_regions": ["II"]}');
