INSERT INTO "classifications" VALUES(1383,'claude-haiku-5-5','2026-10-17T09:49:43Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Water Resources Agency (Japan Water Agency)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Inba Lake, Chiba Prefecture, Japan", "event_name": "Typhoon 25", "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風で堤防決壊の印旛沼 、 大雨で地盤に空洞 専門家 「 どこでも起こる 」", "outcome": "not_reported", "outcome_justification": "The snippet reports a levee breach, flooding and expert analysis of ground cavities, but does not describe any warning, forecast, or response; the agency''s 21 September actions are cut off.", "relevant": false, "review": false, "summary_en": "Typhoon 25 caused a levee breach on Inba Lake in northern Chiba Prefecture, flooding houses and rice fields. An expert attributes the collapse to ground cavities formed by rain since August and warns similar failures could occur elsewhere. The snippet does not describe warnings or forecasts issued before the breach, so it is judged not relevant to early warning services.", "summary_original": "台風25号で千葉県北部の印旛沼の堤防が決壊し、住宅や田んぼが冠水した。専門家は大雨で地盤に空洞ができたとみて、同様の事象が各地で起こり得ると指摘している。", "title_en": "Inba Lake levee breached by typhoon; expert says cavities from heavy rain in ground could occur anywhere", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(1384,'claude-haiku-5-5','2026-10-17T09:49:47Z',1,0.8,0,'{"actions_taken": ["Evacuations of affected families", "Continued monitoring of river level, including non-riverside areas"], "agencies": [], "confidence": 0.8, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Paraná River, Paraguay", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": 1300, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Entre evacuaciones y el temor a otra crecida, 1.300 familias siguen afectadas", "outcome": "not_reported", "outcome_justification": "The article reports ongoing evacuations and continued vigilance but gives no assessment of whether warnings were effective.", "relevant": true, "review": false, "summary_en": "The Paraná River reached 120.81 m above sea level and is expected to recede, but about 1,300 families remain affected and evacuated. Authorities are maintaining monitoring, including in non-riverside areas, in case of another rise.", "summary_original": "El Paraná llegó a 120,81 metros sobre el nivel del mar y se espera que retroceda. Las autoridades mantienen la vigilancia, incluso en zonas no ribereñas, ante el temor a otra crecida; 1.300 familias siguen afectadas.", "title_en": "Between evacuations and fear of another flood, 1,300 families remain affected", "wmo_regions": ["III"]}');
