INSERT INTO "classifications" VALUES(1609,'claude-haiku-5-5','2026-10-18T03:08:46Z',0,0.9,0,'{"actions_taken": [], "agencies": [], "confidence": 0.9, "countries": [], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Siete de los 16 signos vitales del planeta en alerta roja, aunque hay algunos que mejoran-NotiCel-La verdad como es-Noticias de Puerto Rico", "outcome": "not_reported", "outcome_justification": "The item reports on a general climate-indicator assessment (State of the Climate 2026 report) with no specific hazard event, warning, forecast, or dissemination described.", "relevant": false, "review": false, "summary_en": "A EFE news item reports that seven of 16 planetary vital signs are in an alarming state according to the ''State of the Climate 2026'' report published in BioScience, while others show improvement. The item concerns general climate-change indicators rather than early warning services for a natural hazard.", "summary_original": "Siete de los 16 signos vitales para la ''salud'' del planeta se encuentran en un estado alarmante, y aunque algunos de los otros nueve presentan una mejoría, ésta ha de ser más contundente, según el informe ''El estado del clima 2026'' publicado en BioScience.", "title_en": "Seven of the 16 vital signs of the planet in red alert, although some are improving - NotiCel", "wmo_regions": []}');
INSERT INTO "classifications" VALUES(1610,'claude-haiku-5-5','2026-10-18T03:10:42Z',1,0.8,0,'{"actions_taken": ["Evacuation of 206 people in six localities of Corrientes Province", "Self-evacuation of 266 people"], "agencies": [{"country": "AR", "name": "Provincial authorities of Corrientes", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 206, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Más de 400 personas dejaron sus casas en Corrientes por la crecida de los ríos Paraná y Uruguay", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and authorities warning that the number of affected families could increase, but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "Flooding of the Paraná and Uruguay rivers led to the evacuation of 206 people and self-evacuation of 266 others across six localities in Corrientes Province, Argentina. Authorities warned that the number of affected families could rise as rains and river swelling continue.", "summary_original": "La crecida de los ríos Paraná y Uruguay obligó a evacuar a 206 personas y a 266 a autoevacuarse en seis localidades de Corrientes. Las autoridades advirtieron que podrían aumentar las familias afectadas.", "title_en": "More than 400 people left their homes in Corrientes due to the flooding of the Paraná and Uruguay rivers", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1611,'claude-haiku-5-5','2026-10-18T03:10:44Z',0,0.35,1,'{"actions_taken": [], "agencies": [], "confidence": 0.35, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Paraná and Uruguay rivers, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta por El Niño: crecidas en el río Paraná y ciudades inundadas", "outcome": "not_reported", "outcome_justification": "The snippet describes river flooding and El Niño alarms but does not mention specific warnings, forecasts, or their dissemination.", "relevant": false, "review": true, "summary_en": "A news item reports that the Paraná and Uruguay rivers are flooding in Argentina and that El Niño is considered highly relevant, with alarms raised in several areas. The snippet does not describe specific forecasts, warnings or dissemination actions, so its relevance to early warning services is uncertain.", "summary_original": "El Niño sigue más vigente que nunca en Argentina y las crecidas de los ríos Paraná y Uruguay encendieron las alarmas en diversas localidades.", "title_en": "El Niño alert: Paraná river floods and flooded cities", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1612,'claude-haiku-5-5','2026-10-18T03:10:48Z',1,0.7,0,'{"actions_taken": ["Evacuation of over 400 people from their homes", "Relocation of evacuees to Casa Promesera and Taba Cué lodging"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Itatí, Corrientes, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 400, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Corrientes: tras la crecida de los ríos Paraná y Uruguay más de 400 personas abandonaron sus hogares", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations after river flooding but does not state whether warnings were issued in advance or how they were received.", "relevant": true, "review": false, "summary_en": "Following the rise of the Paraná and Uruguay rivers in Corrientes province, Argentina, more than 400 people were evacuated from their homes. Itatí was the most affected locality, with 110 people from 43 families moved to the Casa Promesera and Taba Cué lodging. The snippet does not describe the early warnings or forecasts that preceded the evacuations.", "summary_original": "Tras la crecida de los ríos Paraná y Uruguay, más de 400 personas fueron evacuadas en Corrientes. Itatí es la localidad más afectada, con 110 personas de 43 familias trasladadas a la Casa Promesera y al hospedaje Taba Cué.", "title_en": "Corrientes: after the rise of the Paraná and Uruguay rivers, more than 400 people left their homes", "wmo_regions": ["III"]}');
