INSERT INTO "classifications" VALUES(2344,'claude-haiku-5-5','2026-10-20T03:16:47Z',1,0.85,0,'{"actions_taken": ["Thousands of people evacuated"], "agencies": [], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencian Community, Spain", "event_name": "DANA Adam", "ew4all_pillars": [4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 4, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Última hora de la dana Adam: cuatro personas han fallecido y las lluvias fuertes continúan este lunes en Baleares y en la Comunidad Valenciana", "outcome": "negative", "outcome_justification": "Four deaths, historic rainfall records and serious flooding are reported, but the snippet gives no information on whether warnings were issued in time or how they were received.", "relevant": true, "review": false, "summary_en": "A DANA (cut-off low) named Adam brought historic rainfall records to localities such as Pego and Forna in the Valencian Community, causing serious flooding, four deaths and thousands of evacuations. Heavy rain was expected to continue on Monday in the Balearic Islands and the Valencian Community. The snippet does not describe the warnings issued or how they were disseminated.", "summary_original": "El temporal ha dejado registros históricos de precipitaciones en localidades como Pego o Forna, graves inundaciones y miles de personas evacuadas, con cuatro fallecidos. Las lluvias fuertes continúan el lunes en Baleares y la Comunidad Valenciana.", "title_en": "Latest on DANA Adam: four people dead and heavy rain continues Monday in the Balearics and the Valencian Community", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2347,'claude-haiku-5-5','2026-10-20T03:18:00Z',1,0.9,0,'{"actions_taken": ["Confinement of 145 localities on the Valencian and Alicante coast", "Suspension of classes for more than 102,000 students", "Aerial rescues"], "agencies": [], "confidence": 0.9, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencian and Alicante coast, Spain", "event_name": "DANA Adam", "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": 4, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam deja cuatro muertos en España | Noticias Diario de Burgos", "outcome": "not_reported", "outcome_justification": "The snippet reports four deaths and extensive disruption but does not state whether warnings were issued in advance, how they were disseminated, or whether they reduced losses.", "relevant": true, "review": false, "summary_en": "Torrential rain from DANA Adam, with more than 700 litres per square metre, led to confinement orders for 145 localities on the Valencian and Alicante coast and the suspension of classes for over 102,000 students. Four deaths were reported, along with hundreds of incidents and aerial rescues. The snippet does not describe the forecasts or warnings issued beforehand.", "summary_original": "Las lluvias torrenciales de la DANA Adam, con más de 700 litros por metro cuadrado, mantienen confinadas 145 localidades del litoral valenciano y alicantino, dejan cuatro muertos y obligan a suspender las clases de más de 102.000 estudiantes.", "title_en": "The DANA Adam leaves four dead in Spain", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2348,'claude-haiku-5-5','2026-10-20T03:16:51Z',1,0.6,0,'{"actions_taken": [], "agencies": [], "confidence": 0.6, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Alaska, United States", "event_name": null, "ew4all_pillars": [1], "hazard": "landslide", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Un deslizamiento en Alaska provocó un tsunami que alcanzó 1,580 pies en la montaña", "outcome": "not_reported", "outcome_justification": "The snippet mentions scientists warning about precursor signals that could help prevent future disasters, but reports no warnings issued or actions taken for this event.", "relevant": true, "review": false, "summary_en": "A massive landslide in Alaska triggered the second-highest tsunami on record, sending water 1,580 feet up a mountain. Scientists point to prior warning signs that could help prevent future disasters, though the snippet does not describe any warnings issued during the event.", "summary_original": "Un deslizamiento masivo en Alaska desencadenó el segundo tsunami más alto registrado, enviando agua 1,580 pies hacia una montaña. Científicos advierten sobre señales previas que podrían ayudar a prevenir futuros desastres.", "title_en": "A landslide in Alaska caused a tsunami that reached 1,580 feet up a mountain", "wmo_regions": ["IV"]}');
