INSERT INTO "classifications" VALUES(2855,'claude-haiku-5-5','2026-10-21T03:24:09Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Instituto Nacional de Tecnología Agropecuaria (INTA)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Evacuar ganado de las islas durante una creciente puede costar casi $30 millones, según el INTA", "outcome": "not_reported", "outcome_justification": "The snippet is a cost study on livestock evacuation during floods; it does not describe any warning, forecast, or monitoring activity.", "relevant": false, "review": false, "summary_en": "A study by Argentina''s INTA estimates that evacuating 500 head of livestock from islands during a generalized flood emergency could cost nearly $30 million, versus about $20.5 million under normal conditions. The item concerns economic costs of evacuation and does not describe warnings, forecasts, or dissemination of early warnings.", "summary_original": "Un estudio del INTA estima que evacuar 500 cabezas de ganado de las islas durante una emergencia generalizada por creciente puede costar casi $30 millones, frente a unos $20,5 millones en condiciones normales.", "title_en": "Evacuating livestock from the islands during a flood can cost almost $30 million, according to INTA", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2858,'claude-haiku-5-5','2026-10-21T03:23:32Z',1,0.9,0,'{"actions_taken": ["Activated SAE emergency alert messaging to request evacuation of a sector affected by Río Mapocho overflow"], "agencies": [{"country": "CL", "name": "Senapred (Servicio Nacional de Prevención y Respuesta ante Desastres)", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-20", "event_location": "Talagante, Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senapred ordena evacuar campamento ribera del Río Mapocho en Talagante por desborde", "outcome": "not_reported", "outcome_justification": "The snippet reports the evacuation order and alert activation but gives no information on compliance or results.", "relevant": true, "review": false, "summary_en": "Chile''s national disaster agency Senapred activated its SAE emergency alert messaging system to order evacuation of a riverside encampment in Talagante after the Río Mapocho overflowed in the Metropolitan Region. The snippet does not report monitoring details, lead time, or the outcome of the evacuation.", "summary_original": "Servicio Nacional de Prevención y Respuesta ante Desastres activó mensajería SAE para solicitar la evacuación de un sector en la Región Metropolitana debido al desborde del Río Mapocho.", "title_en": "Senapred orders evacuation of riverside encampment on Río Mapocho in Talagante due to overflow", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2860,'claude-haiku-5-5','2026-10-21T03:24:12Z',1,0.8,0,'{"actions_taken": ["Recommended anticipating livestock evacuation operations from islands", "Recommended site-specific strategies for each establishment"], "agencies": [{"country": "AR", "name": "INTA Paraná", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Paraná River islands, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": "Delaying evacuation of 500 animals could increase direct costs by 9 million pesos", "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Paraná: un estudio reveló los gastos de los productores para retirar el ganado de las islas en momentos críticos", "outcome": "not_reported", "outcome_justification": "The item reports a study on costs of delayed livestock evacuation during river flooding; it does not report actual outcomes of warnings or evacuations.", "relevant": true, "review": false, "summary_en": "An INTA Paraná report warns that delaying the evacuation of 500 livestock from Paraná River islands during flooding could raise direct costs by 9 million pesos. Researchers recommend anticipating evacuation operations and designing site-specific strategies for each farm.", "summary_original": "Un informe del INTA Paraná advierte que demorar la evacuación de 500 animales de las islas del Paraná durante la crecida puede incrementar en 9 millones de pesos los costos directos, y recomienda anticipar los operativos y diseñar estrategias específicas para cada establecimiento.", "title_en": "Paraná flood: a study revealed the costs for producers of removing livestock from the islands at critical moments", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2861,'claude-haiku-5-5','2026-10-21T03:24:17Z',1,0.8,0,'{"actions_taken": ["Preparation of a site about 300 m from the Héroes de Malvinas bridge to shelter families from Vuelta del Paraguayo", "Installation of habitational modules, sanitary facilities and common areas"], "agencies": [{"country": "AR", "name": "Municipalidad de Alto Verde", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Alto Verde, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Paraná: cómo será el Centro de Asistencia que prepara el municipio en Alto Verde y a cuántas familias podrá recibir", "outcome": "not_reported", "outcome_justification": "The article describes preparedness for a possible Paraná River flood; no outcome has yet been reported and no evacuations are currently planned.", "relevant": true, "review": false, "summary_en": "The municipality of Alto Verde has begun preparing a site about 300 metres from the Héroes de Malvinas bridge to house families from Vuelta del Paraguayo in case of a possible Paraná River flood. The shelter will include habitational modules, sanitary facilities and common areas. No evacuations are currently planned.", "summary_original": "La Municipalidad de Alto Verde acondiciona un predio a 300 metros del puente Héroes de Malvinas para alojar a familias de la Vuelta del Paraguayo ante una eventual crecida del Paraná, con módulos habitacionales, sanitarios y áreas comunes; por ahora no hay evacuaciones previstas.}", "title_en": "Paraná River flood: how the assistance centre being prepared by the municipality in Alto Verde will work and how many families it can receive", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2862,'copied','2026-10-21T03:25:41Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Instituto Nacional de Tecnología Agropecuaria (INTA)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Evacuar ganado de las islas durante una creciente puede costar casi $30 millones, según el INTA", "outcome": "not_reported", "outcome_justification": "The snippet is a cost study on livestock evacuation during floods; it does not describe any warning, forecast, or monitoring activity.", "relevant": false, "review": false, "summary_en": "A study by Argentina''s INTA estimates that evacuating 500 head of livestock from islands during a generalized flood emergency could cost nearly $30 million, versus about $20.5 million under normal conditions. The item concerns economic costs of evacuation and does not describe warnings, forecasts, or dissemination of early warnings.", "summary_original": "Un estudio del INTA estima que evacuar 500 cabezas de ganado de las islas durante una emergencia generalizada por creciente puede costar casi $30 millones, frente a unos $20,5 millones en condiciones normales.", "title_en": "Evacuating livestock from the islands during a flood can cost almost $30 million, according to INTA", "wmo_regions": ["III"]}');
