INSERT INTO "classifications" VALUES(2899,'claude-haiku-5-5','2026-10-21T03:25:28Z',1,0.7,0,'{"actions_taken": ["Closure of the San Sebastián point"], "agencies": [{"country": "AR", "name": "Prefectura Naval Argentina", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del río Paraná en Corrientes: cerraron la punta San Sebastián", "outcome": "not_reported", "outcome_justification": "The snippet reports river level exceeding the evacuation threshold and a closure, but gives no information on warning dissemination effectiveness or outcomes.", "relevant": true, "review": false, "summary_en": "The Paraná River reached 7.17 metres at the Corrientes port, exceeding the evacuation level set by Argentina''s Naval Prefecture. As a result, the San Sebastián point was closed. The snippet does not describe the forecasts or warnings issued to the public.", "summary_original": "El nivel del Paraná alcanzó los 7,17 metros en el puerto de Corrientes, superando la marca de evacuación fijada por Prefectura Naval Argentina, y se cerró la punta San Sebastián.", "title_en": "Paraná River flood in Corrientes: San Sebastián point closed", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2900,'claude-haiku-5-5','2026-10-21T03:22:00Z',1,0.95,0,'{"actions_taken": ["Red Alert declared for the entire Metropolitan Region", "Evacuation of some points due to floods and mass movement"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Santiago Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta Roja en toda la Región Metropolitana por evento meteorológico: Intensas lluvias en varios puntos de Santiago", "outcome": "not_reported", "outcome_justification": "The snippet reports the Red Alert declaration and evacuations underway but gives no information on whether warnings were effective or on final impacts.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency service Senapred declared a Red Alert for the entire Santiago Metropolitan Region due to intense rainfall, initially limited to pre-Andean communes. Some locations have already been evacuated in response to river flooding, mass movement and inundation.", "summary_original": "Senapred decretó Alerta Roja para toda la Región Metropolitana por intensas lluvias, inicialmente solo en comunas precordilleranas, y algunos puntos ya fueron evacuados ante crecidas, remoción en masa e inundaciones.", "title_en": "Red Alert across the entire Metropolitan Region for weather event: Intense rain in several points of Santiago", "wmo_regions": ["III"]}');
