INSERT INTO "classifications" VALUES(3010,'claude-haiku-5-5','2026-10-21T03:23:21Z',1,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": ["cell_broadcast"], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La lección aprendida de la dana de 2024: las alertas masivas y la prevención son clave para salvar vidas", "outcome": "mixed", "outcome_justification": "The snippet contrasts management of the 2024 DANA floods with a more recent flood, highlighting mass alerts and prevention as lifesaving but noting pending issues, without specific outcome details.", "relevant": true, "review": false, "summary_en": "An El País article compares early warning and flood management between the 2024 DANA event in Spain and a more recent flood, arguing that mass alerts and prevention are key to saving lives while noting remaining shortcomings. The snippet does not give specifics on the systems or channels used.", "summary_original": "Un artículo de El País compara la gestión de alertas y prevención entre la DANA de 2024 y una inundación más reciente, señalando que las alertas masivas son clave para salvar vidas, aunque quedan asignaturas pendientes.", "title_en": "The lesson learned from the 2024 DANA: mass alerts and prevention are key to saving lives", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(3058,'copied','2026-10-21T03:25:41Z',1,0.85,0,'{"actions_taken": ["Ministry of Defence activated a contingency plan in the Litoral region due to river flooding"], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}, {"country": "AR", "name": "Ministerio de Defensa (Argentina)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-10-19", "event_location": "Litoral and central-east, Argentina", "event_name": "Super El Niño 2026", "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Súper Niño 2026 en Argentina, EN VIVO: qué ciudades están en riesgo de inundación y cuándo llega el pico de la crecida", "outcome": "not_reported", "outcome_justification": "The snippet describes forecasts of intensity and activation of a contingency plan, but no outcomes are reported yet.", "relevant": true, "review": false, "summary_en": "The Servicio Meteorológico Nacional anticipated that the El Niño phenomenon will reach a ''strong or very strong'' intensity in central-east Argentina. The Ministry of Defence activated a contingency plan in the Litoral region in response to river flooding, and the live coverage focuses on which cities face flood risk and when the flood peak will arrive.", "summary_original": "El Servicio Meteorológico Nacional anticipó que el fenómeno alcanzará en el centro-este argentino una intensidad \"fuerte o muy fuerte\". El ministerio de Defensa activó el plan de contingencia en el Litoral por las crecidas de los ríos.", "title_en": "Super El Niño 2026 in Argentina, LIVE: which cities are at risk of flooding and when the flood peak arrives", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3059,'claude-haiku-5-5','2026-10-21T03:23:18Z',1,0.7,0,'{"actions_taken": ["Evacuation of around 300 people in Itatí", "Residents moving by boat and temporary bridges in flooded areas such as Barrio Ibiray"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Itatí, Corrientes, Argentina", "event_name": null, "ew4all_pillars": [2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 300, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Fenómeno El Niño: en Itatí la inundación es récord, la gente ya se mueve en botes y lanchas y le reza a la Virgen", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and a river level exceeding the evacuation threshold, but does not state whether warnings were issued in advance, how they were disseminated, or whether they were effective.", "relevant": true, "review": false, "summary_en": "The Paraná River reached 8.24 m in Itatí, Argentina, exceeding the evacuation level and the 2023 record of 8.07 m, linked to the El Niño phenomenon. About 300 people have been evacuated, and residents in flooded neighbourhoods such as Ibiray are moving by boat and temporary bridges. The snippet does not describe the warnings or forecasts issued in advance.", "summary_original": "El río Paraná llegó a 8,24 metros en Itatí, superó el nivel de evacuación y el récord de 2023, con unas 300 personas evacuadas y vecinos movilizándose en botes y puentes provisorios.", "title_en": "El Niño phenomenon: in Itatí the flood is a record, people are already moving by boat and launches and praying to the Virgin", "wmo_regions": ["III"]}');
