INSERT INTO "classifications" VALUES(3106,'claude-haiku-5-5','2026-10-21T03:23:00Z',1,0.85,0,'{"actions_taken": ["Declaration of Red Alert for the commune of Arauco", "Evacuation of more than 150 families"], "agencies": [{"country": "CL", "name": "Senapred (Servicio Nacional de Prevención y Respuesta ante Desastres)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Villa El Mirador, Arauco, Bío Bío Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "landslide", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 150, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Evacúan a más de 150 familias por socavón de medio kilómetro y declaran Alerta Roja para Arauco", "outcome": "not_reported", "outcome_justification": "The item reports the Red Alert declaration and evacuation of over 150 families, but does not state whether the warning or evacuation outcomes were positive or negative.", "relevant": true, "review": false, "summary_en": "Chile''s national disaster service Senapred declared a Red Alert for the commune of Arauco after a mass movement of about half a kilometre opened a large sinkhole in the Villa El Mirador sector, which occurred roughly a week earlier. More than 150 families were evacuated as a result. The item focuses on the alert and evacuation response rather than on monitoring or forecasting.", "summary_original": "Senapred declaró Alerta Roja en la comuna de Arauco tras una remoción en masa de unos medio kilómetro en el sector Villa El Mirador, ocurrida hace alrededor de una semana, y se evacuaron más de 150 familias.", "title_en": "More than 150 families evacuated due to half-kilometre sinkhole and Red Alert declared for Arauco", "wmo_regions": ["III"]}');
