INSERT INTO "classifications" VALUES(3324,'claude-haiku-5-5','2026-10-22T03:21:04Z',1,0.97,0,'{"actions_taken": ["Issuance of a Level 5 flood special warning (氾濫特別警報) for the Kohoyoshi River via JMA press release"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-20", "event_location": "Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "子吉川（秋田県）にレベル５氾濫特別警報発表", "outcome": "not_reported", "outcome_justification": "The item is an official JMA press release announcing the warning; no information on public response, damage or lives saved is given.", "relevant": true, "review": false, "summary_en": "JMA issued a Level 5 flood special warning (the highest flood alert level) for the Kohoyoshi River in Akita Prefecture, as announced in an official press release on 2026-10-21 (published 2026-10-20 UTC). The release concerns a forecast of river flooding threatening life and property. No impact or response details are provided in the snippet.", "summary_original": "気象庁が子吉川（秋田県）に氾濫特別警報（レベル５）を発表したことを伝える報道発表。", "title_en": "Level 5 flood special warning issued for the Kohoyoshi River (Akita Prefecture)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3330,'claude-haiku-5-5','2026-10-22T03:21:30Z',1,0.9,0,'{"actions_taken": ["JMA urged residents to take early protective measures against a large, very strong typhoon expected to approach the Sakishima Islands"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-23", "event_location": "Sakishima Islands, Okinawa Prefecture, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 1-2 days before approach (expected 23-24 October)", "lead_time_hours": null, "original_title": "猛烈な台風30号 あす先島諸島接近 早めに対策を", "outcome": "not_reported", "outcome_justification": "The item reports an advisory before the event; no outcome is yet known.", "relevant": true, "review": false, "summary_en": "NHK reports that the Japan Meteorological Agency forecasts a large and very strong Typhoon No. 30 approaching the Sakishima Islands of Okinawa Prefecture on 23-24 October 2026, with winds possibly capable of collapsing some houses. JMA has urged residents to begin preparations early.", "summary_original": "大型で猛烈な台風30号は23日から24日土曜日ごろにかけて、沖縄県の先島諸島に近づく見込みです。一部の住宅が倒壊するような猛烈な風が吹くおそれがあり、気象庁は早めに対策を進めるよう呼びかけています。", "title_en": "Violent Typhoon No. 30 to approach Sakishima Islands tomorrow; early preparations urged", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3331,'claude-haiku-5-5','2026-10-22T03:20:24Z',1,0.9,0,'{"actions_taken": ["Issuance of a level 5 flood special warning (氾濫特別警報) for the Kohoku River", "Lifting of the special warning after flooding was confirmed"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-21", "event_location": "Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "秋田 子吉川に一時氾濫特別警報 川の増水など注意を", "outcome": "not_reported", "outcome_justification": "The snippet reports a special flood warning was issued and later lifted, but does not state whether warnings were received or acted upon or what the impacts were.", "relevant": true, "review": false, "summary_en": "Record heavy rain from a low-pressure system and front caused flooding on the Kohoku River in Akita Prefecture, prompting a temporary level 5 flood special warning. The special warning has since been lifted, but authorities urge continued caution due to high river levels and saturated ground.", "summary_original": "低気圧と前線の影響で記録的な大雨となった秋田県では、子吉川で氾濫が確認され、一時「レベル5氾濫特別警報」が発表された。特別警報は解除されたが、水位の高い川や緩んだ地盤への注意が呼びかけられている。", "title_en": "Akita: Special flood warning issued for Kohoku River; caution against rising rivers", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3340,'claude-haiku-5-5','2026-10-22T03:20:30Z',1,0.95,0,'{"actions_taken": ["Issued evacuation advisory (high-risk evacuation for elderly and others, warning level 3) to about 85,000 households / 19,000+ people across the whole city after a level 3 heavy rain warning was issued"], "agencies": [{"country": "JP", "name": "Hakui City government", "type": "other_national_agency"}, {"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-21", "event_location": "Hakui City, Ishikawa Prefecture, Japan", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": 19000}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "石川 羽咋市 高齢者等避難の情報", "outcome": "not_reported", "outcome_justification": "The snippet reports the advisory being issued but gives no information on its effects or on whether residents evacuated.", "relevant": true, "review": false, "summary_en": "Hakui City in Ishikawa Prefecture issued a high-risk evacuation advisory for the elderly and others covering the whole city, roughly 8,500 households and over 19,000 people, at 6 p.m. on 21 October after a level 3 heavy rain warning was issued for the city. The advisory corresponds to warning level 3 on Japan''s five-level alert scale. The snippet does not report outcomes.", "summary_original": "石川県羽咋市は、市内にレベル3大雨警報が発表されたことを受け、21日午後6時、市内全域のおよそ8500世帯1万9000人あまりに、高齢者等避難の情報を出しました。5段階の警戒レベルのうちレベル3に相当します。", "title_en": "Hakui City, Ishikawa: Evacuation advisory for elderly and others issued", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3341,'claude-haiku-5-5','2026-10-22T03:20:33Z',1,0.93,0,'{"actions_taken": ["JMA chief stated countermeasures for the error will be considered at a regular press conference"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Hokkaido to Tokai region, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "気象庁長官 緊急地震速報を誤発表「非常に遺憾 対策検討」", "outcome": "negative", "outcome_justification": "An erroneous earthquake early warning was issued across a wide area from Hokkaido to Tokai, and a previously implemented countermeasure reportedly failed again, indicating a shortcoming in the warning system.", "relevant": true, "review": false, "summary_en": "On 16 October 2026 the Japan Meteorological Agency issued an erroneous earthquake early warning over a wide area from Hokkaido to the Tokai region. JMA Director-General Ryuichi Nomura expressed deep regret at a press conference on 21 October, stating that a countermeasure adopted after a past incident had again failed, and said measures would be examined.", "summary_original": "今月16日、北海道から東海にかけての広い範囲で緊急地震速報を誤って発表したことについて、気象庁の野村竜一長官は21日の定例の会見で、過去の事例を受けて対策が取られたものが再度抜け落ちてしまったことを遺憾とし、対策を検討する考えを示した。", "title_en": "JMA chief expresses ''deep regret'' over erroneous earthquake early warning, says countermeasures will be considered", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3353,'claude-haiku-5-5','2026-10-22T03:21:15Z',1,0.8,0,'{"actions_taken": ["Level 5 flood special warning (氾濫特別警報) issued for the Koyoshi River on the night of 21 October"], "agencies": [{"country": "JP", "name": "Akita Prefectural Police", "type": "other_national_agency"}, {"country": "JP", "name": "Yurihonjo City Fire Department", "type": "other_national_agency"}, {"country": "JP", "name": "Akita Prefectural Government", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Yurihonjo, Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "秋田の河原で80代男性発見、心肺停止 子吉川で一時氾濫特別警報", "outcome": "negative", "outcome_justification": "An 80-something man was found in cardiac arrest on a riverbank in the city where a level 5 flood special warning had been issued the previous night, suggesting he was near the river despite the warning; the snippet does not state whether he was warned or evacuated.", "relevant": true, "review": false, "summary_en": "A man in his 80s was found face-down in cardiac arrest on a riverbank in Yurihonjo, Akita, where the Koyoshi River was under a level 5 flood special warning issued the previous night. He was taken to hospital. The report highlights the risk of people remaining near rivers during flood special warnings, though it does not say how the warning was communicated to him.", "summary_original": "秋田県由利本荘市で、21日夜に子吉川へレベル5の氾濫特別警報が出た中、河原でうつぶせに倒れていた80代男性が心肺停止の状態で発見され、病院に搬送された。", "title_en": "80-something man found in cardiac arrest on riverbank of Akita''s Koyoshi River amid level 5 flood special warning", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3410,'claude-haiku-5-5','2026-10-22T03:20:13Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Japan Weather Association", "type": "media"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-21", "event_location": "Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "雨雲レーダー(実況) / リアルタイムの雨雲 - 日本気象協会 tenki.jp", "outcome": "not_reported", "outcome_justification": "The snippet reports that JMA issued a flood emergency special warning (Level 5) for the Kozuki River in Akita Prefecture on 2026-10-21 at 19:59 and that it is in effect, but gives no information on actions taken or outcomes.", "relevant": true, "review": false, "summary_en": "A tenki.jp radar page displays that JMA has issued a flood emergency special warning for Akita Prefecture, including a Level 5 flood emergency special warning for the Kozuki River announced on 21 October 2026 at 19:59. The page relays the warning as a real-time alert, but the snippet provides no details on dissemination, response or impacts.", "summary_original": "気象庁は秋田県に氾濫特別警報を発表中と表示されている。子吉川に「レベル5氾濫特別警報」が10/21 19:59に発表されたという速報も掲載されている。", "title_en": "Real-time rain cloud radar - Japan Weather Association tenki.jp", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3411,'claude-haiku-5-5','2026-10-22T03:20:18Z',1,0.97,0,'{"actions_taken": ["Residents urged to ensure their personal safety"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Kyodo News", "type": "media"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Koyoshi River, Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "秋田の子吉川に氾濫特別警報 レベル5、気象庁（共同通信） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The item reports the issuance of a Level 5 flood emergency warning and a call for safety but gives no information on the outcome.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a Level 5 flood emergency warning (the highest alert level) for the Koyoshi River in Akita Prefecture on 21 October, urging residents to secure their safety. The warning was linked to a front bringing rain to the Tohoku region. The item does not report dissemination channels or subsequent outcomes.", "summary_original": "気象庁は21日、秋田県の子吉川にレベル5氾濫特別警報を出し、身の安全を確保するよう呼びかけた。前線の影響で東北を中心に雨が降っている。", "title_en": "Level 5 flood emergency warning issued for Akita''s Koyoshi River by Japan Meteorological Agency (Kyodo News)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3412,'claude-haiku-5-5','2026-10-22T03:20:21Z',1,0.95,0,'{"actions_taken": ["Residents urged to ensure their personal safety"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Kyodo News", "type": "media"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "秋田県の河川にレベル５氾濫特別警報", "outcome": "not_reported", "outcome_justification": "The snippet reports the issuance of the warning and the call to safety, but gives no information on whether residents acted or on resulting impacts.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a Level 5 flood special warning for the Kohoku River (子吉川) in Akita Prefecture on 21 October, indicating an imminent threat to life. The agency called on residents to secure their safety, as reported by Kyodo News.", "summary_original": "気象庁は21日、秋田県を流れる子吉川にレベル5氾濫特別警報を出し、命の危険が迫っている段階として身の安全の確保を呼びかけた。", "title_en": "Level 5 flood special warning issued for rivers in Akita Prefecture", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3413,'claude-haiku-5-5','2026-10-22T03:20:06Z',1,0.9,0,'{"actions_taken": ["JMA downgraded the Level 5 flood special warning for the Koyoshi River to a Level 2 flood advisory on 22 October", "Yurihonjo City lifted its emergency safety securing (緊急安全確保) order after water levels fell"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Yurihonjo City", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Yurihonjo, Akita, Japan", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "氾濫特別警報を注意報に切り替え", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning downgrade and lifting of the evacuation order after water levels dropped, but does not state whether the warnings were timely or effective, or what impacts occurred.", "relevant": true, "review": false, "summary_en": "JMA switched the Level 5 flood special warning issued for the Koyoshi River to a Level 2 flood advisory on 22 October 2026, after flooding had occurred in Yurihonjo City. The city reportedly lifted its emergency safety securing order because water levels had fallen.", "summary_original": "気象庁は22日、子吉川に出していたレベル5氾濫特別警報をレベル2氾濫注意報に切り替えた。由利本荘市は水位低下を理由に緊急安全確保を解除したと報じられている。", "title_en": "Flood special warning downgraded to flood advisory", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3417,'claude-haiku-5-5','2026-10-22T03:21:24Z',1,0.95,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Coastal central and southern Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "valid from Thursday 22 to Saturday 24 October 2026", "lead_time_hours": null, "original_title": "Lluvias se intensificarán en el sur: Senamhi emite alerta roja en seis regiones desde mañana", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of a red alert; no outcomes of the warning are described.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service SENAMHI issued a red alert for moderate to extreme rain and drizzle along the central and southern coast, valid from 22 to 24 October 2026, covering six regions. The alert is a formal official warning about intensifying rainfall.", "summary_original": "Senamhi emitió una alerta roja por lluvias y lloviznas de moderada a extrema intensidad en la costa centro y sur de Perú, con vigencia desde el jueves 22 hasta el sábado 24 de octubre.", "title_en": "Rains will intensify in the south: Senamhi issues red alert in six regions from tomorrow", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3418,'claude-haiku-5-5','2026-10-22T03:20:10Z',1,0.97,0,'{"actions_taken": ["Issued Meteorological Warning No. 429 at extreme danger level for precipitation in central and southern coast"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.97, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Ica, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "valid from Thursday 22 to Saturday 24 October 2026", "lead_time_hours": null, "original_title": "Alerta roja por lluvias en Ica y cinco regiones de la costa en pleno Niño Costero", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the warning; no outcomes are described.", "relevant": true, "review": false, "summary_en": "SENAMHI issued Meteorological Warning No. 429 with an extreme danger level for rainfall across the central and southern Peruvian coast, including Ica, valid from 22 to 24 October 2026. The warning is issued during a coastal El Niño episode. No impacts or responses are reported yet.", "summary_original": "SENAMHI emitió el Aviso Meteorológico 429 con nivel de peligro extremo por precipitaciones en la costa centro y sur, vigente del 22 al 24 de octubre de 2026, en pleno Niño Costero.", "title_en": "Red alert for rain in Ica and five coastal regions amid coastal El Niño", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3419,'claude-haiku-5-5','2026-10-22T03:20:36Z',1,0.95,0,'{"actions_taken": ["Senamhi activated red alert for rains in six coastal regions", "Alert sent via sensors and mobile phones to facilitate evacuation before a flood surge"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["mobile_app", "sms"], "event_date": "2026-10-21", "event_location": "Coastal regions, Peru", "event_name": "El Niño", "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El Niño pone en alerta al país: Senamhi activa alerta roja por lluvias en seis regiones", "outcome": "not_reported", "outcome_justification": "The snippet describes the alert issuance and its intended purpose but reports no results or outcomes.", "relevant": true, "review": false, "summary_en": "Senamhi, Peru''s national meteorological and hydrological service, activated a red alert for rains in six coastal regions linked to El Niño. An official said the alert, delivered via sensors and mobile phones, aims to facilitate evacuation before a flood surge.", "summary_original": "Senamhi activó alerta roja por lluvias en seis regiones costeras y un funcionario advirtió que la alerta por sensores y teléfonos móviles busca facilitar la evacuación antes de una crecida.", "title_en": "El Niño puts country on alert: Senamhi activates red alert for rains in six regions", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3420,'claude-haiku-5-5','2026-10-22T03:20:03Z',1,0.9,0,'{"actions_taken": ["Preventive evacuations in the Metropolitan Region, including encampments in Puente Alto", "Red Alert declared for the Metropolitan Region", "Preventive early alert maintained between O''Higgins and Los Lagos", "FIBE (damage/needs) forms issued"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Delegación Presidencial de la Región Metropolitana", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": ["other"], "event_date": "2026-10-21", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senapred reporta frente \"en desarrollo\": mantienen clases, RM en Alerta Roja y fichas FIBE", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and preventive evacuations but does not state results such as lives saved or shortcomings.", "relevant": true, "review": false, "summary_en": "Chile''s Senapred reported a developing frontal system, with preventive evacuations carried out in the Metropolitan Region, including encampments in Puente Alto, and the region placed under Red Alert. A preventive early alert remains in force between O''Higgins and Los Lagos, and FIBE forms were issued to record impacts.", "summary_original": "Senapred reporta que la delegación presidencial efectuó evacuaciones preventivas en la Región Metropolitana, incluyendo campamentos en Puente Alto, y que continúa vigente la alerta temprana preventiva entre O''Higgins y Los Lagos.", "title_en": "Senapred reports developing front: classes maintained, Metropolitan Region under Red Alert and FIBE forms", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3424,'claude-haiku-5-5','2026-10-22T03:22:18Z',1,0.93,0,'{"actions_taken": ["INDECI recommended preparedness measures in response to SENAMHI Meteorological Warning No. 428 (orange level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Southern highlands (sierra sur), Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "snow_ice", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante la ocurrencia de nevada en la sierra sur", "outcome": "not_reported", "outcome_justification": "The snippet describes recommendations and the warning issued but reports no outcomes.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures following SENAMHI Meteorological Warning No. 428 (orange level), which forecasts snowfall above 3900 m a.s.l. in the southern highlands of Peru. The item focuses on warning dissemination and preparedness advice ahead of the event.", "summary_original": "El INDECI recomienda adoptar medidas de preparación ante el Aviso Meteorológico N.° 428 del SENAMHI (nivel naranja), que informa sobre nevadas por encima de los 3900 m s. n. m. en la sierra sur del país.", "title_en": "INDECI recommends preparedness measures ahead of snowfall in the southern highlands", "wmo_regions": ["III"]}');
