INSERT INTO "classifications" VALUES(3899,'claude-haiku-5-5','2026-10-23T03:20:08Z',1,0.95,0,'{"actions_taken": ["JMA issued a linear precipitation band half-day-ahead forecast information (線状降水帯半日前予測) at 03:58 on 23 Oct"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Japan Weather Association (tenki.jp)", "type": "media"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-23", "event_location": "Miyako and Yaeyama regions, Okinawa Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about half a day (半日前予測) ahead of the expected event, from midday 23 Oct to early morning 24 Oct", "lead_time_hours": 12, "original_title": "【速報】沖縄県は23日昼過ぎから24日明け方にかけて「線状降水帯」発生の可能性(気象予報士 日直主任 2026年10月23日) - 日本気象協会 tenki.jp", "outcome": "not_reported", "outcome_justification": "The item only reports the forecast/advisory issuance; no outcome of the event is stated.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a half-day-ahead linear precipitation band forecast at 03:58 on 23 October 2026, indicating possible formation of a linear precipitation band over the Miyako and Yaeyama regions of Okinawa from midday on the 23rd to early morning on the 24th. The item, published by Japan Weather Association tenki.jp, relays this JMA advisory as a forecaster briefing. No impacts or outcomes are reported.", "summary_original": "気象庁は23日3時58分に線状降水帯半日前予測を発表し、沖縄県宮古島地方と八重山地方で23日昼過ぎから24日明け方にかけて線状降水帯が発生する可能性を示した。", "title_en": "[Breaking] Okinawa Prefecture may see linear precipitation bands (senjō kōsuitai) from midday on the 23rd to early morning on the 24th (Weather forecaster duty chief, 23 October 2026) - Japan Weather Association tenki.jp", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3900,'claude-haiku-5-5','2026-10-23T03:20:20Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "San''in Chuo Shimbun", "type": "media"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-23", "event_location": "Okinawa, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "half a day ahead", "lead_time_hours": 12, "original_title": "全般気象解説情報（線状降水帯半日前予測）（第１報）＝気象庁発表（２３日３時５８分） ：気象解説情報", "outcome": "not_reported", "outcome_justification": "The item reports a JMA forecast warning of possible linear precipitation band formation over Okinawa; no outcomes are described.", "relevant": true, "review": false, "summary_en": "JMA issued the first general weather commentary with a half-day advance forecast of linear precipitation bands, stating that linear precipitation bands may form over the Okinawa region and sharply raise the risk of heavy rain disasters. The item reports the forecast advisory itself, with no information on dissemination reach or impacts.", "summary_original": "気象庁は2026年10月23日3時58分に全般気象解説情報（線状降水帯半日前予測）第1報を発表し、沖縄地方で線状降水帯が発生し大雨災害の危険度が急激に高まる可能性を示した。", "title_en": "General Weather Commentary (Half-day Advance Forecast of Linear Precipitation Bands) No.1 issued by JMA (23 Oct 03:58)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3901,'claude-haiku-5-5','2026-10-23T03:20:17Z',1,0.97,0,'{"actions_taken": ["Residents urged to take immediate life-protecting action"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "秋田・子吉川にレベル5「氾濫特別警報」｜Infoseekニュース", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning and call to action but gives no information on whether flooding occurred or what the outcome was.", "relevant": true, "review": false, "summary_en": "A level 5 flood emergency special warning was issued for the Kokai River in Akita Prefecture, stating that inundation has very likely already occurred. Residents were urged to take immediate action to protect their lives. The snippet does not report the subsequent impacts or the effectiveness of the warning.", "summary_original": "秋田県を流れる子吉川にレベル5「氾濫特別警報」が発表され、すでに氾濫が発生している可能性が極めて高いとして、ただちに命を守る行動を取るよう呼びかけられました。", "title_en": "Level 5 \"flood emergency special warning\" issued for Kokai River in Akita", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3902,'claude-haiku-5-5','2026-10-23T03:20:00Z',1,0.95,0,'{"actions_taken": ["JMA and MLIT held emergency press conference", "Special flood warning (level 5 flood emergency warning) issued for Kozukawa river in Akita Prefecture"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Ministry of Land, Infrastructure, Transport and Tourism (MLIT)", "type": "other_national_agency"}, {"country": "JP", "name": "Nippon TV NEWS NNN", "type": "media"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Akita Prefecture, Japan", "event_name": "Typhoon Hagibis-type event (typhoon No. 30, 2026)", "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "気象庁と国交省が緊急会見 秋田で記録的大雨「警報級が続く可能性高い」“原因の1つ”に台風30号（日テレNEWS NNN） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The snippet reports the warnings and emergency press conference but gives no information on whether they were received or acted upon or on their effects.", "relevant": true, "review": false, "summary_en": "A typhoon (No. 30) interacting with a front caused localised heavy rain in Japan, prompting a level 5 flood emergency warning for the Kozukawa river in Akita Prefecture. JMA and MLIT held an emergency press conference warning that warning-level conditions were likely to continue. The snippet gives no details on dissemination or outcomes.", "summary_original": "猛烈な台風30号が前線を刺激して各地で局地的な大雨が降り、秋田県の子吉川にレベル5氾濫特別警報が出された。気象庁と国交省が緊急会見を行った。", "title_en": "Japan Meteorological Agency and MLIT hold emergency press conference; record heavy rain in Akita, ''warning-level conditions likely to continue'', typhoon No. 30 cited as