INSERT INTO "classifications" VALUES(3913,'claude-haiku-5-5','2026-10-23T03:22:00Z',1,0.7,0,'{"actions_taken": [], "agencies": [{"country": "PY", "name": "Secretaría de Emergencia Nacional (SEN)", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Paraguay", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": 5000, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SEN advierte que la crisis por inundaciones recién comienza", "outcome": "not_reported", "outcome_justification": "The snippet reports river flooding affecting about 5,000 families and a warning that conditions may worsen, but does not describe the warnings issued, their dissemination, or any outcome.", "relevant": true, "review": false, "summary_en": "The national emergency secretariat (SEN) reported that about 5,000 families are affected by rising rivers in several parts of Paraguay and warned that the situation could worsen in coming months. The item centres on the official outlook for the flood situation rather than on specific warnings or their dissemination.", "summary_original": "El ministro de la SEN, Arsenio Zárate, informó que unas 5.000 familias resultan afectadas por la crecida de los ríos y advirtió que el escenario podría empeorar en los próximos meses.", "title_en": "SEN warns the flood crisis has only just begun", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3914,'claude-haiku-5-5','2026-10-23T03:22:03Z',1,0.8,0,'{"actions_taken": ["Monitoring of river rise", "Cleaning of drainage channels", "Survey of 600 families potentially at risk"], "agencies": [{"country": "AR", "name": "Comuna de Arroyo Leyes", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Arroyo Leyes, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Arroyo Leyes monitorea la crecida del río: realiza tareas de prevención y relevó a 600 familias que podrían estar en riesgo", "outcome": "not_reported", "outcome_justification": "The snippet describes monitoring and preparedness actions but does not report the outcome of any warning or flood event.", "relevant": true, "review": false, "summary_en": "The commune of Arroyo Leyes is monitoring a river rise and carrying out prevention work, including cleaning drainage channels, amid rain forecasts linked to El Niño. Local authorities identified the western section of provincial route 1 as most vulnerable due to lack of flood defences, and surveyed about 600 families who could be at risk.", "summary_original": "La comuna de Arroyo Leyes monitorea la crecida del río y realiza tareas de prevención, incluyendo la limpieza de canales y el relevamiento de 600 familias en riesgo ante los pronósticos de lluvia asociados a El Niño.", "title_en": "Arroyo Leyes monitors river rise: carries out prevention tasks and surveyed 600 families who could be at risk", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3915,'claude-haiku-5-5','2026-10-23T03:22:09Z',1,0.7,0,'{"actions_taken": [], "agencies": [{"country": "PY", "name": "Secretaría de Emergencia Nacional (SEN)", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Paraguay", "event_name": null, "ew4all_pillars": [2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "3.000 familias son damnificadas en Paraguay por inundaciones, según la SEN", "outcome": "not_reported", "outcome_justification": "The item reports flood damage to 3,000 families and warns the situation could worsen with El Niño, but does not describe warnings issued, their dissemination, or actions taken.", "relevant": true, "review": false, "summary_en": "The national emergency secretariat (SEN) of Paraguay reported that 3,000 families were affected by river flooding at several points in the country. Its head warned the situation could deteriorate as the El Niño phenomenon advances, which points to an advisory element relevant to early warning.", "summary_original": "El titular de la SEN, Arsenio Zárate, informó que 3.000 familias resultaron damnificadas por la crecida de los ríos y advirtió que el escenario podría empeorar con el avance de El Niño.", "title_en": "3,000 families affected in Paraguay by floods, according to the SEN", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3916,'claude-haiku-5-5','2026-10-23T03:22:26Z',1,0.7,0,'{"actions_taken": [], "agencies": [], "confidence": 0.7, "countries": ["US"], "dissemination_channels": ["tv"], "event_date": "2026-10-22", "event_location": "Southern California, United States", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tormenta de octubre amenaza al sur de California con fuertes lluvia", "outcome": "not_reported", "outcome_justification": "The item only reports an approaching storm threatening heavy rain; no outcome of warnings is given.", "relevant": true, "review": false, "summary_en": "A Spanish-language Telemundo news item reports that an October storm threatens Southern California with heavy rain. The snippet is empty, so the specific forecasts, warnings and dissemination details cannot be verified from the available information.", "summary_original": "Una tormenta de octubre amenaza con fuertes lluvias al sur de California, según reporta Telemundo.", "title_en": "October storm threatens Southern California with heavy rain", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(3918,'claude-haiku-5-5','2026-10-23T03:22:31Z',1,0.85,0,'{"actions_taken": ["Confirmation of tornado in Maule", "Issuance of warning that frontal system will persist with rain and electrical storms until Friday", "Reporting of damaged, sheltered and isolated persons across several regions"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Maule Region, Chile", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senapred confirma tornado en el Maule y advierte que sistema frontal mantendrá lluvias y tormentas eléctricas hasta el viernes", "outcome": "not_reported", "outcome_justification": "The snippet reports a warning of continued rain and storms and damage balances, but does not state whether warnings led to timely actions or their effectiveness.", "relevant": true, "review": false, "summary_en": "Chile''s civil protection agency Senapred confirmed a tornado in the Maule region and warned that a frontal system would bring continued rain and thunderstorms until Friday. Its latest balance reported 31 people displaced, 178 sheltered and 40 isolated in Coquimbo due to rising rivers.", "summary_original": "Senapred confirmó un tornado en la Región del Maule y advirtió que un sistema frontal mantendrá lluvias y tormentas eléctricas hasta el viernes. El balance reporta 31 damnificados, 178 albergados y 40 aislados en Coquimbo por la crecida de ríos.", "title_en": "Senapred confirms tornado in Maule and warns frontal system will keep rain and thunderstorms until Friday", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3919,'claude-haiku-5-5','2026-10-23T03:21:14Z',1,0.9,0,'{"actions_taken": ["DMH director Eduardo Mingo confirmed the arrival of heavy rains in national territory and publicised the forecast of rainfall affecting much of the country"], "agencies": [{"country": "PY", "name": "Dirección de Meteorología e Hidrología (DMH), Paraguay", "type": "NMHS"}], "confidence": 0.9, "countries": ["PY"], "dissemination_channels": ["other"], "event_date": "2026-10-21", "event_location": "Paraguay", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "several days (heavy rain expected across the week and reaching Asunción at the weekend)", "lead_time_hours": null, "original_title": "Alerta meteorológica: fuertes lluvias ya ingresaron al país y llegarán a Asunción el fin de semana - Clima", "outcome": "not_reported", "outcome_justification": "The snippet describes a forecast warning issued by the NMHS but reports no outcome, impacts or response results.", "relevant": true, "review": false, "summary_en": "Paraguay''s Directorate of Meteorology and Hydrology (DMH) director Eduardo Mingo confirmed that heavy rains forecast to affect much of the country from the day of publication and through the week have already entered national territory, with arrival expected in Asunción at the weekend. The item is an NMHS warning communicated through the media, with no reported outcomes.", "summary_original": "El director de Meteorología e Hidrología, Eduardo Mingo, confirmó que las fuertes lluvias que azotarían a gran parte del país a partir de hoy y durante la semana ya ingresaron a territorio nacional.", "title_en": "Weather alert: heavy rains have already entered the country and will reach Asunción at the weekend", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3921,'claude-haiku-5-5','2026-10-23T03:20:55Z',1,0.93,0,'{"actions_taken": ["Municipality reinforced prevention works", "Residents urged to take extra precautions"], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional (SMN)", "type": "NMHS"}, {"country": "AR", "name": "Municipality of Rosario", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["AR"], "dissemination_channels": ["other"], "event_date": "2026-10-22", "event_location": "Rosario, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "same day (afternoon forecast, warnings extended into the night)", "lead_time_hours": null, "original_title": "Elevan a naranja el alerta por tormentas para este jueves en Rosario: advierten por lluvias intensas, granizo y ráfagas", "outcome": "not_reported", "outcome_justification": "The snippet describes the upgraded orange alert and preventive measures but reports no outcomes of the warning.", "relevant": true, "review": false, "summary_en": "The Argentine meteorological service upgraded its storm alert to orange for Rosario, forecasting rainfall of up to 100 mm, hail and winds of 90 km/h for the afternoon and night of Thursday. The municipality reinforced prevention work and asked residents to take extra care.", "summary_original": "El Servicio Meteorológico agravó el pronóstico para la tarde y extendió las advertencias hasta la noche, con lluvias de hasta 100 mm y vientos de 90 km/h. El municipio reforzó la prevención y pidió a los vecinos extremar cuidados.", "title_en": "Orange storm alert raised for this Thursday in Rosario: warnings of intense rain, hail and gusts", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3922,'claude-haiku-5-5','2026-10-23T03:22:48Z',0,0.3,1,'{"actions_taken": [], "agencies": [], "confidence": 0.3, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Paraná: quedan 200.000 cabezas de ganado en las islas santafesinas", "outcome": "not_reported", "outcome_justification": "The title describes livestock remaining in flooded islands but gives no information about warnings, forecasts or dissemination; snippet is empty.", "relevant": false, "review": true, "summary_en": "The headline reports a Paraná River flood with around 200,000 cattle still on islands in Santa Fe province. No information about monitoring, forecasts or warnings is available from the title and empty snippet, so the item cannot be judged as relevant to early warning services.", "summary_original": "Crecida del Paraná: quedan 200.000 cabezas de ganado en las islas santafesinas. El titular describe ganado aún en las islas tras la crecida, sin mencionar alertas ni pronósticos.", "title_en": "Paraná River flood: 200,000 head of cattle remain on the Santa Fe islands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3924,'claude-haiku-5-5','2026-10-23T03:21:17Z',1,0.6,0,'{"actions_taken": ["Lessons on prevention discussed in anniversary coverage"], "agencies": [], "confidence": 0.6, "countries": ["MX"], "dissemination_channels": [], "event_date": "2005-10-21", "event_location": "Cancún, Quintana Roo, Mexico", "event_name": "Hurricane Wilma", "ew4all_pillars": [1], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": "18,773 million pesos", "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Huracán Wilma: Cancún recuerda 21 años del ciclón que devastó Quintana Roo", "outcome": "not_reported", "outcome_justification": "The item is a retrospective anniversary piece; it mentions losses and prevention lessons but no specific warning actions or outcomes for the 2005 event are given in the snippet.", "relevant": true, "review": false, "summary_en": "A retrospective article marking 21 years since Hurricane Wilma struck Cancún and Quintana Roo in 2005, recalling damage and economic losses of about 18,773 million pesos and highlighting prevention lessons. The snippet does not detail the forecasts, warnings or dissemination used during the event.", "summary_original": "Artículo retrospectivo que recuerda los 21 años del paso del huracán Wilma por Cancún y Quintana Roo en 2005, con pérdidas por 18 mil 773 millones de pesos y lecciones de prevención.", "title_en": "Hurricane Wilma: Cancún remembers 21 years since the cyclone that devastated Quintana Roo", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(3926,'claude-haiku-5-5','2026-10-23T03:22:51Z',1,0.8,0,'{"actions_taken": ["Monitoring of the river rise", "Cleaning of drainage channels", "Relocation of around 600 families potentially at risk"], "agencies": [{"country": "AR", "name": "Comuna de Arroyo Leyes", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Arroyo Leyes, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Arroyo Leyes monitora la crecida del río: realiza tareas de prevención y relevó a 600 familias que podrían estar en riesgo", "outcome": "not_reported", "outcome_justification": "The article describes monitoring and preventive actions in progress; no outcome has been reported yet.", "relevant": true, "review": false, "summary_en": "The local government of Arroyo Leyes is monitoring a rising river and carrying out prevention work, including channel cleaning, in anticipation of rain linked to El Niño forecasts. About 600 families that could be at risk have been relocated, with the western sector of provincial route 1 identified as most vulnerable due to lack of defences.", "summary_original": "La comuna de Arroyo Leyes monitorea la crecida del río y realiza tareas de limpieza de canales y prevención ante pronósticos de lluvia asociados a El Niño; se relevó a 600 familias que podrían estar en riesgo, siendo el sector oeste de la ruta provincial 1 el más vulnerable.", "title_en": "Arroyo Leyes monitors river rise: carries out prevention tasks and identifies 600 families that could be at risk", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(3927,'claude-haiku-5-5','2026-10-23T03:22:55Z',0,0.8,0,'{"actions_taken": ["Forced livestock sales to save animals from evacuated areas"], "agencies": [{"country": "AR", "name": "Federación Agraria", "type": "NGO"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["radio"], "event_date": "2026-10-21", "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta por El Niño en el campo: piden suspender Ganancias a la venta de hacienda evacuada", "outcome": "not_reported", "outcome_justification": "The item reports economic pressure from forced livestock sales and a projected calf shortage, but no outcome of warnings is described.", "relevant": false, "review": false, "summary_en": "An agrarian federation in Argentina warned on radio that El Niño has reached a critical stage, forcing distress sales of evacuated livestock and projecting a shortage of calves next year. The federation asks for suspension of the Ganancias tax on these sales. The item concerns economic effects and does not describe warning issuance or dissemination.", "summary_original": "Desde la Federación Agraria señalaron en Radio 2 que el fenómeno ya ingresó en una etapa crítica. Advierten que se trata de ''ventas forzosas'' para salvar los animales y prevén un faltante de terneros para el año que viene.", "title_en": "El Niño alert in the countryside: calls to suspend Ganancias tax on sale of evacuated livestock", "wmo_regions": ["III"]}');
