INSERT INTO "classifications" VALUES(3952,'claude-haiku-5-5','2026-10-23T03:20:04Z',1,0.95,0,'{"actions_taken": ["Cancelled two red alerts in the Metropolitan Region", "Declared Yellow Alert for 10 pre-Andean communes due to mass movement (remoción en masa)", "Issued Preventive Early Alert for the whole region for possible thunderstorms, hail and strong winds"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Región Metropolitana, Chile", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "forecast for Thursday and Friday", "lead_time_hours": null, "original_title": "RM queda en Alerta Preventiva tras fuertes lluvias: comunas precordilleranas siguen \"amarillas\"", "outcome": "not_reported", "outcome_justification": "The item reports warning levels and their basis but no outcomes of the warnings.", "relevant": true, "review": false, "summary_en": "Chile''s Senapred cancelled two red alerts in the Metropolitan Region and downgraded the region to a Preventive Early Alert for possible thunderstorms, hail and strong winds, based on the forecast for Thursday and Friday. Ten pre-Andean communes remain under Yellow Alert for mass movement risk. The item reports warning levels but not their outcomes.", "summary_original": "Senapred canceló dos alertas rojas en la Región Metropolitana y declaró Alerta Amarilla para 10 comunas precordilleranas por remoción en masa, junto con Alerta Temprana Preventiva para toda la región ante posibles tormentas eléctricas, granizos y vientos fuertes.", "title_en": "Metropolitan Region downgraded to Preventive Alert after heavy rain; pre-Andean communes remain yellow", "wmo_regions": ["III"]}');
