INSERT INTO "classifications" VALUES(4890,'claude-haiku-5-5','2026-10-25T04:17:49Z',1,0.9,0,'{"actions_taken": ["Broadcast of typhoon information and forecast of linear rainband (senjou kōsuitai) just before Wakayama"], "agencies": [{"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["tv"], "event_date": "2026-10-25", "event_location": "Wakayama, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "not stated", "lead_time_hours": null, "original_title": "【台風30号情報】 前線活動活発に 和歌山に線状降水帯直前予測", "outcome": "not_reported", "outcome_justification": "The snippet reports forecasts and conditions but does not describe outcomes of the warnings.", "relevant": true, "review": false, "summary_en": "NHK reports that the large Typhoon No. 30, moving northeast over the East China Sea, is pumping warm moist air toward a front, making the atmosphere very unstable across western and eastern Japan. A heavy rainfall band (senjō kōsuitai) is forecast just before Wakayama, with very heavy rain expected in western Japan, indicating forecast and warning communication by broadcast media.", "summary_original": "大型の台風30号が東シナ海を北東へ進み、前線に向けて暖かく湿った空気が流入し、西日本と東日本で大気が非常に不安定になっている。西日本では非常に激しい雨が予想され、和歌山では線状降水帯が直前に予測されている。", "title_en": "[Typhoon No. 30 information] Active frontal activity; heavy rain band forecast just before Wakayama", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4894,'claude-haiku-5-5','2026-10-25T04:17:53Z',1,0.9,0,'{"actions_taken": ["Issued earthquake information with seismic intensity observations and tsunami assessment (no tsunami concern)"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["tv", "website"], "event_date": "2026-10-25", "event_location": "Western off-shore of Ogasawara Islands, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "【地震速報】小笠原で震度3 津波の心配なし", "outcome": "not_reported", "outcome_justification": "The item reports the earthquake detection and the tsunami assessment but does not describe any impacts or the effect of the warnings.", "relevant": true, "review": false, "summary_en": "A deep earthquake west of the Ogasawara Islands at about 11:10 local time on 25 October produced seismic intensity 3 in the Ogasawara Islands and intensity 1-2 across a wide area from Tohoku to Tokai. The early earthquake information stated there was no tsunami concern.", "summary_original": "25日午前11時10分ごろ、小笠原諸島西方沖の深い場所を震源とする地震があり、小笠原諸島で震度3の揺れを観測したほか、東北から東海にかけての広い範囲で震度2や1の揺れを観測しました。この地震による津波の心配はないとされています。", "title_en": "[Earthquake alert] Seismic intensity 3 in Ogasawara, no tsunami concern", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(4943,'claude-haiku-5-5','2026-10-25T04:17:23Z',1,0.97,0,'{"actions_taken": ["JMA issued a linear rainband immediate forecast (線状降水帯直前予測) for northern Wakayama Prefecture at 10:58 on 25 October", "JMA called for caution about very heavy rain persisting in the same area"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Mainichi Shimbun", "type": "media"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Northern Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "和歌山県北部に線状降水帯直前予測 気象庁が注意呼びかけ", "outcome": "not_reported", "outcome_justification": "The snippet reports only the issuance of the forecast and call for caution; no outcome or impacts are described.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a linear rainband immediate forecast for northern Wakayama Prefecture at 10:58 on 25 October, warning that a linear rainband could form within three hours and bring persistently very heavy rain to the same area. JMA called on residents to remain cautious. The item covers the forecast and warning issuance only, with no reported outcomes.", "summary_original": "気象庁は25日午前10時58分、和歌山県北部に線状降水帯直前予測を出した。今後3時間以内に線状降水帯が発生し、同じ場所で非常に激しい雨が降り続く可能性が高まっているとして注意を呼び掛けている。", "title_en": "Japan Meteorological Agency issues linear rainband immediate forecast for northern Wakayama Prefecture, calls for caution", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4956,'claude-haiku-5-5','2026-10-25T04:17:27Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "approximately 48 hours before possible approach to Kyushu (forecast issued 24 October for 26 October)", "lead_time_hours": 48, "original_title": "台風３０号 、 先島諸島北方を北上へ 西日本は前線で大雨警戒 ― 気象庁 ： 時事ドットコム", "outcome": "not_reported", "outcome_justification": "The item reports JMA forecasts of the typhoon''s track and expected transition to an extratropical cyclone, but no outcome or impacts are yet reported.", "relevant": true, "review": false, "summary_en": "JMA reported that the large Typhoon No. 30 was north of the Sakishima Islands on 24 October and expected to move north over the East China Sea by 25 October, possibly approaching Kyushu by the morning of 26 October. It is forecast to become an extratropical cyclone by the morning of 27 October, while heavy rain alerts are in place for western Japan due to a front.", "summary_original": "大型の台風３０号は２４日午前、沖縄県・先島諸島の北方海上にあり、２５日にかけて東シナ海を北上する見通しとなった。気象庁によると、２６日午前に九州に接近する恐れがあり、２７日午前までに温帯低気圧に変わって西・東日本の太平洋沖に進むと予想される。", "title_en": "Typhoon No. 30 moves north of the Sakishima Islands; heavy rain warned for western Japan due to front — Japan Meteorological Agency", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4957,'claude-haiku-5-5','2026-10-25T04:17:56Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Oita Prefecture, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "expected from the evening of 25 October (about 1 day ahead of the report)", "lead_time_hours": null, "original_title": "台風30号 、 大分県内25日夕方から強風域に入る見込み 警報級の大雨が降る可能性 - 大分のニュースなら 大分合同新聞プレミアムオンライン Gate", "outcome": "not_reported", "outcome_justification": "The item reports forecast expectations of strong winds and possible warning-level heavy rain; no observed outcome is given.", "relevant": true, "review": false, "summary_en": "A regional newspaper reports that Typhoon No. 30 is expected to enter the strong wind zone over Oita Prefecture from the evening of 25 October, with possible warning-level heavy rain. The item is a forecast-based news report on the typhoon''s expected approach, with no information on warnings issued, dissemination, or outcomes.", "summary_original": "台風30号が25日夕方から大分県内で強風域に入る見込みで、警報級の大雨が降る可能性があると報じられている。", "title_en": "Typhoon No. 30 expected to enter strong wind area in Oita Prefecture from the evening of the 25th; possible warning-level heavy rain", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4958,'claude-haiku-5-5','2026-10-25T04:17:36Z',1,0.9,0,'{"actions_taken": ["JMA forecast that the typhoon may approach Kyushu on the 26th and transition to an extratropical cyclone toward the Shikoku offshore", "JMA warned of heavy rain risk for eastern and western Japan from the stationary front"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-26", "event_location": "Kyushu, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 2 days before expected approach to Kyushu", "lead_time_hours": 48, "original_title": "台風３０号 、 ２６日に九州接近か 東 ・ 西日本は前線で大雨警戒 ― 気象庁 ： 時事ドットコム", "outcome": "not_reported", "outcome_justification": "The item reports only forecasts and warnings issued; no outcomes or impacts are described.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency reported that large Typhoon No. 30, which moved north over the sea north of the Sakishima Islands on the 24th, may approach Kyushu on the 26th. It is expected to become an extratropical cyclone and move toward the Shikoku offshore. Heavy rain warnings were also issued for eastern and western Japan due to a stationary front.", "summary_original": "大型の台風３０号は２４日午後、沖縄県・先島諸島の北方海上を北上。気象庁によると２６日に九州に接近する恐れがあり、その後は温帯低気圧に変わって四国沖へ進む見込み。東・西日本は前線停滞の影響で大雨に警戒が必要。", "title_en": "Typhoon No. 30 may approach Kyushu on the 26th; heavy rain warned for eastern and western Japan due to front — Japan Meteorological Agency", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4959,'claude-haiku-5-5','2026-10-25T04:19:33Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan; Kyushu, Japan", "event_name": null, "ew4all_pillars": [2], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 2 days before expected Kyushu landfall (forecast for 26 October)", "lead_time_hours": 48, "original_title": "台風３０号 、 週明け九州接近か 東シナ海を東進へ: 主要: 福島民友新聞社", "outcome": "not_reported", "outcome_justification": "The article reports the forecast track and expected landfall timing of the typhoon, but no outcome of the warnings is given.", "relevant": true, "review": false, "summary_en": "A large Typhoon No. 30 approached the Sakishima Islands of Okinawa on 24 October and is forecast to turn east over the East China Sea, approaching and making landfall on Kyushu around 26 October, then moving toward the Shikoku offshore area by about 27 October. The report conveys a multi-day track forecast for the typhoon as a whole.", "summary_original": "大型の台風30号は24日、沖縄の先島諸島に接近した。北上して東シナ海で進路を東寄りに変え、26日に九州へ接近、上陸する見込みと報じられている。", "title_en": "Typhoon No. 30 may approach Kyushu early next week, moving east across the East China Sea", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4960,'claude-haiku-5-5','2026-10-25T04:18:05Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-26", "event_location": "Kyushu, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 2 days before expected landfall (forecast issued on Friday for Monday landfall)", "lead_time_hours": 48, "original_title": "強い台風30号は月曜日に九州上陸へ 土曜日と日曜日は九州～関東で警報級の大雨", "outcome": "not_reported", "outcome_justification": "The item only reports forecasts of landfall and advisory-level heavy rain; no outcome is yet reported.", "relevant": true, "review": false, "summary_en": "News reports that a strong Typhoon No. 30 is forecast to make landfall in Kyushu on Monday, with heavy rain of warning-level intensity expected from Kyushu to the Kanto region on Saturday and Sunday. The item centres on forecast information issued ahead of the event, with no reported dissemination actions or outcomes yet.", "summary_original": "強い台風30号は月曜日に九州に上陸する見込みで、土曜日と日曜日には九州から関東にかけて警報級の大雨が予想されるとの予報を伝えるニュース。", "title_en": "Strong Typhoon No. 30 expected to make landfall in Kyushu on Monday; heavy rain warnings-level in Kyushu to Kanto on Saturday and Sunday", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4961,'claude-haiku-5-5','2026-10-25T04:18:46Z',1,0.9,0,'{"actions_taken": ["Issued land typhoon warning", "Forecast weakening to light typhoon and lifting of land warning by evening", "Reported casualty figures"], "agencies": [{"country": "TW", "name": "Central Weather Administration (CWA)", "type": "NMHS"}, {"country": "TW", "name": "Central Disaster Response Center", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["TW"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Taiwan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": 1, "economic_losses": null, "evacuated": null, "injured": 527, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風30号 、 夕方にも陸上警報解除の見通し 1人死亡 、 527人けが ／ 台湾", "outcome": "not_reported", "outcome_justification": "The item reports casualties (1 dead, 527 injured) but does not state whether warnings led to preventive actions or whether they were late, missed, or effective.", "relevant": true, "review": false, "summary_en": "Taiwan''s Central Weather Administration said Typhoon No. 30 (designated No. 29 by CWA) approached Taiwan from the afternoon of 23 October into 24 October, and expected it to weaken to a light typhoon by afternoon and lift the land typhoon warning by evening of 24 October. The Central Disaster Response Center reported 1 death and 527 injuries nationwide.", "summary_original": "台風30号（中央気象署の発表では29号）は23日午後から24日午前にかけて台湾に接近。中央気象署は24日午後に軽度台風へ弱まり、夕方ごろに陸上台風警報を解除する見通しを示した。中央災害対策センターは台風により1人死亡、527人けがと発表した。", "title_en": "Typhoon No. 30 expected to be lifted from land warning by evening; 1 dead, 527 injured in Taiwan", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4962,'copied','2026-10-25T04:20:33Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "approximately 48 hours before possible approach to Kyushu (forecast issued 24 October for 26 October)", "lead_time_hours": 48, "original_title": "台風３０号 、 先島諸島北方を北上へ 西日本は前線で大雨警戒 ― 気象庁 ： 時事ドットコム", "outcome": "not_reported", "outcome_justification": "The item reports JMA forecasts of the typhoon''s track and expected transition to an extratropical cyclone, but no outcome or impacts are yet reported.", "relevant": true, "review": false, "summary_en": "JMA reported that the large Typhoon No. 30 was north of the Sakishima Islands on 24 October and expected to move north over the East China Sea by 25 October, possibly approaching Kyushu by the morning of 26 October. It is forecast to become an extratropical cyclone by the morning of 27 October, while heavy rain alerts are in place for western Japan due to a front.", "summary_original": "大型の台風３０号は２４日午前、沖縄県・先島諸島の北方海上にあり、２５日にかけて東シナ海を北上する見通しとなった。気象庁によると、２６日午前に九州に接近する恐れがあり、２７日午前までに温帯低気圧に変わって西・東日本の太平洋沖に進むと予想される。", "title_en": "Typhoon No. 30 moves north of the Sakishima Islands; heavy rain warned for western Japan due to front — Japan Meteorological Agency", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4963,'claude-haiku-5-5','2026-10-25T04:19:41Z',1,0.93,0,'{"actions_taken": ["JMA called for strict vigilance against gales and high waves", "Warnings issued for landslides and low-lying flooding in northern Kyushu through 26 October"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "approximately 2 days before expected approach to western Japan (around 26 October)", "lead_time_hours": 48, "original_title": "台風３０号 、 東シナ海を北上 週明けに西日本接近", "outcome": "not_reported", "outcome_justification": "The article describes forecasts and warnings issued in advance; no outcome has been reported yet.", "relevant": true, "review": false, "summary_en": "JMA warned of violent winds, high waves and swells as Typhoon No. 30 approached the Sakishima Islands, and forecast its turn toward western Japan. Warnings for landslides and flooding were issued for northern Kyushu through 26 October, with forecasts of up to 250 mm of 24-hour rainfall there.", "summary_original": "気象庁は台風30号が先島諸島に接近するなか、暴風や高波に厳重な警戒を呼びかけ、九州北部では26日にかけて土砂災害や浸水への警戒を求めた。", "title_en": "Typhoon No. 30 moves north through East China Sea, approaches western Japan next week", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4964,'claude-haiku-5-5','2026-10-25T04:18:11Z',1,0.95,0,'{"actions_taken": ["JMA warned of landslides, low-lying flooding, river rises and high waves across western and eastern Japan and Okinawa", "Okinawa Prefecture reported a fatal incident caused by strong winds in Miyako Island"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Okinawa Prefectural Government", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": 1, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 2 days before expected landfall in Kyushu (26 October)", "lead_time_hours": 48, "original_title": "台風30号が東シナ海を北上 、 週明けに西日本接近 暴風 ・ 高波に警戒", "outcome": "not_reported", "outcome_justification": "Warnings were issued in advance, but the article does not report whether they were received or acted upon; a fatality from strong winds is reported on Miyako Island.", "relevant": true, "review": false, "summary_en": "Japan Meteorological Agency forecasts Typhoon No. 30 to approach Kyushu on 26 October and transition to an extratropical low off Shikoku, while the front intensifies. JMA urged heightened vigilance for landslides, low-lying flooding, river rises and high waves across western and eastern Japan and Okinawa. A 70-year-old woman died after being blown over by strong winds in Miyako Island on 22 October.", "summary_original": "大型の台風30号が沖縄先島諸島を通過後、26日に九州へ上陸する見込みで、気象庁は西―東日本と沖縄で土砂災害や浸水、河川増水、高波に厳重警戒を呼びかけた。", "title_en": "Typhoon No. 30 moves north through East China Sea; approaches western Japan next week, warnings for strong winds and high waves", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4965,'claude-haiku-5-5','2026-10-25T04:18:17Z',1,0.95,0,'{"actions_taken": ["Storm warnings maintained for Miyako and Yaeyama islands", "Announcement that a linear rainband (senjo kosuitai) may form within 3 hours over the Ishigaki region"], "agencies": [{"country": "JP", "name": "Okinawa District Meteorological Observatory (Japan Meteorological Agency)", "type": "NMHS"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Yonaguni and Ishigaki, Okinawa, Japan", "event_name": "Typhoon Nos. 30 and 31 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours (heavy rainband warning for Ishigaki region)", "lead_time_hours": 3, "original_title": "大型で強い台風30号 、 与那国北方で停滞 宮古 ・ 八重山で暴風警報続く 台風31号も発生", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and advisories issued but does not describe impacts or how warnings were received or acted upon.", "relevant": true, "review": false, "summary_en": "Large Typhoon No. 30 was moving slowly east about 50 km north-northeast of Yonaguni, and storm warnings remained in effect for Miyako and Yaeyama. At 10:28 the Okinawa District Meteorological Observatory announced a raised likelihood of a linear rainband forming over the Ishigaki region within three hours. Typhoon No. 31 was also reported to have formed.", "summary_original": "大型の台風30号は24日午前9時、与那国島の北北東約50キロにあり、時速15キロで東に進んでいる。沖縄気象台は午前10時28分、石垣島地方に今後3時間以内に線状降水帯が発生する可能性が高まったと発表した。", "title_en": "Large, strong Typhoon No. 30 stalls north of Yonaguni; storm warnings continue for Miyako and Yaeyama; Typhoon No. 31 also forms", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4966,'claude-haiku-5-5','2026-10-25T04:16:35Z',1,0.85,0,'{"actions_taken": ["Partial suspension of Area Mail (emergency alert) service for security response", "Suspension of ''Dokodemo Saigai/Hinan Joho'' disaster and evacuation information distribution", "Emergency maintenance carried out"], "agencies": [{"country": "JP", "name": "NTT Docomo", "type": "other"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["cell_broadcast", "mobile_app"], "event_date": "2026-10-23", "event_location": null, "event_name": null, "ew4all_pillars": [3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "ドコモ 「 エリアメール 」 がPHP対応で一部停止 、 Jアラートや避難情報対象 ・ 地震速報は継続", "outcome": "negative", "outcome_justification": "Disruption of cell-broadcast emergency alerts, including J-Alert and evacuation information, reduces warning dissemination capacity, though earthquake alerts continue.", "relevant": true, "review": false, "summary_en": "NTT Docomo announced on 23 October that, due to a security response involving PHP support, parts of its Area Mail emergency alert service and the ''Dokodemo Saigai/Hinan Joho'' disaster and evacuation information distribution were suspended for emergency maintenance. Earthquake early alerts continue. The suspension affects delivery of J-Alert and evacuation information to mobile users.", "summary_original": "NTTドコモは10月23日、セキュリティ対応に伴い、緊急速報「エリアメール」の一部サービスおよび「どこでも災害・避難情報」の配信を停止し、緊急メンテナンスを実施していると発表した。", "title_en": "NTT Docomo''s Area Mail partially suspended due to PHP support, affecting J-Alert and evacuation information; earthquake alerts continue", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4967,'claude-haiku-5-5','2026-10-25T04:20:00Z',0,0.8,0,'{"actions_taken": ["Expert panel discussion on strengthening drainage and storage facilities for urban inundation", "Plan to ask municipalities to build drainage facilities able to handle 100mm/hour rainfall in hazard spots"], "agencies": [{"country": "JP", "name": "Ministry of Land, Infrastructure, Transport and Tourism (MLIT)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-22", "event_location": "Japan", "event_name": null, "ew4all_pillars": [1], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "国土交通省 、 排水整備強化促す 100ミリ級豪雨に対応", "outcome": "not_reported", "outcome_justification": "Article concerns infrastructure policy for pluvial flooding after past events; no warning, forecast or dissemination activity is described.", "relevant": false, "review": false, "summary_en": "Japan''s Ministry of Land, Infrastructure, Transport and Tourism plans to ask local governments to strengthen drainage and storage facilities against urban inundation from extreme rainfall of about 100 mm per hour. The policy responds to recent heavy rain events, including the August Chiba downpour, linked to climate change. The item focuses on structural flood protection rather than early warning services.", "summary_original": "国土交通省は、内水氾濫被害を減らすため、排水・貯留施設の整備強化を自治体に求める方針を有識者会議で示した。1時間100ミリ級の豪雨への対応を危険箇所で図る。8月の千葉豪雨などを受けた対策である。", "title_en": "MLIT calls for stronger drainage to counter 100mm-class torrential rain", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4968,'claude-haiku-5-5','2026-10-25T04:20:04Z',1,0.8,0,'{"actions_taken": ["Central Disaster Response Center reported casualty figures and damage status"], "agencies": [{"country": "TW", "name": "Central Weather Administration", "type": "NMHS"}, {"country": "TW", "name": "Central Disaster Response Center", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["TW"], "dissemination_channels": [], "event_date": "2026-10-23", "event_location": "Taiwan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": 1, "economic_losses": null, "evacuated": null, "injured": 94, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "from the night of 23 October to early morning of 24 October (approaching closest)", "lead_time_hours": null, "original_title": "台風30号 、 今夜から明日午前にかけ台湾に最接近か 1人死亡 、 94人けが", "outcome": "not_reported", "outcome_justification": "The snippet reports a forecast of closest approach and casualties already incurred, but does not state whether warnings led to specific protective actions or their effectiveness.", "relevant": true, "review": false, "summary_en": "The Central Weather Administration of Taiwan forecast that Typhoon No. 30 (designated No. 29 by the CWA) would make its closest approach to Taiwan from the night of 23 October to the morning of 24 October. The Central Disaster Response Center reported one death and 94 injuries across Taiwan as of 6:30 a.m. on 23 October.", "summary_original": "中央気象署によると台風は23日夜から24日午前にかけて台湾に最接近する見通しで、中央災害対策センターは23日午前時点で1人死亡、94人けがと発表した。", "title_en": "Typhoon No. 30 may approach Taiwan from tonight to early tomorrow morning; 1 dead, 94 injured", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4969,'claude-haiku-5-5','2026-10-25T04:17:02Z',1,0.9,0,'{"actions_taken": ["JMA called on residents to remain on strict alert for gales, high waves and heavy rain"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-10-23", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風３０号 、 先島諸島から東シナ海へ 暴風高波大雨に厳重警戒 ― 気象庁 ： 時事ドットコム", "outcome": "not_reported", "outcome_justification": "The snippet reports JMA warnings and advisories for the Sakishima Islands but gives no information on impacts or how the warnings were received or acted upon.", "relevant": true, "review": false, "summary_en": "A large, very strong Typhoon No. 30 was forecast to pass near Yonaguni Island on the night of 23 October and move north of the Sakishima Islands, making them very rough. The Japan Meteorological Agency urged strict vigilance against gales, high waves and heavy rain.", "summary_original": "大型で非常に強い台風30号が23日夜に与那国島付近を通過し、先島諸島北方へ進む見通しで、同諸島は大荒れとなる。気象庁は暴風・高波・大雨に厳重警戒を呼びかけた。", "title_en": "Typhoon No. 30 moves from Sakishima Islands toward East China Sea; JMA urges strict vigilance for gales, high waves and heavy rain", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4970,'claude-haiku-5-5','2026-10-25T04:16:47Z',1,0.9,0,'{"actions_taken": ["JMA issued forecasts of storm, high waves, landslides, storm surge, and river flooding for Okinawa", "JMA warned of possible linear rainband (senjo kousuitai) formation with rapidly rising heavy rain disaster risk", "Public advised to be on alert for inundation of low-lying areas and river overflow"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30 (2026)", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "about 1 day before closest approach to Sakishima Islands (24 October)", "lead_time_hours": 24, "original_title": "【 台風情報 】 台風30号 、 強い勢力で先島諸島へ 沖縄地方で非常に激しい雨や猛烈な風の予報 前線の北上に伴い西日本や東日本の広い範囲で土砂災害等に警戒を 最新の進路予報 気象庁発表 、 現在位置と今後の進路予想 | 行政 ・ 社会 | 佐賀県のニュース", "outcome": "not_reported", "outcome_justification": "The item only reports forecasts and warnings issued in advance; no actual impacts or outcomes are described.", "relevant": true, "review": false, "summary_en": "JMA forecast that Typhoon No. 30, a large and strong storm, would closely approach the Sakishima Islands on 24 October and warned of violent winds, high waves, landslides and storm surge in Okinawa. JMA also warned that linear rainbands could cause heavy rain disasters to rise rapidly, and advised alerts for flooding and river overflow across wide areas of western and eastern Japan.", "summary_original": "台風第30号は24日にかけて強い勢力で先島諸島に最も接近する見込み。気象庁は沖縄地方で暴風、高波、土砂災害、高潮に厳重に警戒を呼びかけ、線状降水帯による大雨災害の危険度急上昇にも注意を促している。", "title_en": "[Typhoon Information] Typhoon No. 30 approaching Sakishima Islands with strong force; very heavy rain and violent winds forecast for Okinawa; landslide warnings across wide areas of western and eastern Japan as front moves north; latest track forecast issued by JMA", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4971,'claude-haiku-5-5','2026-10-25T04:18:24Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-23", "event_location": null, "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "全般気象解説情報 （ 台風第３０号 ）（ 第６報 ） ＝気象庁発表 （ ２３日５時１分 ） ： 気象解説情報", "outcome": "not_reported", "outcome_justification": "The item is a JMA official forecast commentary on a typhoon; no outcomes of the warning are reported in the snippet.", "relevant": true, "review": false, "summary_en": "JMA issued the sixth general meteorological commentary on Typhoon No. 30 at 05:01 on 23 October, providing forecast information on the developing tropical cyclone. The snippet does not describe warnings'' dissemination or actions taken or outcomes.", "summary_original": "気象庁は10月23日5時1分、台風第30号に関する全般気象解説情報（第6報）を発表した。台風の予報に関する解説情報であり、詳細な内容はスニペットからは確認できない。", "title_en": "General Meteorological Commentary (Typhoon No. 30) (Report No. 6) — issued by JMA at 05:01 on the 23rd: Meteorological Commentary", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4972,'claude-haiku-5-5','2026-10-25T04:16:38Z',1,0.97,0,'{"actions_taken": ["JMA issued a ''linear rainband immediate forecast'' meteorological disaster alert (気象防災速報) at 10:58 for northern Wakayama Prefecture"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Northern Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "和歌山県北部に「線状降水帯直前予測」", "outcome": "not_reported", "outcome_justification": "The snippet reports only the issuance of the alert; no outcomes or public response are described.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a ''linear rainband immediate forecast'' disaster alert at 10:58 for northern Wakayama Prefecture, indicating a high likelihood of a linear rainband forming within the next three hours. The alert was reported by NHK. The snippet does not describe public response or outcomes.", "summary_original": "気象庁は和歌山県北部で今後3時間以内に線状降水帯が発生する可能性が高まったとして、午前10時58分に「線状降水帯直前予測」の気象防災速報を発表した。", "title_en": "\"Linear rainband immediate forecast\" issued for northern Wakayama Prefecture", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4973,'claude-haiku-5-5','2026-10-25T04:16:50Z',1,0.9,0,'{"actions_taken": ["Preventive evacuation", "Rescues", "Activation of temporary shelters", "Preventive alerts via sirens and loudspeakers"], "agencies": [{"country": "MX", "name": "Government of Veracruz", "type": "other_national_agency"}, {"country": "MX", "name": "Federal Government of Mexico", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["MX"], "dissemination_channels": ["sirens", "loudspeakers"], "event_date": "2026-10-25", "event_location": "Veracruz, Mexico", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Veracruz despliega operativo Estatal y Federal para atender la emergencia por las lluvias", "outcome": "not_reported", "outcome_justification": "The snippet describes warnings and preventive evacuations but does not report whether they reduced losses or whether any shortcomings occurred.", "relevant": true, "review": false, "summary_en": "Veracruz state and federal authorities are conducting relief, preventive evacuation and recovery operations linked to rains from Cold Front No. 2. Preventive alerts were disseminated via sirens and loudspeakers, followed by rescues and the opening of temporary shelters.", "summary_original": "El gobierno de Veracruz, con apoyo federal, mantiene acciones de auxilio, evacuación preventiva y recuperación por lluvias asociadas al Frente Frío número 2. Las alertas preventivas se difundieron mediante sirenas y perifoneo, seguidas de rescates y habilitación de refugios temporales.", "title_en": "Veracruz deploys state and federal operation to address rain emergency", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(4974,'claude-haiku-5-5','2026-10-25T04:17:19Z',0,0.7,0,'{"actions_taken": ["Emergency agencies running assistance and prevention operations"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Neuquén, Chaco and Corrientes, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Inundaciones, evacuados y aislados: las imágenes del caos que provocó El Niño en Neuquén, Chaco y Corrientes - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and isolated families but does not mention warnings or forecasts issued or their effectiveness.", "relevant": false, "review": false, "summary_en": "Intense rains and river flooding left thousands evacuated and families isolated in Neuquén, Chaco and Corrientes, attributed to El Niño. Emergency agencies are running assistance and prevention operations. The snippet does not describe any monitoring, forecast or warning activity, so the item is judged not relevant to early warning services.", "summary_original": "Las lluvias intensas y la crecida de los ríos dejaron miles de evacuados y familias aisladas en Neuquén, Chaco y Corrientes. Los organismos de emergencia sostienen operativos de asistencia y prevención atribuidos al fenómeno El Niño.", "title_en": "Floods, evacuees and isolated people: the images of the chaos caused by El Niño in Neuquén, Chaco and Corrientes - Infobae", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4975,'claude-haiku-5-5','2026-10-25T04:18:27Z',1,0.85,0,'{"actions_taken": ["Participation in an academic event on early warning strategies for El Niño in Loreto, aimed at the general public"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Loreto, Peru", "event_name": "El Niño", "ew4all_pillars": [1, 3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI difunde estrategias de alerta temprana frente al fenómeno El Niño en Loreto", "outcome": "not_reported", "outcome_justification": "The snippet describes an outreach event on early warning strategies but reports no outcomes of warnings.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, took part in a public academic event on early warning strategies for the El Niño phenomenon in the Loreto region. The initiative focuses on risk knowledge and communication of early warning information to the general public. The snippet does not report specific warnings issued or their outcomes.", "summary_original": "El SENAMHI participó en un evento académico sobre estrategias de alerta temprana frente al fenómeno El Niño en Loreto, dirigido al público en general.", "title_en": "SENAMHI disseminates early warning strategies for El Niño phenomenon in Loreto", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5128,'claude-haiku-5-5','2026-10-25T04:16:41Z',1,0.93,0,'{"actions_taken": ["Precautions advised to the population"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Peruvian jungle (selva), Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "about 1 day before 25-26 October", "lead_time_hours": null, "original_title": "Termómetros llegarán a 39°C y activan alerta roja este fin de semana: Senamhi advierte ola de calor extremo en 7 regiones", "outcome": "not_reported", "outcome_justification": "The item reports a forecast and red alert issued by Senamhi ahead of the event; no outcomes are yet reported.", "relevant": true, "review": false, "summary_en": "Senamhi forecasts temperatures up to 39°C in Peru''s jungle on 25-26 October, triggering red alerts in several regions. The agency urges precautions for the population. The item documents a forecast and heat alert issued in advance of the hazard.", "summary_original": "Senamhi advierte que la selva peruana enfrentará temperaturas de hasta 39°C el 25 y 26 de octubre, lo que activa alertas rojas en varias regiones. Se requieren precauciones.", "title_en": "Thermometers to reach 39°C and trigger red alert this weekend: Senamhi warns of extreme heatwave in 7 regions", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5138,'claude-haiku-5-5','2026-10-25T04:18:30Z',1,0.9,0,'{"actions_taken": ["Santa Marta mayor''s office declared a red alert for floods and risk of flash floods on two rivers, based on the latest IDEAM report"], "agencies": [{"country": "CO", "name": "IDEAM", "type": "NMHS"}, {"country": "CO", "name": "Alcaldía de Santa Marta", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CO"], "dissemination_channels": ["website"], "event_date": "2026-10-24", "event_location": "Santa Marta, Colombia", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Emergencias por lluvias en el Caribe: primeros balances de inundaciones y desbordamientos en varias ciudades; se esperan más precipitaciones", "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert declaration and IDEAM-based recommendations but gives no information on the outcome of the warnings.", "relevant": true, "review": false, "summary_en": "The Santa Marta municipal government declared a red alert for flooding and the risk of flash floods on two rivers, based on the latest IDEAM hydrometeorological report, and issued recommendations to residents. Further rainfall was expected across Caribbean cities. The snippet gives no details on dissemination or outcomes.", "summary_original": "La Alcaldía de Santa Marta declaró alerta roja por inundaciones y riesgo de crecientes súbitas en dos ríos, con base en el más reciente reporte del IDEAM, que emitió recomendaciones para la población.", "title_en": "Caribbean rain emergencies: first reports of floods and overflows in several cities; more rainfall expected", "wmo_regions": ["III", "IV"]}');
