INSERT INTO "classifications" VALUES(5288,'claude-haiku-5-5','2026-10-26T04:15:17Z',1,0.85,0,'{"actions_taken": ["JMA advised caution against landslides and inundation of low-lying areas"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-26", "event_location": null, "event_name": "Typhoon Ragasa", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風30号は温帯低気圧に 西～東日本で非常に激しい雨のおそれ", "outcome": "not_reported", "outcome_justification": "The item reports a JMA advisory on continuing heavy rain but gives no information on outcomes of the warning.", "relevant": true, "review": false, "summary_en": "Typhoon No. 30 has transitioned into an extratropical cyclone, and together with a front it is causing locally heavy rain in western Japan. Because the front will stall, rain may continue in eastern Japan, and the Japan Meteorological Agency is urging residents to take care against landslides and flooding of low-lying areas.", "summary_original": "台風30号から変わった温帯低気圧と前線の影響で、西日本では局地的に激しい雨が降っている。前線は停滞するため東日本でも雨が続くおそれがあり、気象庁は土砂災害や低い土地の浸水への注意を呼びかけている。", "title_en": "Typhoon No. 30 becomes extratropical cyclone; very heavy rain feared from western to eastern Japan", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(5352,'claude-haiku-5-5','2026-10-26T04:15:34Z',1,0.93,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Osaka Regional Meteorological Observatory (JMA)", "type": "NMHS"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Kinki region, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "from late morning on 25 October through 26 October", "lead_time_hours": null, "original_title": "【 速報 】【 台風30号 】 近畿地方 、 きょう25日～警報級大雨の可能性 「 温低 」 で接近 、 強雨ピーク2回か｜京都新聞デジタル 京都 ・ 滋賀のニュースサイト", "outcome": "not_reported", "outcome_justification": "The item reports a forecast/advisory of possible warning-level heavy rain; no outcome is yet described.", "relevant": true, "review": false, "summary_en": "The Osaka Regional Meteorological Observatory issued a heavy-rain weather information on the morning of 25 October stating that Typhoon No. 30 and related effects could bring warning-level heavy rain to the Kinki region from late morning on 25 October into 26 October. The approaching warm low is expected to produce two peaks of heavy rain.", "summary_original": "大阪管区気象台は25日朝、大雨に関する気象情報を発表し、台風30号などの影響で近畿地方は25日昼前～26日にかけて警報級大雨の可能性があるとした。温低の接近により強雨のピークが2回来る見込み。", "title_en": "[Breaking] Typhoon No. 30: Kinki region may see warning-level heavy rain from the 25th; warm low approaches with two rain peaks likely", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(5353,'claude-haiku-5-5','2026-10-26T04:15:07Z',1,0.97,0,'{"actions_taken": ["JMA issued a linear rainband immediate forecast (senjo kosuitai chokuzen yosoku) for northern Wakayama Prefecture at 10:58 JST", "Level 4 sediment disaster danger warning issued for Arida City and Yuasa Town"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "FNN Prime Online (Fuji TV)", "type": "media"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-25", "event_location": "Arida City and Yuasa Town, Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "和歌山県北部に「線状降水帯」発生の恐れ（10時58分時点）（FNNプライムオンライン（フジテレビ系）） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the forecast and warning; no outcome is described in the snippet.", "relevant": true, "review": false, "summary_en": "JMA issued a linear rainband immediate forecast for northern Wakayama Prefecture at 10:58 JST on 25 October, warning that a linear rainband could form within three hours and produce very heavy rain. A Level 4 sediment disaster danger warning was issued for Arida City and Yuasa Town. The item focuses on the forecast and warning issuance; no outcome is reported.", "summary_original": "気象庁は25日10時58分に和歌山県北部へ線状降水帯直前予測を発表し、今後3時間以内に線状降水帯が発生し非常に激しい雨が続く可能性があると伝えた。和歌山県有田市・湯浅町にはレベル4土砂災害危険警報が発表された。", "title_en": "Possible formation of a linear rainband (senjo kosuitai) in northern Wakayama Prefecture (as of 10:58) (FNN Prime Online, Fuji TV affiliate) - Yahoo! News", "wmo_regions": ["II"]}');
