INSERT INTO "classifications" VALUES(5360,'claude-haiku-5-5','2026-10-26T04:16:31Z',1,0.6,0,'{"actions_taken": ["evacuation of thousands of people from riverside areas"], "agencies": [{"country": "PY", "name": "Ministerio de Defensa Nacional", "type": "other_national_agency"}], "confidence": 0.6, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Southern and eastern Paraguay, Paraná River", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del río Paraná: ¿ Cuál es la zona que más preocupa al ministro de Defensa? - Nacionales", "outcome": "not_reported", "outcome_justification": "The snippet reports flooding and evacuations but does not state whether warnings preceded or enabled them.", "relevant": true, "review": false, "summary_en": "The Paraguayan Minister of National Defence commented on the crisis in the south and east of the country caused by the flooding of the Paraná River, which inundated riverside areas and forced the evacuation of thousands of people. The minister discussed the affected points of greatest concern to authorities. The snippet does not describe monitoring, forecasts or warning dissemination.", "summary_original": "El ministro de Defensa Nacional habló sobre la crisis en el sur y este del país por la crecida del río Paraná, que inundó zonas ribereñas y obligó a evacuar a miles de personas, y sobre los puntos afectados que más preocupan a las autoridades.", "title_en": "Paraná River flood: which area most concerns the Defence Minister?", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5362,'claude-haiku-5-5','2026-10-26T04:16:35Z',1,0.7,0,'{"actions_taken": ["Evacuation of livestock from the islands", "Coordination of works, transfers and safety measures with agencies and producers", "Expedited procedures with Senasa"], "agencies": [{"country": "AR", "name": "Government of Santa Fe", "type": "other_national_agency"}, {"country": "AR", "name": "Senasa", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Santa Fe Province, Argentina", "event_name": "El Niño", "ew4all_pillars": [4], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Fenómeno de El Niño: la Provincia asistió en la evacuación de más del 70% de la hacienda de las islas", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuation progress but does not state whether warnings preceded or enabled the evacuation or its effects.", "relevant": true, "review": false, "summary_en": "Santa Fe Province''s government reportedly helped evacuate over 70% of livestock from islands linked to El Niño-related flooding, coordinating with Senasa and producers. The snippet does not detail the monitoring or warnings that triggered the response.", "summary_original": "El Gobierno de Santa Fe agilizó trámites con el Senasa y coordinó obras, traslados y medidas de seguridad para evacuar más del 70% de la hacienda de las islas por el fenómeno de El Niño.", "title_en": "El Niño phenomenon: the Province assisted in evacuating more than 70% of livestock from the islands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5363,'claude-haiku-5-5','2026-10-26T04:16:38Z',0,0.7,0,'{"actions_taken": ["Evacuations", "Assistance operations deployed by authorities"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Neuquén, Chaco and Corrientes provinces, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 1700, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tormentas, crecidas y más de 1.700 evacuados: cómo impacta El Niño en Neuquén, Chaco y Corrientes", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and flooding but does not state whether warnings were issued, disseminated, or how they performed.", "relevant": false, "review": false, "summary_en": "Intense rains in Neuquén, Chaco and Corrientes provinces of Argentina led to evacuations of more than 1,700 people, road cuts and serious flooding linked to El Niño. Authorities deployed assistance operations as water advanced over homes and productive areas. The snippet does not describe monitoring, forecasts or warnings issued before the event.", "summary_original": "Intensas lluvias en Neuquén, Chaco y Corrientes provocaron evacuaciones de más de 1.700 personas, cortes de caminos e inundaciones graves vinculadas a El Niño. Las autoridades desplegaron operativos de asistencia mientras el agua avanzaba sobre viviendas y zonas productivas.", "title_en": "Storms, floods and more than 1,700 evacuated: how El Niño impacts Neuquén, Chaco and Corrientes", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5366,'claude-haiku-5-5','2026-10-26T04:16:12Z',0,0.35,1,'{"actions_taken": ["Provincial governments deployed assistance and prevention operations"], "agencies": [{"country": "AR", "name": "Radio Mitre", "type": "media"}], "confidence": 0.35, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Neuquén, Chaco and Corrientes provinces, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Fuertes inundaciones en Neuquén, Chaco y Corrientes por El Niño: evacuados, parajes aislados y rutas afectadas", "outcome": "not_reported", "outcome_justification": "The snippet reports flooding and evacuations but does not mention any warnings, forecasts or early warning dissemination; the only warning-adjacent element is a general reference to an El Niño scenario.", "relevant": false, "review": true, "summary_en": "Flooding linked to intense rains and rising rivers has put parts of Neuquén, Chaco and Corrientes in emergency, with families isolated, roads cut and residents evacuated. Provincial governments deployed assistance and prevention operations amid a scenario associated with El Niño. The snippet does not describe any monitoring, forecasts or warnings issued in advance.", "summary_original": "Las inundaciones por lluvias intensas y el aumento de los ríos mantienen en emergencia zonas de Neuquén, Chaco y Corrientes, con familias aisladas, caminos cortados y vecinos evacuados. Los gobiernos provinciales desplegaron operativos de asistencia y prevención ante un escenario asociado a El Niño.", "title_en": "Heavy floods in Neuquén, Chaco and Corrientes due to El Niño: evacuees, isolated settlements and affected roads", "wmo_regions": ["III"]}');
