INSERT INTO "classifications" VALUES(5668,'claude-haiku-5-5','2026-10-27T04:19:53Z',1,0.7,0,'{"actions_taken": ["Advisory No. 2026-10-004 urging tourism establishments to implement water-saving measures and protect guests and staff from extreme heat"], "agencies": [{"country": "PH", "name": "Department of Tourism (Mimaropa)", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["PH"], "dissemination_channels": ["other"], "event_date": "2026-10-27", "event_location": "Oriental Mindoro, Philippines", "event_name": "El Niño 2026", "ew4all_pillars": [3, 4], "hazard": "drought", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "DOT urges establishment owners to step up water conservation amid El Niño", "outcome": "not_reported", "outcome_justification": "The snippet describes an advisory issued in response to El Niño water supply threats but reports no outcome of its implementation.", "relevant": true, "review": false, "summary_en": "The Department of Tourism in Mimaropa issued Advisory No. 2026-10-004 urging tourism establishments in Occidental and Oriental Mindoro, Marinduque, Romblon and Palawan to conserve water and protect guests and personnel from extreme heat as El Niño threatens water supplies. The advisory is a government warning-related communication responding to an El Niño-driven drought risk.", "summary_original": null, "title_en": "DOT urges establishment owners to step up water conservation amid El Niño", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(5711,'claude-haiku-5-5','2026-10-27T04:19:18Z',1,0.85,0,'{"actions_taken": ["SoftBank suspended delivery of disaster and evacuation information from national and local governments for maintenance after a serious PHP vulnerability was found", "SoftBank resumed all emergency alert mail deliveries on the evening of 26 October"], "agencies": [{"country": "JP", "name": "SoftBank", "type": "other"}, {"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-26", "event_location": null, "event_name": null, "ew4all_pillars": [3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "ソフトバンク 緊急速報メールの配信すべて再開", "outcome": "mixed", "outcome_justification": "Emergency alert delivery was interrupted for maintenance and has been restored, but the snippet does not report any hazard event or harm arising from the suspension.", "relevant": true, "review": false, "summary_en": "SoftBank, a major Japanese telecom operator, had suspended delivery of disaster and evacuation information from national and local governments via emergency alert mail after a serious vulnerability was discovered in the PHP programming language. The company resumed all deliveries on the evening of 26 October 2026. The item concerns the continuity of warning dissemination infrastructure.", "summary_original": "通信大手のソフトバンクは、PHPと呼ばれるプログラミング言語に重大なぜい弱性が見つかったことに伴い、メンテナンスのため停止していた国や地方公共団体による災害や避難の情報の配信を、26日夜に再開した。", "title_en": "SoftBank resumes all emergency alert mail deliveries", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(5782,'claude-haiku-5-5','2026-10-27T04:19:03Z',1,0.95,0,'{"actions_taken": ["Declaration of Early Preventive Alert (Alerta Temprana Preventiva) for the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": ["other"], "event_date": "2026-10-26", "event_location": "Región Metropolitana, Chile", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Monday afternoon until conditions warrant; issued 26 October 2026 for Monday 27 October", "lead_time_hours": null, "original_title": "Decretan Alerta Temprana Preventiva en la RM por pronóstico de lluvia, tormenta eléctrica y granizos", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the alert; no outcomes of the event are described.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency agency Senapred declared an Early Preventive Alert for the Metropolitan Region ahead of forecast normal to moderate rain, electrical storms and possible hail on Monday afternoon. The alert remains in force until conditions warrant it being lifted.", "summary_original": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana ante el pronóstico de lluvias normales a moderadas, tormentas eléctricas y posibles granizos para la tarde del lunes. El aviso rige desde ese día hasta que las condiciones lo ameriten.", "title_en": "Early Preventive Alert declared in the Metropolitan Region due to forecast rain, thunderstorms and hail", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5783,'claude-haiku-5-5','2026-10-27T04:19:00Z',1,0.95,0,'{"actions_taken": ["Senamhi issued red-level meteorological warning No. 440 for heavy to extreme rainfall", "Indeci recommended reinforcing house roofs and establishing early warning mechanisms with local authorities"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Indeci", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-10-27", "event_location": "Peru (northern coast and highlands)", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "between 27 and 29 October (issued before the event)", "lead_time_hours": null, "original_title": "El Senamhi emite una alerta roja por lluvias intensas en 11 departamentos del Perú entre el 27 y 29 de octubre - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet describes the warning and recommendations but reports no outcome of the event.", "relevant": true, "review": false, "summary_en": "Peru''s NMHS Senamhi issued red-level warning No. 440 for heavy to extreme rainfall on the northern coast and highlands between 27 and 29 October. Indeci recommended reinforcing roofs and setting up early warning mechanisms with local authorities.", "summary_original": "El Senamhi emitió el aviso meteorológico N.° 440, de nivel rojo, por precipitaciones intensas en la costa norte y la sierra entre el 27 y el 29 de octubre, y Indeci recomendó reforzar techos y establecer mecanismos de alerta temprana.", "title_en": "Senamhi issues red alert for heavy rains in 11 departments of Peru between 27 and 29 October", "wmo_regions": ["III"]}');
