INSERT INTO "classifications" VALUES(5796,'copied','2026-10-27T04:20:49Z',1,0.9,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 432"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Northern coast and highlands, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Friday 23 onward (per snippet, period truncated)", "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante precipitaciones en la costa norte y sierra", "outcome": "not_reported", "outcome_justification": "The snippet describes a recommendation to prepare for forecast moderate-to-strong rain and hail, but no observed outcome is reported.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures ahead of SENAMHI Aviso N.° 432, which warns of moderate-to-strong rainfall and hail in the highlands from Friday 23 onward. The advisory forms part of the warning-to-action chain, linking the NMHS warning to civil protection preparedness. The snippet is truncated, so the full period and affected areas are not confirmed.", "summary_original": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 432 del SENAMHI, que informa sobre precipitaciones (lluvias y granizo) de moderada a fuerte intensidad en la sierra desde el viernes 23.", "title_en": "INDECI recommends preparedness measures for rainfall in the northern coast and highlands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5935,'claude-haiku-5-5','2026-10-27T04:19:50Z',0,0.85,0,'{"actions_taken": ["Community kitchen increased production by 100 meals per day for people evacuated by the Paraná river flood"], "agencies": [], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-26", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La incansable Ceci: tiene un comedor comunitario y ahora también prepara viandas para los evacuados por las inundaciones en Corrientes", "outcome": "not_reported", "outcome_justification": "The snippet describes community food support for flood evacuees but reports no warnings, forecasts, or early warning outcomes.", "relevant": false, "review": false, "summary_en": "A community kitchen in Paranacito, Corrientes, Argentina, has increased its output by 100 meals per day to feed people who had to leave their homes because of the rising Paraná river. The item focuses on humanitarian food aid and does not mention monitoring, forecasts, warnings or their dissemination.", "summary_original": "Cecilia Bernié, encargada del \"Comedor Paranacito\", aumentó su producción para preparar 100 platos más de comida diaria para personas que dejaron sus hogares por la crecida del río Paraná.", "title_en": "The tireless Ceci: she runs a community kitchen and now also prepares meals for those evacuated by flooding in Corrientes", "wmo_regions": ["III"]}');
