INSERT INTO "classifications" VALUES(5957,'claude-haiku-5-5','2026-10-27T04:19:56Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Defensoría del Pueblo", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-10-25", "event_location": "Ayabaca, Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Fuertes lluvias en Piura inundan viviendas en Ayabaca: Senamhi alerta por precipitaciones intensas en el norte del país", "outcome": "not_reported", "outcome_justification": "The item reports flooding of homes and Senamhi forecasts of up to 40 mm/day, but does not state whether warnings were received or acted upon.", "relevant": true, "review": false, "summary_en": "Rainfall on Sunday flooded 15 homes in Ayabaca, Piura, according to the Ombudsman''s office, carrying mud through streets and shops. Senamhi forecasts accumulations of up to 40 mm per day on the northern coast, along with electrical discharges and gusts near 40 km/h.", "summary_original": "Las lluvias del domingo afectaron 15 viviendas en Ayabaca y Senamhi prevé hasta 40 mm diarios en la costa norte, además de descargas eléctricas y ráfagas de viento.", "title_en": "Heavy rains in Piura flood homes in Ayabaca: Senamhi warns of intense precipitation in northern Peru", "wmo_regions": ["III"]}');
