INSERT INTO "classifications" VALUES(6140,'claude-haiku-5-5','2026-10-28T04:17:26Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-26", "event_location": null, "event_name": "Typhoon No. 25 (2026)", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "令和８年台風第25号による大雨の状況について～「災害をもたらした気象事例」に資料を掲載しました～", "outcome": "not_reported", "outcome_justification": "The official JMA press release announces a post-event summary of heavy rain from the typhoon, but the snippet provides no details on warnings issued, their timing, or outcomes.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency published a press release on heavy rain associated with Typhoon No. 25 (2026) and added supporting materials to its ''Meteorological Events That Caused Disasters'' web page. The release is a post-event review of meteorological conditions and is relevant to how the event was monitored and forecast, though the snippet does not state specific warnings or outcomes.", "summary_original": "気象庁は令和８年台風第25号による大雨について、「災害をもたらした気象事例」のページに資料を掲載したと発表した。", "title_en": "Heavy rain caused by Typhoon No. 25 (2026) — materials added to the ''Meteorological Events That Caused Disasters'' page", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6142,'claude-haiku-5-5','2026-10-28T04:16:51Z',1,0.8,0,'{"actions_taken": ["JMA announced the ''Kogarashi 1'' (first winter wind) observation for Tokyo and Kinki at 11:00", "Strong wind alerts issued for northern Japan"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-28", "event_location": "Northern Japan, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "冬型気圧配置 初雪や「木枯らし1号」も 北日本は暴風など警戒", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and observations but no outcomes or impacts from the event.", "relevant": true, "review": false, "summary_en": "A winter pressure pattern and upper-level cold air brought snow and first-snow observations to northern Japan, including Sapporo and Aomori. JMA announced the ''Kogarashi 1'' winter wind observation for Tokyo and Kinki, and strong wind warnings were issued for northern Japan.", "summary_original": "冬型の気圧配置と上空の寒気の影響で北日本を中心に雪が降り、札幌市や青森市などで初雪が観測された。気象庁は東京と近畿で「木枯らし1号」を発表し、北日本では暴風への警戒が呼びかけられた。", "title_en": "Winter pressure pattern brings first snow and ''first north wind of winter'' (Kogarashi 1); strong winds warned in northern Japan", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6151,'claude-haiku-5-5','2026-10-28T04:17:21Z',0,0.9,0,'{"actions_taken": [], "agencies": [], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-07-28", "event_location": "Kumamoto, Japan", "event_name": null, "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "熊本地震3か月 住まいの確保と在宅避難者への継続支援が課題", "outcome": "not_reported", "outcome_justification": "The item covers post-disaster shelter and recovery conditions three months after the earthquake and does not discuss any warnings, forecasts or alerts.", "relevant": false, "review": false, "summary_en": "Three months after the July 2026 Kumamoto earthquake, over 1,000 people remain in evacuation shelters and many others live in damaged homes. The article focuses on long-term housing and continued support needs ahead of winter, with no reference to early warning, monitoring or alert dissemination.", "summary_original": "ことし7月の熊本地震から3か月が経過し、依然として1000人余りが避難所で生活しているほか、壊れた自宅で暮らす人も多い。冬を前に住まいの確保と在宅避難者への支援が課題となっている。", "title_en": "Three months after the Kumamoto earthquake: securing housing and continued support for people sheltering at home are challenges", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6230,'claude-haiku-5-5','2026-10-28T04:16:31Z',1,0.93,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Japan Weather Association (tenki.jp)", "type": "media"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-25", "event_location": "Northern Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within 3 hours", "lead_time_hours": 3, "original_title": "【速報】和歌山県北部は今後3時間以内に線状降水帯発生のおそれ 25日11時頃発表(気象予報士 日直主任 2026年10月25日) - 日本気象協会 tenki.jp", "outcome": "not_reported", "outcome_justification": "The item reports a JMA linear rainband (senjojosuikitai) immediate forecast issued at 10:58 for northern Wakayama, but no actual impacts or responses are described.", "relevant": true, "review": false, "summary_en": "JMA issued a weather disaster flash bulletin (linear rainband immediate forecast) at 10:58 on 25 October 2026, warning that a linear rainband was likely to form in northern Wakayama Prefecture within the next three hours. The item is a media report relaying this official forecast; it does not describe outcomes or public responses.", "summary_original": "気象庁は10月25日10時58分に気象防災速報(線状降水帯直前予測)を発表し、和歌山県北部では今後3時間以内に線状降水帯が発生する可能性が高まったとしています。", "title_en": "[Flash] Northern Wakayama Prefecture at risk of linear rainband formation within 3 hours; announced around 11:00 on 25 October", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6231,'claude-haiku-5-5','2026-10-28T04:17:02Z',1,0.9,0,'{"actions_taken": ["Issued strong warnings about heavy rain", "Reported linear rainband immediate forecast (線状降水帯直前予測) operational from 2026"], "agencies": [{"country": "JP", "name": "Weathernews", "type": "media"}, {"country": "JP", "name": "JMA (AMeDAS observation network)", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-25", "event_location": "Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "和歌山県で線状降水帯が発生のおそれ 大雨に厳重警戒 - ウェザーニュース", "outcome": "not_reported", "outcome_justification": "The snippet reports observed rainfall and the warning but gives no information on impacts or whether warnings were acted upon.", "relevant": true, "review": false, "summary_en": "Very heavy rain continued in northern Wakayama Prefecture, with AMeDAS Wakayama recording 78 mm in three hours. A possible linear rainband (senjo kosuitai) was flagged under strong heavy-rain warnings, and the report notes that the linear rainband immediate forecast has been operational since 2026.", "summary_original": "和歌山県北部付近では非常に激しい雨が続き、アメダス和歌山で3時間に78mmの雨を観測。線状降水帯直前予測は2026年から運用が開始されたと説明されている。", "title_en": "Possible linear rainband in Wakayama Prefecture; heavy rain warning - Weathernews", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6232,'claude-haiku-5-5','2026-10-28T04:16:35Z',1,0.93,0,'{"actions_taken": ["Issued linear rainband ''imminent prediction'' (線状降水帯直前予測) for northern Wakayama Prefecture", "Issued Level 4 sediment disaster danger warning (土砂災害危険警報) for Arida City and surrounding areas", "Issued Level 3 heavy rain warning (大雨警報)"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA) / Wakayama Local Meteorological Observatory", "type": "NMHS"}, {"country": "JP", "name": "MBS (Mainichi Broadcasting System)", "type": "media"}], "confidence": 0.93, "countries": ["JP"], "dissemination_channels": ["tv", "website"], "event_date": "2026-10-25", "event_location": "Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "和歌山県北部に「線状降水帯直前予測」非常に激しい雨が降り続くおそれ高まる 和歌山市の1時間雨量は10月の観測史上最大を記録（MBSニュース） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings issued and record rainfall but does not describe impacts or how the warnings were received or acted upon.", "relevant": true, "review": false, "summary_en": "JMA issued a linear rainband imminent prediction for northern Wakayama Prefecture, along with a Level 4 sediment disaster danger warning for Arida City and a Level 3 heavy rain warning, warning that very heavy rain may continue. Wakayama City recorded 68 mm in one hour, the highest October hourly rainfall on record, according to the report.", "summary_original": "和歌山県北部に「線状降水帯直前予測」が出され、気象台は和歌山県有田市などにレベル4の土砂災害危険警報、レベル3の大雨警報を発表した。和歌山市では10月の観測史上最大の1時間雨量68ミリを記録した。", "title_en": "Linear rainband ''imminent prediction'' issued for northern Wakayama Prefecture; very heavy rain expected to continue; Wakayama City records October hourly rainfall record (MBS News)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6233,'claude-haiku-5-5','2026-10-28T04:16:44Z',1,0.9,0,'{"actions_taken": ["Public media warning urging strict vigilance against heavy rain band formation"], "agencies": [{"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["tv", "website"], "event_date": "2026-10-26", "event_location": "Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within 3 hours", "lead_time_hours": 3, "original_title": "前線と台風影響で大雨 和歌山で線状降水帯直前予測 厳重警戒を", "outcome": "not_reported", "outcome_justification": "The snippet reports a forecast warning of a possible linear rainfall band within 3 hours, but does not describe actual outcomes.", "relevant": true, "review": false, "summary_en": "Locally very heavy rain was observed in Wakayama Prefecture due to a front and Typhoon No. 30. NHK reports that the likelihood of a linear rainfall band forming within 3 hours in northern Wakayama has increased, and urges strict vigilance. The item conveys a short-range heavy rain forecast warning delivered via broadcast media.", "summary_original": "前線や台風30号などの影響で和歌山県では局地的に非常に激しい雨が観測され、和歌山県北部では3時間以内に線状降水帯が発生する可能性が高まっているとNHKが伝えています。", "title_en": "Frontal and typhoon-related heavy rain; quasi-stationary heavy rain band forecast imminent in Wakayama, strict vigilance urged", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6234,'claude-haiku-5-5','2026-10-28T04:16:37Z',1,0.95,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-25", "event_location": "Northern Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "和歌山県北部に「線状降水帯直前予測」の気象防災速報", "outcome": "not_reported", "outcome_justification": "The snippet reports only the issuance of the bulletin; no outcome, impacts or public response is described.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a ''linear rainband imminent forecast'' weather disaster bulletin at 10:58 for northern Wakayama Prefecture, stating that a linear rainband was highly likely to form within the next 3 hours. The item, reported by NHK, concerns a detection and forecasting product for a developing heavy rain hazard; dissemination details and outcomes are not given.", "summary_original": "気象庁は和歌山県北部で今後3時間以内に線状降水帯が発生する可能性が高まったとして、午前10時58分に「線状降水帯直前予測」の気象防災速報を発表した。", "title_en": "Japan Meteorological Agency issues ''linear rainband imminent forecast'' weather disaster bulletin for northern Wakayama Prefecture", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6238,'claude-haiku-5-5','2026-10-28T04:17:13Z',1,0.9,0,'{"actions_taken": ["Red Alert declared for mass movement in 10 pre-Andean communes including San José de Maipo, Puente Alto, Las Condes and Colina"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-26", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "landslide", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senapred declara Alerta Roja en 10 comunas precordilleranas de la RM por remoción en masa tras lluvias", "outcome": "not_reported", "outcome_justification": "The snippet reports the alert declaration but gives no information on outcomes or impacts.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency agency Senapred declared a Red Alert for mass movement (landslide) risk in 10 pre-Andean communes of the Metropolitan Region following an intense frontal system. The alert covers communes including San José de Maipo, Puente Alto, Las Condes and Colina. The snippet does not report channels, lead time or impacts.", "summary_original": "Senapred declaró Alerta Roja por remoción en masa en 10 comunas precordilleranas de la Región Metropolitana debido al intenso sistema frontal, abarcando comunas como San José de Maipo, Puente Alto, Las Condes y Colina.", "title_en": "Senapred declares Red Alert in 10 pre-Andean communes of the Metropolitan Region due to mass movement after rains", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6239,'claude-haiku-5-5','2026-10-28T04:16:24Z',1,0.95,0,'{"actions_taken": ["SENAMHI maintained red-level Meteorological Warning No. 440 for precipitation on the northern coast and highlands, valid until Thursday 29 October 2026"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-28", "event_location": "Tumbes and Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja por lluvias en Tumbes y Piura: ¿hasta cuándo durará y con qué intensidad lloverá?", "outcome": "negative", "outcome_justification": "The article reports that rains in Ayabaca had already caused floods and mudflows, indicating hazardous impacts despite the warning being in place; no evidence of effective response is given.", "relevant": true, "review": false, "summary_en": "SENAMHI maintains a red-level meteorological warning (No. 440) for heavy rainfall on Peru''s northern coast and highlands, valid until 29 October 2026. The article notes that rains in Ayabaca have already caused flooding and mudflows.", "summary_original": "El Senamhi mantiene el Aviso Meteorológico N.° 440 de nivel rojo por precipitaciones en la costa norte y la sierra, vigente hasta el jueves 29 de octubre de 2026. Las lluvias en Ayabaca ya causaron inundaciones y corrientes de lodo.", "title_en": "Red alert for rain in Tumbes and Piura: how long will it last and how intense will the rain be?", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6240,'claude-haiku-5-5','2026-10-28T04:16:28Z',1,0.97,0,'{"actions_taken": ["Indeci warned of possible huaicos and landslides and called for reinforced preventive measures"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Indeci", "type": "other_national_agency"}], "confidence": 0.97, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-27", "event_location": "Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "period 27-29 October 2026", "lead_time_hours": null, "original_title": "Senamhi activa ALERTA ROJA por lluvias intensas: estas 11 regiones serán afectadas hasta el 29 de octubre", "outcome": "not_reported", "outcome_justification": "The item reports the issuance of a red alert and warnings but no observed outcomes of the warnings.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service Senamhi activated a red alert for intense rainfall in 11 regions for 27-29 October 2026, with possible hail, snowfall and strong winds. The civil protection agency Indeci warned of possible flash floods (huaicos) and landslides and urged reinforced preventive measures.", "summary_original": "El Senamhi activó alerta roja por lluvias intensas en 11 regiones para el periodo del 27 al 29 de octubre, con posible granizo, nevadas y fuertes vientos. El Indeci advirtió sobre posibles huaicos y deslizamientos y pidió reforzar medidas preventivas.", "title_en": "Senamhi activates RED ALERT for intense rain: these 11 regions will be affected until October 29", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6241,'claude-haiku-5-5','2026-10-28T04:16:59Z',1,0.9,0,'{"actions_taken": ["Red alert issued for ten communes for risk of mass movements", "Class suspension in Las Condes", "Evacuation of 25 people in San Carlos de Apoquindo", "Evacuation of 16 people in Lo Barnechea"], "agencies": [{"country": "CL", "name": "Government of Chile (Metropolitan Region authorities)", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": ["website"], "event_date": "2026-10-27", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 41, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Minuto a minuto: sigue el avance de las lluvias en la zona oriente de la RM - La Tercera", "outcome": "not_reported", "outcome_justification": "The snippet reports alerts and evacuations but does not state whether the warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "A live news blog reports that ten communes in the Metropolitan Region of Santiago are under red alert for the risk of mass movements due to heavy rain. Authorities suspended classes in Las Condes and evacuated 25 people in San Carlos de Apoquindo and 16 in Lo Barnechea. The snippet does not describe how the warnings were disseminated or their lead time.", "summary_original": "Diez comunas de la Región Metropolitana están con alerta roja por riesgo de remociones en masa, con suspensión de clases en Las Condes y evacuaciones en San Carlos de Apoquindo y Lo Barnechea.", "title_en": "Live blog: follow the rainfall progress in the eastern zone of the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6245,'claude-haiku-5-5','2026-10-28T04:17:58Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Peruvian Amazon jungle (selva), Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "cold_wave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI pronostica lluvias y descenso de temperaturas por décimo cuarto friaje en la selva", "outcome": "not_reported", "outcome_justification": "The snippet describes a SENAMHI forecast of rain, lightning, wind and temperature drop from a friaje, but no outcome or impacts are reported.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, announced a forecast of rain, electrical discharges, stronger winds and falling temperatures in the Peruvian jungle caused by the fourteenth friaje (cold air incursion) of the season. The item is an official forecast bulletin published on SENAMHI''s website.", "summary_original": "El SENAMHI informa que la selva peruana tendrá lluvias, descargas eléctricas, aumento del viento y descenso de temperaturas por el décimo cuarto friaje, según un pronóstico oficial publicado en su portal.", "title_en": "SENAMHI forecasts rain and temperature drop due to the fourteenth friaje in the Peruvian jungle", "wmo_regions": ["III"]}');
