INSERT INTO "items" VALUES(1445,'https://www.preventionweb.net/news/same-day-heat-wave-and-wildfire-smoke-exposure-increasing-worldwide','https://preventionweb.net/news/same-day-heat-wave-and-wildfire-smoke-exposure-increasing-worldwide','Same-day heat wave and wildfire smoke exposure is increasing worldwide','samedayheatwaveandwildfiresmokeexposureisincreasingworldwide','preventionweb','PreventionWeb','en','2026-10-16T16:15:14Z','2026-10-18T03:04:05Z','A 20-year study found that global exposure to wildfires and heat waves occurring on the same days rose by 287 million from 2000 to 2019, with over half the world’s population experiencing these combined events.',2.0,'classified',NULL,NULL);
