INSERT INTO "items" VALUES(1456,'https://www.preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-pacific','https://preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-pacific','Disaster Risk Reduction State of Play in the Pacific','disasterriskreductionstateofplayinthepacific','preventionweb','PreventionWeb','en','2026-10-16T12:56:12Z','2026-10-18T03:04:05Z','This report reviews disaster risk reduction in the Pacific from 2023–2026, highlighting progress in governance and early warning, but noting gaps in implementation, data, and inclusion',3.0,'classified',NULL,54);
