INSERT INTO "items" VALUES(3717,'https://www.preventionweb.net/drr-community-voices/hospitals-have-disaster-plans-so-why-dont-staff-read-them-0','https://preventionweb.net/drr-community-voices/hospitals-have-disaster-plans-so-why-dont-staff-read-them-0','Hospitals have disaster plans. So why don''t staff read them?','hospitalshavedisasterplanssowhydontstaffreadthem','preventionweb','PreventionWeb','en','2026-10-22T08:10:37Z','2026-10-23T03:10:24Z','Author finds Greek hospital staff lack access to and training on disaster plans. The article calls for regular practical drills, dedicated preparedness officers, hospital vulnerability assessments and measurable readiness to strengthen emergency response.',1.0,'classified',NULL,NULL);
