INSERT INTO "items" VALUES(3721,'https://www.preventionweb.net/publication/documents-and-publications/resilience-starts-home-rethinking-disaster-risk-reduction','https://preventionweb.net/publication/documents-and-publications/resilience-starts-home-rethinking-disaster-risk-reduction','Resilience starts at home: Rethinking disaster risk reduction through diverse experiences of home','resiliencestartsathomerethinkingdisasterriskreductionthroughdiverseexperiencesofhome','preventionweb','PreventionWeb','en','2026-10-21T19:40:08Z','2026-10-23T03:10:24Z','This report explores how disaster risk reduction policies that center on "home" can overlook marginalized groups, urging inclusive approaches that recognize diverse living situations to ensure effective support and protection for all communities.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(3722,'https://www.preventionweb.net/news/extreme-weather-could-threaten-half-us-drinking-water-systems','https://preventionweb.net/news/extreme-weather-could-threaten-half-us-drinking-water-systems','Extreme weather could threaten half of U.S. drinking water systems','extremeweathercouldthreatenhalfofusdrinkingwatersystems','preventionweb','PreventionWeb','en','2026-10-21T19:39:09Z','2026-10-23T03:10:24Z','Climate change could threaten the reliability of half of U.S. drinking water utilities by 2050 through wildfires, heat, floods and rising seas. Experts urge utilities to assess risks and adapt infrastructure to protect safe water supplies.',1.0,'classified',NULL,NULL);
