INSERT INTO "stories" VALUES(80,'','flood','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": ["Anticipatory action using established triggers and beneficiary registries", "Development of flood risk insurance and a Community Protection Fund for post-flood payouts"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "BD", "name": "Bangladesh"}], "event_date": "2026-10-19", "event_location": "Bangladesh", "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "flood", "hazards": ["flood"], "id": 80, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes an initiative under development and does not report measured outcomes of warnings.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T13:15:36Z", "source_name": "PreventionWeb", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "title_en": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "url": "https://www.preventionweb.net/news/leveraging-anticipatory-action-disaster-risk-finance-lessons-bangladesh"}], "summaries_original": {}, "summary_en": "Bangladesh is building flood risk insurance and a Community Protection Fund by reusing its existing anticipatory action systems, including established flood triggers, beneficiary registries and delivery networks. The initiative adapts these early warning-linked mechanisms for post-flood payouts. The snippet does not report specific warning lead times or outcomes.", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "wmo_regions": ["II"]}');
