INSERT INTO "stories" VALUES(85,'landslide|US|alaska','landslide','2026-10-20T03:20:34Z','2026-10-22T03:09:53Z','2026-10-19','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.85, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-19", "event_location": "Alaska, United States", "event_name": null, "first_seen": "2026-10-20T03:14:36Z", "hazard": "landslide", "hazards": ["landslide"], "id": 85, "impacts": {}, "languages": ["en", "es"], "last_updated": "2026-10-22T03:09:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes a 2025 landslide-triggered tsunami in Alaska and scientists'' proposal for a progressive alert system, but reports no warnings actually issued or their outcomes.", "pillars": [1, 2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-19T17:30:00Z", "source_name": "cadena3.com", "title": "Un deslizamiento en Alaska provocó un tsunami que alcanzó 1,580 pies en la montaña", "title_en": "A landslide in Alaska caused a tsunami that reached 1,580 feet up a mountain", "url": "https://www.cadena3.com/noticia/ciencia/un-deslizamiento-en-alaska-provoco-un-tsunami-que-alcanzo-1580-pies-en-la-montana_604862"}, {"language": "en", "published_at": "2026-10-20T14:52:34Z", "source_name": "PreventionWeb", "title": "Alaska’s near‑record landslide tsunami sent a wave 1,580 feet up the fjord walls – and left clues for building a warning system", "title_en": "Alaska''s near-record landslide tsunami sent a wave 1,580 feet up the fjord walls – and left clues for building a warning system", "url": "https://www.preventionweb.net/news/alaskas-near-record-landslide-tsunami-sent-wave-1580-feet-fjord-walls-and-left-clues-0"}], "summaries_original": {"es": "Un deslizamiento masivo en Alaska desencadenó el segundo tsunami más alto registrado, enviando agua 1,580 pies hacia una montaña. Científicos advierten sobre señales previas que podrían ayudar a prevenir futuros desastres."}, "summary_en": "A 2025 landslide-triggered mega-tsunami in Alaska sent a wave 1,580 feet up fjord walls, highlighting growing risks as glaciers melt. Scientists propose a progressive alert system combining weather, glacier change and seismic monitoring to warn communities and vessels of potential landslides and tsunamis.", "title": "Alaska''s near-record landslide tsunami sent a wave 1,580 feet up the fjord walls – and left clues for building a warning system", "wmo_regions": ["IV"]}');
