INSERT INTO "stories" VALUES(91,'severe_storm|PE|coastal departments of peru (ancash and others)','severe_storm','2026-10-21T03:25:42Z','2026-10-21T03:21:48Z','2026-10-21','{"actions": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 427"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["website"], "confidence": 0.95, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-21", "event_location": "Coastal departments of Peru (Áncash and others)", "event_name": null, "first_seen": "2026-10-21T03:21:48Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 91, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-21T03:21:48Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes advisory recommendations issued after a SENAMHI warning but reports no outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante el incremento de la velocidad del viento en la costa", "title_en": "INDECI recommends preparedness measures ahead of increased coastal wind speeds", "url": "https://www.gob.pe/institucion/indeci/noticias/1459310-indeci-recomienda-medidas-de-preparacion-ante-el-incremento-de-la-velocidad-del-viento-en-la-costa"}], "summaries_original": {"es": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 427 del SENAMHI, que informa sobre el incremento de la velocidad del viento a lo largo de la costa, de moderada a extrema intensidad, de los departamentos de Áncash, y otros de la costa peruana."}, "summary_en": "INDECI recommends preparedness measures following SENAMHI Aviso N.° 427, which warns of increasing wind speeds of moderate to extreme intensity along Peru''s coast, including Áncash and other departments. The item shows a national agency relaying an NMHS warning into preparedness advice. No outcomes are reported in the snippet.", "title": "INDECI recommends preparedness measures ahead of increased coastal wind speeds", "wmo_regions": ["III"]}');
