INSERT INTO "stories" VALUES(99,'','tropical_cyclone','2026-10-21T03:26:06Z','2026-10-21T03:21:03Z','2026-10-20','{"actions": [], "agencies": [], "agency_types": [], "channels": ["website"], "confidence": 0.8, "countries": [], "event_date": "2026-10-20", "event_location": null, "event_name": null, "first_seen": "2026-10-21T03:21:03Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 99, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-21T03:21:03Z", "lead_time": null, "outcome": "mixed", "outcome_justification": "The study reports that hurricane forecast graphics have improved but many people still do not understand the real risk they face, which could endanger their safety.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-20T17:00:00Z", "source_name": "cadena3.com", "title": "Mejoran los mapas de advertencia de huracanes, pero persiste un problema peligroso", "title_en": "Hurricane warning maps improve, but a dangerous problem persists", "url": "https://www.cadena3.com/noticia/ciencia/mejoran-los-mapas-de-advertencia-de-huracanes-pero-persiste-un-problema-peligroso_605287"}], "summaries_original": {"es": "Un estudio de la Universidad Estatal de Florida indica que, a pesar de la mejora en los gráficos de pronóstico de huracanes, muchos aún no comprenden el riesgo real que enfrentan, lo que podría poner en peligro su seguridad."}, "summary_en": "A Florida State University study finds that hurricane forecast graphics have improved, yet many people still do not understand the actual risk they face, potentially endangering their safety. The item focuses on how warning products are interpreted by the public rather than on a specific event. The findings point to communication of forecast uncertainty and risk as the remaining gap.", "title": "Hurricane warning maps improve, but a dangerous problem persists", "wmo_regions": []}');
