ources": [{"language": "es", "published_at": "2026-10-20T20:45:00Z", "source_name": "elpais.com", "title": "Sistema frontal: alerta roja en Santiago por granizos, truenos e intensas lluvias", "title_en": "Frontal system: red alert in Santiago for hail, thunder and intense rain", "url": "https://elpais.com/chile/2026-10-20/sistema-frontal-alerta-roja-en-santiago-por-granizos-truenos-e-intensas-lluvias.html"}, {"language": "es", "published_at": "2026-10-21T03:21:03Z", "source_name": "biobiochile.cl", "title": "Declaran Alerta Roja en toda la región Metropolitana por llegada de intensas lluvias con granizos", "title_en": "Red Alert declared across the entire Metropolitan Region due to arrival of intense rain with hail", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/20/declaran-alerta-roja-en-toda-la-region-metropolitana-por-llegada-de-intensas-lluvias-con-granizos.shtml"}, {"language": "es", "published_at": "2026-10-21T03:21:03Z", "source_name": "publimetro.cl", "title": "Emergencia meteorológica en Santiago: Decretan Alerta Roja en la Región Metropolitana por fuertes lluvias y granizos", "title_en": "Weather emergency in Santiago: Red Alert declared in the Metropolitan Region due to heavy rain and hail", "url": "https://www.publimetro.cl/noticias/2026/10/20/decretan-alerta-roja-en-la-region-metropolitana-por-fuertes-lluvias-y-granizos/"}, {"language": "es", "published_at": "2026-10-21T03:21:03Z", "source_name": "biobiochile.cl", "title": "Orrego llama a no relajarse ante intensas lluvias: en Puente Alto han evacuado a 172 familias", "title_en": "Orrego calls not to relax amid intense rains: 172 families evacuated in Puente Alto", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/20/orrego-llama-a-no-relajarse-ante-intensas-lluvias-en-puente-alto-han-evacuado-a-172-familias.shtml"}, {"language": "es", "published_at": "2026-10-21T03:21:03Z", "source_name": "radiogennesis.cl", "title": "Senapred declaró alerta roja en la Región Metropolitana debido al evento meteorológico", "title_en": "Senapred declared red alert in the Metropolitan Region due to meteorological event", "url": "https://www.radiogennesis.cl/2026/10/20/senapred-declaro-alerta-roja-en-la-region-metropolitana-debido-al-evento-meteorologico/"}, {"language": "es", "published_at": "2026-10-23T03:19:31Z", "source_name": "biobiochile.cl", "title": "RM queda en Alerta Preventiva tras fuertes lluvias: comunas precordilleranas siguen \"amarillas\"", "title_en": "Metropolitan Region downgraded to Preventive Alert after heavy rain; pre-Andean communes remain yellow", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/22/rm-queda-en-alerta-preventiva-tras-fuertes-lluvias-comunas-precordilleranas-siguen-amarillas.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Roja en toda la región Metropolitana ante intensas lluvias y granizos, con alto riesgo de aluviones y remociones en masa en la precordillera, según la DMC y el director regional Miguel Muñoz."}, "summary_en": "Senapred declared a Red Alert across the entire Metropolitan Region of Chile due to intense rain and hail, with high risk of flash floods (aluviones) and mass movements in the foothills, according to the DMC and regional director Miguel Muñoz. The alert level is a high-severity warning issued ahead of the expected hazard.", "title": "Red Alert declared across the entire Metropolitan Region due to arrival of intense rain with hail", "wmo_regions": ["III"]}');
