INSERT INTO "stories" VALUES(104,'landslide|CL|villa el mirador','landslide','2026-10-21T03:26:24Z','2026-10-21T03:21:52Z','2026-10-21','{"actions": ["Declaration of Red Alert for the commune of Arauco", "Evacuation of more than 150 families"], "agencies": [{"country": "CL", "name": "Senapred (Servicio Nacional de Prevención y Respuesta ante Desastres)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.85, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-21", "event_location": "Villa El Mirador, Arauco, Bío Bío Region, Chile", "event_name": null, "first_seen": "2026-10-21T03:21:52Z", "hazard": "landslide", "hazards": ["landslide"], "id": 104, "impacts": {"evacuated": 150}, "languages": ["es"], "last_updated": "2026-10-21T03:21:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports the Red Alert declaration and evacuation of over 150 families, but does not state whether the warning or evacuation outcomes were positive or negative.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-21T00:45:43Z", "source_name": "BioBioChile nacional", "title": "Evacúan a más de 150 familias por socavón de medio kilómetro y declaran Alerta Roja para Arauco", "title_en": "More than 150 families evacuated due to half-kilometre sinkhole and Red Alert declared for Arauco", "url": "https://www.biobiochile.cl/noticias/nacional/region-del-bio-bio/2026/10/20/evacuan-a-mas-de-150-familias-por-enorme-socavon-y-declaran-alerta-roja-para-la-comuna-de-arauco.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Roja en la comuna de Arauco tras una remoción en masa de unos medio kilómetro en el sector Villa El Mirador, ocurrida hace alrededor de una semana, y se evacuaron más de 150 familias."}, "summary_en": "Chile''s national disaster service Senapred declared a Red Alert for the commune of Arauco after a mass movement of about half a kilometre opened a large sinkhole in the Villa El Mirador sector, which occurred roughly a week earlier. More than 150 families were evacuated as a result. The item focuses on the alert and evacuation response rather than on monitoring or forecasting.", "title": "More than 150 families evacuated due to half-kilometre sinkhole and Red Alert declared for Arauco", "wmo_regions": ["III"]}');
