INSERT INTO "stories" VALUES(167,'flood|JM|st thomas','flash_flood','2026-10-25T04:20:55Z','2026-10-25T04:08:27Z','2026-10-24','{"actions": ["Flash flood watch issued for eight parishes, valid until 5 p.m. Sunday"], "agencies": [{"country": "JM", "name": "Meteorological Service of Jamaica", "type": "NMHS"}, {"country": "JM", "name": "Jamaica Gleaner", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "JM", "name": "Jamaica"}], "event_date": "2026-10-24", "event_location": "St Thomas, Jamaica", "event_name": null, "first_seen": "2026-10-25T04:08:27Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 167, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-25T04:08:27Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The article reports the issuance of a flash flood watch and resulting landslide and flooding impacts, but does not state whether the warning led to specific protective actions or what the outcome was for the stranded students.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-24T09:00:00Z", "source_name": "jamaica-gleaner.com", "title": "8 parishes on alert as rains trigger landslides, flooding", "title_en": "8 parishes on alert as rains trigger landslides, flooding", "url": "https://jamaica-gleaner.com/article/news/20261024/8-parishes-alert-rains-trigger-landslides-flooding"}], "summaries_original": {}, "summary_en": "The Meteorological Service of Jamaica issued a flash flood watch covering eight parishes, in effect until 5 p.m. Sunday, after heavy rainfall triggered a major landslide that stranded 15 students and several teachers at Johnson Mountain Primary School in St Thomas. The watch covers low-lying and flood-prone areas across St Ann, St Mary, Portland, St Thomas, Kingston, St Andrew, St Catherine and Clarendon.", "title": "8 parishes on alert as rains trigger landslides, flooding", "wmo_regions": ["IV"]}');
