INSERT INTO "stories" VALUES(169,'flood|IN|malappuram','heavy_rain','2026-10-25T04:21:01Z','2026-10-26T04:11:51Z','2026-10-24','{"actions": ["Red alert issued for Malappuram, Kozhikode and Wayanad", "Orange warnings issued for seven districts", "School classes suspended", "Tourism banned in affected districts", "Red alerts issued for Malappuram, Kozhikode and Wayanad", "Schools ordered shut in affected districts", "Tourist destinations ordered shut in affected districts", "Orange alerts issued in 10 districts and yellow alert in Kasaragod"], "agencies": [{"country": "IN", "name": "India Meteorological Department (IMD)", "type": "NMHS"}, {"country": "IN", "name": "Indian Meteorological Department Thiruvananthapuram", "type": "NMHS"}, {"country": "IN", "name": "Kerala state government", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-10-24", "event_location": "Malappuram, Kozhikode, Wayanad, Kerala, India", "event_name": "Cyclone Arnab", "first_seen": "2026-10-25T04:08:27Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 169, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-26T04:11:51Z", "lead_time": "not stated (warning issued for Sunday)", "outcome": "not_reported", "outcome_justification": "The snippet describes warnings and precautionary closures but does not report actual impacts or how the warnings performed.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-24T19:15:00Z", "source_name": "timesofindia.indiatimes.com", "title": "3 districts on red alert, 7 on orange warning on Sunday", "title_en": "3 districts on red alert, 7 on orange warning on Sunday", "url": "https://timesofindia.indiatimes.com/city/kochi/3-districts-on-red-alert-7-on-orange-warning-on-sunday/articleshow/135176533.cms"}, {"language": "en", "published_at": "2026-10-25T05:30:00Z", "source_name": "newindianexpress.com", "title": "Cyclone Arnab effect: Red alert issued in three Keralam districts on Oct 25", "title_en": "Cyclone Arnab effect: Red alert issued in three Keralam districts on Oct 25", "url": "https://www.newindianexpress.com/states/kerala/2026/Oct/25/cyclone-arnab-effect-red-alert-issued-in-three-keralam-districts-on-oct-25"}, {"language": "en", "published_at": "2026-10-25T08:00:00Z", "source_name": "freepressjournal.in", "title": "Kerala Heavy Rains October 25: IMD Issues Red Alert In 3 Districts, Schools & Tourist Spots Shut", "title_en": "Kerala Heavy Rains October 25: IMD Issues Red Alert In 3 Districts, Schools & Tourist Spots Shut", "url": "https://www.freepressjournal.in/india/kerala-heavy-rains-october-25-imd-issues-red-alert-in-3-districts-schools-tourist-spots-shut"}], "summaries_original": {}, "summary_en": "IMD warned of more than 20 cm of rain in Kerala, placing Malappuram, Kozhikode and Wayanad under red alert and seven other districts under orange warning for Sunday. Schools were closed and tourism banned in the affected districts, and a cyclone may form, according to the report.", "title": "3 districts on red alert, 7 on orange warning on Sunday", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(170,'flood|CO|santa marta','flash_flood','2026-10-25T04:21:01Z','2026-10-26T04:15:00Z','2026-10-24','{"actions": ["Santa Marta mayor''s office declared a red alert for floods and risk of flash floods on two rivers, based on the latest IDEAM report"], "agencies": [{"country": "CO", "name": "IDEAM", "type": "NMHS"}, {"country": "CO", "name": "El Tiempo", "type": "media"}, {"country": "CO", "name": "Alcaldía de Santa Marta", "type": "other_national_agency"}], "agency_types": ["NMHS", "media", "other_national_agency"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "CO", "name": "Colombia"}], "event_date": "2026-10-24", "event_location": "Santa Marta, Colombia", "event_name": null, "first_seen": "2026-10-25T04:16:26Z", "hazard": "flash_flood", "hazards": ["flash_flood", "flood", "heavy_rain"], "id": 170, "impacts": {"affected": 670}, "languages": ["es"], "last_updated": "2026-10-26T04:15:00Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert declaration and IDEAM-based recommendations but gives no information on the outcome of the warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-24T23:56:26Z", "source_name": "El Tiempo (Colombia)", "title": "Emergencias por lluvias en el Caribe: primeros balances de inundaciones y desbordamientos en varias ciudades; se esperan más precipitaciones", "title_en": "Caribbean rain emergencies: first reports of floods and overflows in several cities; more rainfall expected", "url": "https://www.eltiempo.com/colombia/otras-ciudades/alcaldia-de-santa-marta-declara-alerta-roja-por-inundaciones-y-riesgo-de-crecientes-subitas-en-dos-rios-estas-son-las-recomendaciones-del-ideam-3596073"}, {"language": "es", "published_at": "2026-10-25T18:00:00Z", "source_name": "portafolio.co", "title": "Alerta roja en Santa Marta por lluvias: Ideam prevé más aguaceros", "title_en": "Red alert in Santa Marta due to rains: IDEAM forecasts more downpours", "url": "https://www.portafolio.co/economia/gobierno/alerta-roja-en-santa-marta-por-lluvias-ideam-preve-mas-aguaceros-en-otras-regiones-del-pais-505072"}, {"language": "es", "published_at": "2026-10-25T18:41:58Z", "source_name": "El Tiempo (Colombia)", "title": "Lluvias golpean al Caribe: más de 670 viviendas y familias afectadas en Cartagena y Santa Marta; inundaciones y emergencias en cinco departamentos", "title_en": "Rains hit the Caribbean: more than 670 homes and families affected in Cartagena and Santa Marta; floods and emergencies in five departments", "url": "https://www.eltiempo.com/colombia/barranquilla/lluvias-golpean-al-caribe-mas-de-670-viviendas-y-familias-afectadas-en-cartagena-y-santa-marta-inundaciones-y-emergencias-en-cinco-departamentos-3596177"}], "summaries_original": {"es": "La Alcaldía de Santa Marta declaró alerta roja por inundaciones y riesgo de crecientes súbitas en dos ríos, con base en el más reciente reporte del IDEAM, que emitió recomendaciones para la población."}, "summary_en": "The Santa Marta municipal government declared a red alert for flooding and the risk of flash floods on two rivers, based on the latest IDEAM hydrometeorological report, and issued recommendations to residents. Further rainfall was expected across Caribbean cities. The snippet gives no details on dissemination or outcomes.", "title": "Caribbean rain emergencies: first reports of floods and overflows in several cities; more rainfall expected", "wmo_regions": ["III", "IV"]}');
INSERT INTO "stories" VALUES(171,'earthquake|JP|western off-shore of ogasawara islands','earthquake','2026-10-25T04:21:03Z','2026-10-25T04:08:40Z','2026-10-25','{"actions": ["Issued earthquake information with seismic intensity observations and tsunami assessment (no tsunami concern)"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["tv", "website"], "confidence": 0.9, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-25", "event_location": "Western off-shore of Ogasawara Islands, Japan", "event_name": null, "first_seen": "2026-10-25T04:08:40Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 171, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-25T04:08:40Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports the earthquake detection and the tsunami assessment but does not describe any impacts or the effect of the warnings.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-25T02:56:28Z", "source_name": "NHK ニュース 主要", "title": "【地震速報】小笠原で震度3 津波の心配なし", "title_en": "[Earthquake alert] Seismic intensity 3 in Ogasawara, no tsunami concern", "url": "https://news.web.nhk/newsweb/na/nd-20261025de65049"}], "summaries_original": {"ja": "25日午前11時10分ごろ、小笠原諸島西方沖の深い場所を震源とする地震があり、小笠原諸島で震度3の揺れを観測したほか、東北から東海にかけての広い範囲で震度2や1の揺れを観測しました。この地震による津波の心配はないとされています。"}, "summary_en": "A deep earthquake west of the Ogasawara Islands at about 11:10 local time on 25 October produced seismic intensity 3 in the Ogasawara Islands and intensity 1-2 across a wide area from Tohoku to Tokai. The early earthquake information stated there was no tsunami concern.", "title": "[Earthquake alert] Seismic intensity 3 in Ogasawara, no tsunami concern", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(172,'flood|JP|northern wakayama prefecture','heavy_rain','2026-10-25T04:21:07Z','2026-10-29T04:12:17Z','2026-10-25','{"actions": ["JMA issued a linear rainband immediate forecast (線状降水帯直前予測) for northern Wakayama Prefecture at 10:58 on 25 October", "JMA called for caution about very heavy rain persisting in the same area", "JMA issued a ''linear rainband immediate forecast'' meteorological disaster alert (気象防災速報) at 10:58 for northern Wakayama Prefecture", "JMA issued a linear rainband immediate forecast (senjo kosuitai chokuzen yosoku) for northern Wakayama Prefecture at 10:58 JST", "Level 4 sediment disaster danger warning issued for Arida City and Yuasa Town", "Issued linear rainband ''imminent prediction'' (線状降水帯直前予測) for northern Wakayama Prefecture", "Issued Level 4 sediment disaster danger warning (土砂災害危険警報) for Arida City and surrounding areas", "Issued Level 3 heavy rain warning (大雨警報)"], "agencies": [{"country": "JP", "name": "JMA (AMeDAS observation network)", "type": "NMHS"}, {"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Japan Meteorological Agency (JMA) / Wakayama Local Meteorological Observatory", "type": "NMHS"}, {"country": "JP", "name": "FNN Prime Online (Fuji TV)", "type": "media"}, {"country": "JP", "name": "Japan Weather Association (tenki.jp)", "type": "media"}, {"country": "JP", "name": "MBS (Mainichi Broadcasting System)", "type": "media"}, {"country": "JP", "name": "Mainichi Shimbun", "type": "media"}, {"country": "JP", "name": "NHK", "type": "media"}, {"country": "JP", "name": "Weathernews", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other", "tv", "website"], "confidence": 0.97, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-25", "event_location": "Northern Wakayama Prefecture, Japan", "event_name": null, "first_seen": "2026-10-25T04:08:41Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 172, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-29T04:12:17Z", "lead_time": "within the next 3 hours", "outcome": "not_reported", "outcome_justification": "The snippet reports only the issuance of the forecast and call for caution; no outcome or impacts are described.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-25T02:58:57Z", "source_name": "毎日新聞 (Mainichi Shimbun)", "title": "和歌山県北部に線状降水帯直前予測 気象庁が注意呼びかけ", "title_en": "Japan Meteorological Agency issues linear rainband immediate forecast for northern Wakayama Prefecture, calls for caution", "url": "https://mainichi.jp/articles/20261025/k00/00m/040/059000c"}, {"language": "ja", "published_at": "2026-10-25T04:11:37Z", "source_name": "news.web.nhk", "title": "和歌山県北部に「線状降水帯直前予測」", "title_en": "\"Linear rainband immediate forecast\" issued for northern Wakayama Prefecture", "url": "https://news.web.nhk/newsweb/na/nd-20261025de65051"}, {"language": "ja", "published_at": "2026-10-25T04:12:47Z", "source_name": "tenki.jp", "title": "【速報】和歌山県北部は今後3時間以内に線状降水帯発生のおそれ 25日11時頃発表(気象予報士 日直主任 2026年10月25日) - 日本気象協会 tenki.jp", "title_en": "[Flash] Northern Wakayama Prefecture at risk of linear rainband formation within 3 hours; announced around 11:00 on 25 October", "url": "https://tenki.jp/forecaster/deskpart/2026/10/25/41085.html"}, {"language": "ja", "published_at": "2026-10-25T04:12:47Z", "source_name": "weathernews.jp", "title": "和歌山県で線状降水帯が発生のおそれ 大雨に厳重警戒 - ウェザーニュース", "title_en": "Possible linear rainband in Wakayama Prefecture; heavy rain warning - Weathernews", "url": "https://weathernews.jp/news/202610/250121/"}, {"language": "ja", "published_at": "2026-10-25T04:12:47Z", "source_name": "news.yahoo.co.jp", "title": "和歌山県北部に「線状降水帯直前予測」非常に激しい雨が降り続くおそれ高まる 和歌山市の1時間雨量は10月の観測史上最大を記録（MBSニュース） - Yahoo!ニュース", "title_en": "Linear rainband ''imminent prediction'' issued for northern Wakayama Prefecture; very heavy rain expected to continue; Wakayama City records October hourly rainfall record (MBS News)", "url": "https://news.yahoo.co.jp/articles/09d6c26aa09e8cc6001d2a7b3859506382e453a3"}, {"language": "ja", "published_at": "2026-10-25T04:12:47Z", "source_name": "news.web.nhk", "title": "和歌山県北部に「線状降水帯直前予測」の気象防災速報", "title_en": "Japan Meteorological Agency issues ''linear rainband imminent forecast'' weather disaster bulletin for northern Wakayama Prefecture", "url": "https://news.web.nhk/newsweb/na/nd-20261025de65053"}, {"language": "ja", "published_at": "2026-10-25T04:12:54Z", "source_name": "news.yahoo.co.jp", "title": "和歌山県北部に「線状降水帯」発生の恐れ（10時58分時点）（FNNプライムオンライン（フジテレビ系）） - Yahoo!ニュース", "title_en": "Possible formation of a linear rainband (senjo kosuitai) in northern Wakayama Prefecture (as of 10:58) (FNN Prime Online, Fuji TV affiliate) - Yahoo! News", "url": "https://news.yahoo.co.jp/articles/11a0209c17a9aefdd5554a9c45a805288292c23a"}, {"language": "ja", "published_at": "2026-10-26T04:12:47Z", "source_name": "news.web.nhk", "title": "前線と台風影響で大雨 和歌山で線状降水帯直前予測 厳重警戒を", "title_en": "Frontal and typhoon-related heavy rain; quasi-stationary heavy rain band forecast imminent in Wakayama, strict vigilance urged", "url": "https://news.web.nhk/newsweb/na/nd-20261025de65122"}, {"language": "ja", "published_at": "2026-10-27T04:12:11Z", "source_name": "wacoca.com", "title": "台風と秋雨前線で大雨に 和歌山県 線状降水帯の恐れ（テレビ朝日系（ANN）） - Yahoo!ニュース - News", "title_en": "Typhoon and autumn rain front bring heavy rain; Wakayama Prefecture at risk of linear rainband (TV Asahi/ANN, via Yahoo! News)", "url": "https://wacoca.com/news/2967400"}], "summaries_original": {"ja": "気象庁は25日午前10時58分、和歌山県北部に線状降水帯直前予測を出した。今後3時間以内に線状降水帯が発生し、同じ場所で非常に激しい雨が降り続く可能性が高まっているとして注意を呼び掛けている。"}, "summary_en": "The Japan Meteorological Agency issued a linear rainband immediate forecast for northern Wakayama Prefecture at 10:58 on 25 October, warning that a linear rainband could form within three hours and bring persistently very heavy rain to the same area. JMA called on residents to remain cautious. The item covers the forecast and warning issuance only, with no reported outcomes.", "title": "Japan Meteorological Agency issues linear rainband immediate forecast for northern Wakayama Prefecture, calls for caution", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(173,'named|no 30','heavy_rain','2026-10-25T04:21:07Z','2026-10-28T04:11:13Z','2026-10-25','{"actions": ["Broadcast of typhoon information and forecast of linear rainband (senjou kōsuitai) just before Wakayama", "JMA advised caution against landslides and inundation of low-lying areas"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}, {"country": "JP", "name": "Osaka Regional Meteorological Observatory (JMA)", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other", "tv", "website"], "confidence": 0.93, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-25", "event_location": "Kinki region, Japan", "event_name": "Typhoon No. 30", "first_seen": "2026-10-25T04:08:40Z", "hazard": "heavy_rain", "hazards": ["heavy_rain", "multi_hazard"], "id": 173, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-28T04:11:13Z", "lead_time": "from late morning on 25 October through 26 October", "outcome": "not_reported", "outcome_justification": "The item reports a forecast/advisory of possible warning-level heavy rain; no outcome is yet described.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-25T03:02:00Z", "source_name": "NHK ニュース 主要", "title": "【台風30号情報】 前線活動活発に 和歌山に線状降水帯直前予測", "title_en": "[Typhoon No. 30 information] Active frontal activity; heavy rain band forecast just before Wakayama", "url": "https://news.web.nhk/newsweb/na/nd-20261024de64932"}, {"language": "ja", "published_at": "2026-10-25T04:45:00Z", "source_name": "kyoto-np.co.jp", "title": "【 速報 】【 台風30号 】 近畿地方 、 きょう25日～警報級大雨の可能性 「 温低 」 で接近 、 強雨ピーク2回か｜京都新聞デジタル 京都 ・ 滋賀のニュースサイト", "title_en": "[Breaking] Typhoon No. 30: Kinki region may see warning-level heavy rain from the 25th; warm low approaches with two rain peaks likely", "url": "https://www.kyoto-np.co.jp/articles/-/1814472"}, {"language": "ja", "published_at": "2026-10-26T03:11:00Z", "source_name": "NHK ニュース 主要", "title": "台風30号は温帯低気圧に 西～東日本で非常に激しい雨のおそれ", "title_en": "Typhoon No. 30 becomes extratropical cyclone; very heavy rain feared from western to eastern Japan", "url": "https://news.web.nhk/newsweb/na/nd-20261026de65420"}, {"language": "ja", "published_at": "2026-10-26T15:00:00Z", "source_name": "気象庁 (JMA)", "title": "令和８年台風第25号による大雨の状況について～「災害をもたらした気象事例」に資料を掲載しました～", "title_en": "Heavy rain caused by Typhoon No. 25 (2026) — materials added to the ''Meteorological Events That Caused Disasters'' page", "url": "https://www.jma.go.jp/jma/press/2610/27a/20261027_saimota.html"}], "summaries_original": {"ja": "大阪管区気象台は25日朝、大雨に関する気象情報を発表し、台風30号などの影響で近畿地方は25日昼前～26日にかけて警報級大雨の可能性があるとした。温低の接近により強雨のピークが2回来る見込み。"}, "summary_en": "The Osaka Regional Meteorological Observatory issued a heavy-rain weather information on the morning of 25 October stating that Typhoon No. 30 and related effects could bring warning-level heavy rain to the Kinki region from late morning on 25 October into 26 October. The approaching warm low is expected to produce two peaks of heavy rain.", "title": "[Breaking] Typhoon No. 30: Kinki region may see warning-level heavy rain from the 25th; warm low approaches with two rain peaks likely", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(174,'','other','2026-10-26T04:16:51Z','2026-10-26T04:14:47Z','2026-10-26','{"actions": ["Held national workshop to update procedures for elaborating meteorological warnings"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-26", "event_location": "Peru", "event_name": null, "first_seen": "2026-10-26T04:14:47Z", "hazard": "other", "hazards": ["other"], "id": 174, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-26T04:14:47Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes an internal procedural update workshop; no hazard event or warning outcome is reported.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI reunió a especialistas de todo el país para actualizar procedimientos de elaboración de avisos meteorológicos", "title_en": "SENAMHI gathered specialists from across the country to update procedures for issuing meteorological warnings", "url": "https://www.gob.pe/institucion/senamhi/noticias/1462286-senamhi-reunio-a-especialistas-de-todo-el-pais-para-actualizar-procedimientos-de-elaboracion-de-avisos-meteorologicos"}], "summaries_original": {"es": "El SENAMHI de Perú desarrolló un taller nacional con especialistas de todo el país para actualizar los procedimientos de elaboración de avisos meteorológicos."}, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, held a national workshop with specialists from across the country to update its procedures for issuing meteorological warnings. The item concerns the institutional process for warning production rather than a specific hazard event. It is relevant to the forecasting and warning pillars of Early Warnings for All.", "title": "SENAMHI gathered specialists from across the country to update procedures for issuing meteorological warnings", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(175,'flood|PE|north coast and highlands','heavy_rain','2026-10-26T04:16:56Z','2026-10-26T04:14:57Z','2026-10-26','{"actions": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 435 (red level)"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-26", "event_location": "North coast and highlands, Peru", "event_name": null, "first_seen": "2026-10-26T04:14:57Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 175, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-26T04:14:57Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a recommendation issued in response to a SENAMHI red-level warning but reports no outcome.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante la continuidad de las precipitaciones en la costa norte y sierra.", "title_en": "INDECI recommends preparedness measures ahead of continued rainfall on the north coast and highlands", "url": "https://www.gob.pe/institucion/indeci/noticias/1462256-indeci-recomienda-medidas-de-preparacion-ante-la-continuidad-de-las-precipitaciones-en-la-costa-norte-y-sierra"}], "summaries_original": {"es": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 435 (nivel rojo) del SENAMHI, que informa sobre la continuidad de las precipitaciones de ligera a moderada intensidad en la sierra y costa norte del Perú."}, "summary_en": "INDECI issued a press release recommending preparedness measures in response to SENAMHI Aviso N.° 435 (red level), which warns of continued light to moderate rainfall in the highlands and north coast of Peru. The notice shows a national agency relaying an NMHS red-level warning to the public and response actors. No outcome is reported in the snippet.", "title": "INDECI recommends preparedness measures ahead of continued rainfall on the north coast and highlands", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(176,'','earthquake','2026-10-26T04:16:58Z','2026-10-26T04:14:39Z','2026-10-24','{"actions": ["Tsunami alert issued and later withdrawn by authorities"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.85, "countries": [{"code": "VU", "name": "Vanuatu"}], "event_date": "2026-10-24", "event_location": "Vanuatu", "event_name": null, "first_seen": "2026-10-26T04:14:39Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 176, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-26T04:14:39Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports a tsunami alert being issued and then lifted while damage was assessed, but gives no information on impacts or whether the warning was received or acted upon.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-24T12:15:00Z", "source_name": "negocios.com", "title": "Un terremoto de 6,9 sacude Vanuatu y desata una alerta por tsunami", "title_en": "A magnitude 6.9 earthquake shakes Vanuatu and triggers a tsunami alert", "url": "https://www.negocios.com/articulo/geociencia-espacio/terremoto-69-sacude-vanuatu-desata-alerta-tsunami/20261024094342496425.html"}], "summaries_original": {"es": "Un potente seísmo golpea el Pacífico Sur, seguido de una réplica de magnitud 6,3. Las autoridades retiran la alerta de tsunami mientras evalúan los posibles efectos."}, "summary_en": "A magnitude 6.9 earthquake struck the South Pacific near Vanuatu, followed by a magnitude 6.3 aftershock. Authorities issued a tsunami alert, which was withdrawn while they assessed possible effects. The snippet does not describe impacts or how the warning was disseminated.", "title": "A magnitude 6.9 earthquake shakes Vanuatu and triggers a tsunami alert", "wmo_regions": ["V"]}');
INSERT INTO "stories" VALUES(177,'flood|AR|comallo','flash_flood','2026-10-26T04:17:05Z','2026-10-26T04:14:39Z','2026-10-24','{"actions": ["Firefighters assisted affected families", "Preventive evacuation of residents"], "agencies": [{"country": "AR", "name": "Bomberos (fire brigade)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.7, "countries": [{"code": "AR", "name": "Argentina"}], "event_date": "2026-10-24", "event_location": "Comallo, Río Negro, Argentina", "event_name": null, "first_seen": "2026-10-26T04:14:39Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 177, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-26T04:14:39Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The title reports a preventive evacuation and assistance but gives no information on whether warnings were issued in advance or on their effectiveness.", "pillars": [4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-24T22:00:00Z", "source_name": "bariloche2000.com", "title": "Comallo: bomberos asistieron a familias por la crecida de un arroyo y hubo evacuación preventiva", "title_en": "Comallo: firefighters assisted families over a stream flood and a preventive evacuation took place", "url": "https://www.bariloche2000.com/sociedad/comallo-bomberos-asistieron-a-familias-por-la-crecida-de-un-arroyo-y-hubo-evacuacion-preventiva-20261024-0008.html"}], "summaries_original": {"es": "Bomberos asistieron a familias en Comallo por la crecida de un arroyo y se realizó una evacuación preventiva; la nota no indica si hubo aviso previo ni su forma de difusión."}, "summary_en": "Firefighters in Comallo, Río Negro, Argentina, assisted families affected by the rising waters of a stream, and a preventive evacuation was carried out. The item does not state whether a forecast or warning preceded the evacuation or how it was communicated.", "title": "Comallo: firefighters assisted families over a stream flood and a preventive evacuation took place", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(178,'named|vance','tropical_cyclone','2026-10-26T04:17:06Z','2026-10-26T04:14:39Z','2026-10-24','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "MX", "name": "Mexico"}], "event_date": "2026-10-24", "event_location": "Michoacán, Colima and Jalisco coasts, Mexico", "event_name": "Hurricane Vance", "first_seen": "2026-10-26T04:14:39Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 178, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-26T04:14:39Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports a forecast of intensification and approach but no warning dissemination or outcomes are described.", "pillars": [2], "review": false, "sources": [{"language": "es", "published_at": "2026-10-24T23:30:00Z", "source_name": "diariodelsur.com.co", "title": "Huracán Vance se fortalece y amenaza las costas del Pacífico | DIARIO DEL SUR", "title_en": "Hurricane Vance strengthens and threatens Pacific coasts", "url": "http://diariodelsur.com.co/noticias/huracan-vance-se-fortalece-y-amenaza-las-costas-del-pacifico-mexicano"}], "summaries_original": {"es": "El huracán Vance alcanzó categoría 2 frente a México y podría intensificarse antes de acercarse a las costas de Michoacán, Colima y Jalisco."}, "summary_en": "Hurricane Vance reached Category 2 off Mexico and was expected to intensify before approaching the coasts of Michoacán, Colima and Jalisco. The item reports the hazard forecast but not specific warnings or responses.", "title": "Hurricane Vance strengthens and threatens Pacific coasts", "wmo_regions": ["IV"]}');
INSERT INTO "stories" VALUES(179,'tropical_cyclone|IN|odisha','tropical_cyclone','2026-10-26T04:17:06Z','2026-10-29T04:10:36Z','2026-10-25','{"actions": ["Shelters and evacuation measures arranged", "District control rooms set up", "Rescue teams arranged", "Coast Guard guiding vessels to shore", "IMD advised residents in vulnerable coastal housing to move to safer places", "Review of preparations by Andhra Pradesh and Odisha governments", "Officials directed to protect residents in low-lying areas", "Evacuation of nearly 100,000 people in Andhra Pradesh and Odisha"], "agencies": [{"country": "IN", "name": "India Meteorological Department (IMD)", "type": "NMHS"}, {"country": null, "name": "GDACS", "type": "international"}, {"country": "IN", "name": "Andhra Pradesh state government", "type": "other_national_agency"}, {"country": "IN", "name": "Indian Coast Guard", "type": "other_national_agency"}, {"country": "IN", "name": "Indian authorities", "type": "other_national_agency"}, {"country": "IN", "name": "National Crisis Management Committee", "type": "other_national_agency"}, {"country": "NP", "name": "Nepal weather authorities", "type": "other_national_agency"}, {"country": "IN", "name": "Odisha state government", "type": "other_national_agency"}, {"country": "LK", "name": "Sri Lanka weather authorities", "type": "other_national_agency"}], "agency_types": ["NMHS", "international", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.97, "countries": [{"code": "IN", "name": "India"}, {"code": "LK", "name": "Sri Lanka"}, {"code": "NP", "name": "Nepal"}], "event_date": "2026-10-25", "event_location": "Andhra Pradesh–Yanam coast, India", "event_name": "Cyclone Arnab", "first_seen": "2026-10-26T04:10:42Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 179, "impacts": {"affected": 356000, "evacuated": 100000}, "languages": ["en"], "last_updated": "2026-10-29T04:10:36Z", "lead_time": "ahead of October 28 landfall (reviewed October 26)", "outcome": "not_reported", "outcome_justification": "The snippet describes preparations and warnings but does not report outcomes such as casualties or evacuation results.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-25T04:11:51Z", "source_name": "vajiramandravi.com", "title": "Odisha Cyclone Alert 2026, Date, Name, Latest Update, Tracker", "title_en": "Odisha Cyclone Alert 2026, Date, Name, Latest Update, Tracker", "url": "https://vajiramandravi.com/current-affairs/odisha-cyclone/"}, {"language": "en", "published_at": "2026-10-25T05:30:00Z", "source_name": "timesofindia.indiatimes.com", "title": "Weather tomorrow: IMD forecasts rain, thunderstorms in 9 states; cyclone to hit Andhra and Odisha, Keralam under red alert", "title_en": "Weather tomorrow: IMD forecasts rain, thunderstorms in 9 states; cyclone to hit Andhra and Odisha, Keralam under red alert", "url": "https://timesofindia.indiatimes.com/city/delhi/weather-tomorrow-imd-forecasts-rain-thunderstorms-in-8-states-cyclone-to-hit-andhra-odisha-keralam-under-red-alert/articleshow/135183124.cms"}, {"language": "en", "published_at": "2026-10-25T09:30:00Z", "source_name": "livemint.com", "title": "Cyclone Arnab: Depression over Bay of Bengal to intensify; when and where will landfall occur? IMD latest updates", "title_en": "Cyclone Arnab: Depression over Bay of Bengal to intensify; when and where will landfall occur? IMD latest updates", "url": "https://www.livemint.com/news/india/cyclone-arnab-depression-over-bay-of-bengal-to-intensify-when-and-where-will-landfall-occur-imds-latest-updates-11792917730320.html"}, {"language": "en", "published_at": "2026-10-26T01:51:40Z", "source_name": "GDACS", "title": "Orange notification for tropical cyclone TWO-26. Population affected by Category 1 (120 km/h) wind speeds or higher is 0.356 million .", "title_en": "Orange notification for tropical cyclone TWO-26. Population affected by Category 1 (120 km/h) wind speeds or higher is 0.356 million.", "url": "http://www.gdacs.org/report.aspx?eventtype=TC&eventid=1001345"}, {"language": "en", "published_at": "2026-10-28T04:10:32Z", "source_name": "watchers.news", "title": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India - The Watchers", "title_en": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India", "url": "https://watchers.news/2026/10/27/very-severe-cyclone-arnab-nears-andhra-pradesh-yanam-coast-ahead-of-october-28-landfall-india"}, {"language": "en", "published_at": "2026-10-28T04:10:57Z", "source_name": "france24.com", "title": "India orders evacuations as Cyclone Arnab looms", "title_en": "India orders evacuations as Cyclone Arnab looms", "url": "https://france24.com/en/live-news/20261027-india-orders-evacuations-as-cyclone-arnab-looms"}], "summaries_original": {}, "summary_en": "The National Crisis Management Committee reviewed cyclone preparations on October 26, arranging shelters, evacuation measures, district control rooms and rescue teams ahead of Very Severe Cyclone Arnab''s expected landfall on October 28. IMD advised residents of vulnerable coastal housing to move to safer places, and the Coast Guard guided vessels to shore.", "title": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(180,'other|PE|marcapomacocha','other','2026-10-27T04:20:57Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Participatory PICSA climate services workshop with farmers on decisions related to frost, snowfall and rainfall variability"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Marcapomacocha, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "other", "hazards": ["other"], "id": 180, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a capacity-building workshop on climate services; no warning outcomes are reported.", "pillars": [1, 2, 3], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI desarrolla segundo taller PICSA en Marcapomacocha para fortalecer decisiones frente a heladas, nevadas y variabilidad de lluvias", "title_en": "SENAMHI develops second PICSA workshop in Marcapomacocha to strengthen decisions on frost, snowfall and rainfall variability", "url": "https://www.gob.pe/institucion/senamhi/noticias/1462533-senamhi-desarrolla-segundo-taller-picsa-en-marcapomacocha-para-fortalecer-decisiones-frente-a-heladas-nevadas-y-variabilidad-de-lluvias"}], "summaries_original": {"es": "El SENAMHI desarrolló el segundo taller participativo PICSA con comuneros de Marcapomacocha para fortalecer decisiones frente a heladas, nevadas y variabilidad de lluvias, bajo el enfoque de Servicios Climáticos Integrados y Participativos para la Agricultura."}, "summary_en": "SENAMHI held a second participatory PICSA (Integrated and Participatory Climate Services for Agriculture) workshop with community members in Marcapomacocha to strengthen decision-making against frost, snowfall and rainfall variability. The initiative focuses on translating climate information into actionable guidance for farmers. No specific warning event or outcome is described in the snippet.", "title": "SENAMHI develops second PICSA workshop in Marcapomacocha to strengthen decisions on frost, snowfall and rainfall variability", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(181,'','multi_hazard','2026-10-27T04:20:59Z','2026-10-27T04:18:46Z','2026-10-27','{"actions": ["Inter-institutional working meeting between INDECI and UNHCR to strengthen cooperation for preparedness and response to the 2026–2027 El Niño phenomenon"], "agencies": [{"country": null, "name": "UNHCR", "type": "international"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}], "agency_types": ["international", "other_national_agency"], "channels": [], "confidence": 0.7, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Peru", "event_name": null, "first_seen": "2026-10-27T04:18:46Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 181, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:46Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a coordination meeting on preparedness but reports no outcomes of warnings.", "pillars": [4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI y ACNUR fortalecen cooperación para la preparación y respuesta ante el Fenómeno El Niño 2026–2027", "title_en": "INDECI and UNHCR strengthen cooperation for preparedness and response to the 2026–2027 El Niño phenomenon", "url": "https://www.gob.pe/institucion/indeci/noticias/1462723-indeci-y-acnur-fortalecen-cooperacion-para-la-preparacion-y-respuesta-ante-el-fenomeno-el-nino-2026-2027"}], "summaries_original": {"es": "INDECI sostuvo una reunión de trabajo con representantes de ACNUR para fortalecer la cooperación interinstitucional en la preparación y respuesta ante el Fenómeno El Niño 2026–2027."}, "summary_en": "Peru''s National Civil Defence Institute (INDECI) met with UNHCR representatives to strengthen inter-institutional cooperation for preparedness and response to the anticipated 2026–2027 El Niño phenomenon. The item focuses on preparedness coordination rather than on specific forecasts or warnings issued.", "title": "INDECI and UNHCR strengthen cooperation for preparedness and response to the 2026–2027 El Niño phenomenon", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(182,'flood|US|four corners region','flash_flood','2026-10-27T04:21:00Z','2026-10-27T04:09:39Z','2026-10-25','{"actions": ["Rescues of people from roofs", "Emergency declaration for a county", "Evacuation orders for residents in susceptible areas", "Disaster emergency declared in 12 Colorado counties"], "agencies": [{"country": "US", "name": "Colorado Governor''s Office", "type": "other"}], "agency_types": ["other"], "channels": [], "confidence": 0.8, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-25", "event_location": "Four Corners region, USA", "event_name": null, "first_seen": "2026-10-27T04:09:39Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 182, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-27T04:09:39Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports evacuation orders and rescues but does not state whether warnings preceded the flooding or how effective they were.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-25T04:09:36Z", "source_name": "npr.org", "title": "Flooding in Four Corners region displaces residents, as storms move southeast", "title_en": "Flooding in Four Corners region displaces residents, as storms move southeast", "url": "https://npr.org/2026/10/23/nx-s1-6014742/flooding-weather-four-corners"}], "summaries_original": {}, "summary_en": "Flooding in the Four Corners region inundated homes, requiring rescues from roofs and a county emergency declaration. Residents in susceptible areas were told to evacuate, and Colorado''s governor declared disaster emergencies in 12 counties. The snippet does not detail the forecasts or warnings issued in advance.", "title": "Flooding in Four Corners region displaces residents, as storms move southeast", "wmo_regions": ["IV"]}');
INSERT INTO "stories" VALUES(183,'multi_hazard|BI|tanzania','multi_hazard','2026-10-27T04:21:00Z','2026-10-27T04:08:00Z','2026-10-26','{"actions": ["Strengthened El Niño preparedness through early warning, logistics planning and anticipatory action", "Launched Tanzania''s first ECHO-funded disaster preparedness partnership with IOM"], "agencies": [{"country": null, "name": "ECHO", "type": "international"}, {"country": null, "name": "IOM", "type": "international"}, {"country": null, "name": "World Food Programme", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.6, "countries": [{"code": "BI", "name": "Burundi"}, {"code": "CD", "name": "Democratic Republic of the Congo"}, {"code": "TZ", "name": "Tanzania"}], "event_date": "2026-10-26", "event_location": "Tanzania", "event_name": null, "first_seen": "2026-10-27T04:08:00Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 183, "impacts": {"people_reached": 142017}, "languages": ["en"], "last_updated": "2026-10-27T04:08:00Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes preparedness actions for El Niño but reports no outcomes of warnings.", "pillars": [4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-26T05:54:52Z", "source_name": "ReliefWeb - Updates", "title": "WFP Tanzania Country Brief October 2026", "title_en": "WFP Tanzania Country Brief October 2026", "url": "https://reliefweb.int/report/united-republic-tanzania/wfp-tanzania-country-brief-october-2026"}], "summaries_original": {}, "summary_en": "WFP''s October 2026 Tanzania country brief reports food assistance to 142,017 people in September, including refugees in Nyarugusu Camp. It notes WFP strengthened El Niño preparedness through early warning, logistics planning and anticipatory action, and launched an ECHO-funded disaster preparedness partnership with IOM. The snippet is a general operational update with limited early-warning detail.", "title": "WFP Tanzania Country Brief October 2026", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(184,'named|el nino drought karamoja','multi_hazard','2026-10-27T04:21:01Z','2026-10-27T04:08:00Z','2026-10-26','{"actions": ["Joint UN and partners appeal to protect 560,000 people including refugees and about 130,000 people in food-insecure households", "Alignment with Government of Uganda El Niño Contingency and Response Plan 2026-2027"], "agencies": [{"country": "UG", "name": "UN Country Team in Uganda", "type": "international"}, {"country": "UG", "name": "UN Resident Coordinator in Uganda", "type": "international"}, {"country": "UG", "name": "Government of Uganda", "type": "other_national_agency"}], "agency_types": ["international", "other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "UG", "name": "Uganda"}], "event_date": "2026-10-26", "event_location": "Karamoja subregion, Uganda", "event_name": "El Niño 2026-2027 drought, Karamoja", "first_seen": "2026-10-27T04:08:00Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 184, "impacts": {"affected": 130000}, "languages": ["en"], "last_updated": "2026-10-27T04:08:00Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item is an appeal for funding and response; no outcome of warnings or actions is reported.", "pillars": [4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-26T08:55:55Z", "source_name": "ReliefWeb - Updates", "title": "United Nations and Partners'' Joint Appeal for Uganda El Niño & Karamoja Food Insecurity and Nutrition Crisis", "title_en": "United Nations and Partners'' Joint Appeal for Uganda El Niño & Karamoja Food Insecurity and Nutrition Crisis", "url": "https://reliefweb.int/report/uganda/united-nations-and-partners-joint-appeal-uganda-el-nino-karamoja-food-insecurity-and-nutrition-crisis"}], "summaries_original": {}, "summary_en": "The UN and partners launched a joint appeal responding to severe food insecurity and nutrition crisis in Uganda''s Karamoja subregion, linked to prolonged drought associated with El Niño in 2026. The appeal aims to protect 560,000 people, including refugees and about 130,000 people in 32,000 households facing severe food insecurity. It is aligned with the Government of Uganda''s El Niño Contingency and Response Plan for 2026-2027.", "title": "United Nations and Partners'' Joint Appeal for Uganda El Niño & Karamoja Food Insecurity and Nutrition Crisis", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(185,'','other','2026-10-27T04:21:02Z','2026-10-27T04:08:01Z','2026-10-26','{"actions": [], "agencies": [{"country": null, "name": "LoRaVida", "type": "NGO"}], "agency_types": ["NGO"], "channels": ["other"], "confidence": 0.6, "countries": [], "event_date": "2026-10-26", "event_location": null, "event_name": null, "first_seen": "2026-10-27T04:08:01Z", "hazard": "other", "hazards": ["other"], "id": 185, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-27T04:08:01Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a system aimed at delivering warnings in areas without mobile networks but reports no specific event or outcome.", "pillars": [3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-26T09:36:13Z", "source_name": "PreventionWeb", "title": "LoRaVida", "title_en": "LoRaVida", "url": "https://www.preventionweb.net/organization/loravida"}, {"language": "en", "published_at": "2026-10-26T09:36:13Z", "source_name": "UNDRR news", "title": "LoRaVida", "title_en": "LoRaVida", "url": "https://www.undrr.org/organization/loravida"}], "summaries_original": {}, "summary_en": "LoRaVida is described as an early warning approach for remote mountain valleys lacking mobile network coverage, where hazards occur but warning systems do not reach. The item concerns warning dissemination in areas with no mobile connectivity. No specific hazard event, forecast, or outcome is reported in the snippet.", "title": "LoRaVida", "wmo_regions": []}');
INSERT INTO "stories" VALUES(186,'flood|CN|nepal and china border region','flood','2026-10-27T04:21:03Z','2026-10-27T04:08:01Z','2026-10-26','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "CN", "name": "China"}, {"code": "NP", "name": "Nepal"}], "event_date": "2026-10-26", "event_location": "Nepal and China border region", "event_name": null, "first_seen": "2026-10-27T04:08:01Z", "hazard": "flood", "hazards": ["flood"], "id": 186, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-27T04:08:01Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet discusses using AI for flood anticipation and cross-border warnings but reports no specific warning outcome.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-26T12:07:43Z", "source_name": "PreventionWeb", "title": "Can AI save lives before the next flood?", "title_en": "Can AI save lives before the next flood?", "url": "https://www.preventionweb.net/news/can-ai-save-lives-next-flood"}], "summaries_original": {}, "summary_en": "An opinion piece on PreventionWeb uses a Nepal–China flood to argue that AI should be applied now to anticipate floods and accelerate cross-border early warnings. It emphasises protecting lives in the near term rather than focusing only on future threats. No specific warnings or outcomes are described in the snippet.", "title": "Can AI save lives before the next flood?", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(187,'flood|PE|ayabaca','heavy_rain','2026-10-27T04:21:05Z','2026-10-27T04:18:51Z','2026-10-26','{"actions": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Defensoría del Pueblo", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-26", "event_location": "Ayabaca, Piura, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:51Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 187, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports flooding of homes and Senamhi forecasts of up to 40 mm/day, but does not state whether warnings were received or acted upon.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-26T17:03:56Z", "source_name": "La República (Perú) sociedad", "title": "Fuertes lluvias en Piura inundan viviendas en Ayabaca: Senamhi alerta por precipitaciones intensas en el norte del país", "title_en": "Heavy rains in Piura flood homes in Ayabaca: Senamhi warns of intense precipitation in northern Peru", "url": "https://larepublica.pe/sociedad/2026/10/26/fuertes-lluvias-en-piura-inundan-viviendas-en-ayabaca-senamhi-alerta-por-precipitaciones-intensas-en-el-norte-del-pais-1491022"}], "summaries_original": {"es": "Las lluvias del domingo afectaron 15 viviendas en Ayabaca y Senamhi prevé hasta 40 mm diarios en la costa norte, además de descargas eléctricas y ráfagas de viento."}, "summary_en": "Rainfall on Sunday flooded 15 homes in Ayabaca, Piura, according to the Ombudsman''s office, carrying mud through streets and shops. Senamhi forecasts accumulations of up to 40 mm per day on the northern coast, along with electrical discharges and gusts near 40 km/h.", "title": "Heavy rains in Piura flood homes in Ayabaca: Senamhi warns of intense precipitation in northern Peru", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(188,'flood|CL|las condes','flash_flood','2026-10-27T04:21:05Z','2026-10-27T04:18:52Z','2026-10-27','{"actions": ["Residents advised to stay in place (SAE alert sent to mobile phones at 22:04)", "Red Alert declared in 10 precordillera communes of the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["cell_broadcast"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Las Condes, Región Metropolitana, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 188, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the alert being issued and sent to phones but does not describe its effects or any impacts.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T01:12:40Z", "source_name": "BioBioChile nacional", "title": "Senapred activa nuevamente alerta SAE por repentino desborde de Quebrada Honda en Las Condes", "title_en": "Senapred activates SAE alert again due to sudden overflow of Quebrada Honda in Las Condes", "url": "https://www.biobiochile.cl/noticias/nacional/chile/2026/10/26/senapred-activa-nuevamente-alerta-sae-por-repentino-desborde-de-quebrada-honda-en-las-condes.shtml"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "elmostrador.cl", "title": "Senapred declara Alerta Roja en 10 comunas de la RM por riesgo de aluviones tras intensas lluvias", "title_en": "Senapred declares Red Alert in 10 communes of the Metropolitan Region due to risk of debris flows after intense rains", "url": "https://elmostrador.cl/noticias/pais/2026/10/26/senapred-declara-alerta-roja-en-10-comunas-de-la-rm-por-riesgo-de-aluviones-tras-intensas-lluvias"}], "summaries_original": {"es": "Senapred activó nuevamente una alerta SAE por el desborde de Quebrada Honda, en la comuna de Las Condes, en medio de intensas lluvias en la capital. La advertencia fue enviada a los celulares a las 22:04 horas, llamando a los vecinos a mantenerse en lugares seguros."}, "summary_en": "Senapred issued a SAE emergency alert to mobile phones at 22:04 local time after the Quebrada Honda overflowed suddenly in Las Condes amid intense rain in Santiago. The alert called on residents to remain in safe locations. This is a repeat activation of the alert for the same ravine.", "title": "Senapred activates SAE alert again due to sudden overflow of Quebrada Honda in Las Condes", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(189,'flood|PE|kimbiri','flood','2026-10-27T04:21:06Z','2026-10-27T04:18:51Z','2026-10-27','{"actions": ["Emergency evacuation of residents initiated by authorities"], "agencies": [{"country": "PE", "name": "Local authorities", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.6, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Kimbiri, Cusco, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:51Z", "hazard": "flood", "hazards": ["flood"], "id": 189, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:51Z", "lead_time": null, "outcome": "negative", "outcome_justification": "The event caught residents by surprise and some people were reportedly trapped in the river, suggesting no effective advance warning was given.", "pillars": [4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T03:00:17Z", "source_name": "La República (Perú) sociedad", "title": "Cusco: desborde del río Kimbiri arrasa viviendas en el VRAEM y obliga a evacuar a pobladores", "title_en": "Cusco: Kimbiri river overflow sweeps away homes in the VRAEM and forces residents to evacuate", "url": "https://larepublica.pe/sociedad/2026/10/26/cusco-desborde-del-rio-kimbiri-arrasa-viviendas-en-el-vraem-y-obliga-a-evacuar-a-pobladores-1288378"}], "summaries_original": {"es": "Un desborde del río Kimbiri en el VRAEM, Cusco, arrasó viviendas y obligó a las autoridades a evacuar de emergencia a los pobladores; algunas personas habrían quedado atrapadas en el río, y el evento tomó por sorpresa a la población."}, "summary_en": "A sudden overflow of the Kimbiri river in the VRAEM area of Cusco, Peru, swept away homes and forced authorities to launch an emergency evacuation. Residents were reportedly taken by surprise and some people may have been trapped in the river, indicating that advance warning was limited or absent.", "title": "Cusco: Kimbiri river overflow sweeps away homes in the VRAEM and forces residents to evacuate", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(190,'severe_storm|CL|region metropolitana','severe_storm','2026-10-27T04:21:08Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Declaration of Early Preventive Alert (Alerta Temprana Preventiva) for the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Región Metropolitana, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 190, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": "from Monday afternoon until conditions warrant; issued 26 October 2026 for Monday 27 October", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the alert; no outcomes of the event are described.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "biobiochile.cl", "title": "Decretan Alerta Temprana Preventiva en la RM por pronóstico de lluvia, tormenta eléctrica y granizos", "title_en": "Early Preventive Alert declared in the Metropolitan Region due to forecast rain, thunderstorms and hail", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/26/decretan-alerta-temprana-preventiva-en-la-rm-por-pronostico-de-lluvia-tormenta-electrica-y-granizos.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana ante el pronóstico de lluvias normales a moderadas, tormentas eléctricas y posibles granizos para la tarde del lunes. El aviso rige desde ese día hasta que las condiciones lo ameriten."}, "summary_en": "Chile''s national emergency agency Senapred declared an Early Preventive Alert for the Metropolitan Region ahead of forecast normal to moderate rain, electrical storms and possible hail on Monday afternoon. The alert remains in force until conditions warrant it being lifted.", "title": "Early Preventive Alert declared in the Metropolitan Region due to forecast rain, thunderstorms and hail", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(191,'flood|PE|peru (northern coast and highlands)','heavy_rain','2026-10-27T04:21:11Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Indeci warned of possible huaicos and landslides and called for reinforced preventive measures", "Senamhi issued red-level meteorological warning No. 440 for heavy to extreme rainfall", "Indeci recommended reinforcing house roofs and establishing early warning mechanisms with local authorities", "Indeci recommended authorities verify evacuation routes and emergency services", "National authorities urged regional and local governments to adopt measures to ensure population safety", "SENAMHI maintained red-level Meteorological Warning No. 440 for precipitation on the northern coast and highlands, valid until Thursday 29 October 2026"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Indeci", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.97, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Peru", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 191, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": "period 27-29 October 2026", "outcome": "negative", "outcome_justification": "The item reports the issuance of a red alert and warnings but no observed outcomes of the warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "wapa.pe", "title": "Senamhi activa ALERTA ROJA por lluvias intensas: estas 11 regiones serán afectadas hasta el 29 de octubre", "title_en": "Senamhi activates RED ALERT for intense rain: these 11 regions will be affected until October 29", "url": "https://wapa.pe/ocio/2026/10/26/senamhi-activa-alerta-roja-lluvias-intensas-11-regiones-seran-afectadas-29-octubre-911742"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "infobae.com", "title": "El Senamhi emite una alerta roja por lluvias intensas en 11 departamentos del Perú entre el 27 y 29 de octubre - Infobae", "title_en": "Senamhi issues red alert for heavy rains in 11 departments of Peru between 27 and 29 October", "url": "https://www.infobae.com/peru/2026/10/26/el-senamhi-emite-una-alerta-roja-por-lluvias-intensas-en-11-departamentos-del-peru-entre-el-27-y-29-de-octubre/"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "larepublica.pe", "title": "Alerta roja del Senamhi en 11 departamentos: pronostican lluvias de extrema intensidad, granizo y nevadas hasta el 29 de octubre", "title_en": "Senamhi red alert in 11 departments: extreme-intensity rain, hail and snowfall forecast until 29 October", "url": "https://larepublica.pe/sociedad/2026/10/26/alerta-roja-del-senamhi-en-11-departamentos-pronostican-lluvias-de-extrema-intensidad-granizo-y-nevadas-hasta-el-29-de-octubre-322478"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "elcomercio.pe", "title": "Estos 11 departamentos del Perú serán afectados por fuertes lluvias entre el 27 y 29 de octubre del 2026: Senamhi ya lanzó la alerta roja", "title_en": "These 11 departments of Peru will be affected by heavy rains between October 27 and 29, 2026: Senamhi has already issued the red alert", "url": "https://elcomercio.pe/respuestas/que/estos-11-departamentos-del-peru-seran-afectados-por-fuertes-lluvias-entre-el-27-y-29-de-octubre-del-2026-senamhi-ya-lanzo-la-alerta-roja-tdpe-noticia/"}, {"language": "es", "published_at": "2026-10-28T04:15:55Z", "source_name": "buenapepa.pe", "title": "Alerta roja por lluvias en Tumbes y Piura: ¿hasta cuándo durará y con qué intensidad lloverá?", "title_en": "Red alert for rain in Tumbes and Piura: how long will it last and how intense will the rain be?", "url": "https://buenapepa.pe/senamhi-alerta-roja-lluvias-tumbes-piura/"}], "summaries_original": {"es": "El Senamhi activó alerta roja por lluvias intensas en 11 regiones para el periodo del 27 al 29 de octubre, con posible granizo, nevadas y fuertes vientos. El Indeci advirtió sobre posibles huaicos y deslizamientos y pidió reforzar medidas preventivas."}, "summary_en": "Peru''s national meteorological service Senamhi activated a red alert for intense rainfall in 11 regions for 27-29 October 2026, with possible hail, snowfall and strong winds. The civil protection agency Indeci warned of possible flash floods (huaicos) and landslides and urged reinforced preventive measures.", "title": "Senamhi activates RED ALERT for intense rain: these 11 regions will be affected until October 29", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(192,'flood|CL|metropolitan region','heavy_rain','2026-10-27T04:21:15Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Red alert issued for ten communes for risk of mass movements", "Class suspension in Las Condes", "Evacuation of 25 people in San Carlos de Apoquindo", "Evacuation of 16 people in Lo Barnechea", "Declaration of preventive early alert for the Metropolitan Region in response to two active DMC warnings", "Activation of Sinapred to reinforce surveillance and act in a timely manner"], "agencies": [{"country": "CL", "name": "Dirección Meteorológica de Chile", "type": "NMHS"}, {"country": "CL", "name": "Government of Chile (Metropolitan Region authorities)", "type": "other_national_agency"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Sinapred", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 192, "impacts": {"evacuated": 41}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports alerts and evacuations but does not state whether the warnings were timely or effective.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "latercera.com", "title": "Minuto a minuto: sigue el avance de las lluvias en la zona oriente de la RM - La Tercera", "title_en": "Live blog: follow the rainfall progress in the eastern zone of the Metropolitan Region", "url": "https://www.latercera.com/nacional/noticia/minuto-a-minuto-se-activa-quebrada-honda-en-las-condes-por-fuertes-lluvias-en-zona-oriente/"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "radio.uchile.cl", "title": "Por lluvias y posibles tormentas eléctricas: Senapred declara alerta temprana preventiva para la RM - Diario y Radio Universidad Chile", "title_en": "Due to rain and possible thunderstorms: Senapred declares preventive early alert for the Metropolitan Region", "url": "https://radio.uchile.cl/2026/10/26/por-lluvias-y-posibles-tormentas-electricas-senapred-declara-alerta-temprana-preventiva-para-la-rm/"}], "summaries_original": {"es": "Diez comunas de la Región Metropolitana están con alerta roja por riesgo de remociones en masa, con suspensión de clases en Las Condes y evacuaciones en San Carlos de Apoquindo y Lo Barnechea."}, "summary_en": "A live news blog reports that ten communes in the Metropolitan Region of Santiago are under red alert for the risk of mass movements due to heavy rain. Authorities suspended classes in Las Condes and evacuated 25 people in San Carlos de Apoquindo and 16 in Lo Barnechea. The snippet does not describe how the warnings were disseminated or their lead time.", "title": "Live blog: follow the rainfall progress in the eastern zone of the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(193,'multi_hazard|GR|attica and rhodes','multi_hazard','2026-10-27T04:21:15Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Civil protection issued a reinforced alert in Attica and Rhodes until 29 October", "EMY raised the alert level to red and extended the warning until 28 October in several regions"], "agencies": [{"country": "GR", "name": "EMY (Hellenic National Meteorological Service)", "type": "NMHS"}, {"country": "GR", "name": "Civil Protection (Attica and Rhodes authorities)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "GR", "name": "Greece"}], "event_date": "2026-10-27", "event_location": "Attica and Rhodes, Greece", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 193, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and alert levels issued but gives no information on outcomes, impacts or how the warnings were received.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "es.rua.gr", "title": "Grecia bajo la influencia del mal tiempo: las lluvias durarán hasta el 28 de octubre, donde será más peligroso - Noticias de Atenas", "title_en": "Greece under the influence of bad weather: rains will last until 28 October, where it will be most dangerous", "url": "https://es.rua.gr/2026/10/26/grecia-bajo-la-influencia-del-mal-tiempo-las-lluvias-duraran-hasta-el-28-de-octubre-donde-sera-mas-peligroso/"}], "summaries_original": {"es": "Las autoridades de Ática y Rodas anunciaron una alerta reforzada de protección civil hasta el 29 de octubre. El EMY elevó el nivel de alerta a rojo y amplió el aviso hasta el 28 de octubre en varias regiones griegas."}, "summary_en": "Greek civil protection authorities in Attica and Rhodes announced a reinforced alert until 29 October, and EMY raised its alert level to red, extending the warning to 28 October in several regions. The item concerns forecast-based warnings of prolonged bad weather, with no outcome reported in the snippet.", "title": "Greece under the influence of bad weather: rains will last until 28 October, where it will be most dangerous", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(194,'','heatwave','2026-10-28T04:18:05Z','2026-10-28T04:11:02Z','2026-10-28','{"actions": ["Public engagement with weather warnings and advice assessed through new research"], "agencies": [{"country": "GB", "name": "Met Office", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.85, "countries": [{"code": "GB", "name": "United Kingdom"}], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:11:02Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 194, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:02Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports survey findings on how engaged 18-24-year-olds are with weather warnings after a record summer heat period, but does not describe specific warning outcomes.", "pillars": [3], "review": false, "sources": [{"language": "en", "published_at": null, "source_name": "UK Met Office news", "title": "Young people most likely to act on weather warnings after record summer Following this summer''s extreme heat, new Met Office research suggests 18-24-year-olds are among the most engaged age group when it comes to following weather warnings and advice. Read more", "title_en": "Young people most likely to act on weather warnings after record summer", "url": "https://www.metoffice.gov.uk/about-us/news-and-media/media-centre/weather-and-climate-news/2026/young-people-most-likely-to-act-on-weather-warnings-after-record-summer-"}], "summaries_original": {}, "summary_en": "The UK Met Office reports new research indicating that 18-24-year-olds are among the most engaged age groups in following weather warnings and advice after an extreme summer heat period. The finding concerns warning uptake and communication effectiveness, which is central to early warning dissemination.", "title": "Young people most likely to act on weather warnings after record summer", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(195,'','other','2026-10-28T04:18:06Z','2026-10-28T04:11:05Z','2026-10-28','{"actions": [], "agencies": [{"country": "PH", "name": "PAGASA", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["website"], "confidence": 0.6, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-10-28", "event_location": "Philippines", "event_name": null, "first_seen": "2026-10-28T04:11:05Z", "hazard": "other", "hazards": ["other"], "id": 195, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:05Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "Only the title is available; the press release is a PAGASA monitoring/advisory announcement on seasonal monsoon onset with no reported impacts or actions.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": null, "source_name": "PAGASA press releases", "title": "ONSET OF THE NORTHEAST MONSOON", "title_en": "Onset of the Northeast Monsoon", "url": "https://pagasa.dost.gov.ph/press-release/230"}], "summaries_original": {}, "summary_en": "PAGASA, the Philippine NMHS, issued a press release announcing the onset of the Northeast Monsoon, a seasonal climate-monitoring and forecasting update. Only the title is available, so no details on hazards, warnings, or outcomes can be confirmed.", "title": "Onset of the Northeast Monsoon", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(196,'cold_wave|PE|peruvian amazon jungle (selva)','cold_wave','2026-10-28T04:18:06Z','2026-10-29T04:17:03Z','2026-10-28','{"actions": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 442"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.93, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-28", "event_location": "Southern jungle (selva sur), Peru", "event_name": null, "first_seen": "2026-10-28T04:16:03Z", "hazard": "cold_wave", "hazards": ["cold_wave"], "id": 196, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-29T04:17:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a warning and recommended preparedness measures but reports no outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI pronostica lluvias y descenso de temperaturas por décimo cuarto friaje en la selva", "title_en": "SENAMHI forecasts rain and temperature drop due to the fourteenth friaje in the Peruvian jungle", "url": "https://www.gob.pe/institucion/senamhi/noticias/1463550-senamhi-pronostica-lluvias-y-descenso-de-temperaturas-por-decimo-cuarto-friaje-en-la-selva"}, {"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante el descenso de la temperatura diurna en la selva sur – décimo cuarto friaje", "title_en": "INDECI recommends preparedness measures for daytime temperature drop in southern jungle – fourteenth friaje", "url": "https://www.gob.pe/institucion/indeci/noticias/1464756-indeci-recomienda-medidas-de-preparacion-ante-el-descenso-de-la-temperatura-diurna-en-la-selva-sur-decimo-cuarto-friaje"}], "summaries_original": {"es": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 442 del SENAMHI, que informa sobre el descenso de la temperatura diurna en la selva, de moderada a fuerte intensidad, asociado al décimo cuarto friaje."}, "summary_en": "INDECI, Peru''s civil defence institute, recommends preparedness measures following SENAMHI Aviso N.° 442, which warns of moderate to strong daytime temperature drops in the southern jungle associated with the fourteenth friaje (cold surge) of the season. The notice is a government press release on an official SENAMHI warning and its follow-up advice.", "title": "INDECI recommends preparedness measures for daytime temperature drop in southern jungle – fourteenth friaje", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(197,'landslide|CL|metropolitan region','landslide','2026-10-28T04:18:10Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Red Alert declared for mass movement in 10 pre-Andean communes including San José de Maipo, Puente Alto, Las Condes and Colina"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-28T04:16:03Z", "hazard": "landslide", "hazards": ["landslide"], "id": 197, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the alert declaration but gives no information on outcomes or impacts.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "biobiochile.cl", "title": "Senapred declara Alerta Roja en 10 comunas precordilleranas de la RM por remoción en masa tras lluvias", "title_en": "Senapred declares Red Alert in 10 pre-Andean communes of the Metropolitan Region due to mass movement after rains", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/26/senapred-declara-alerta-roja-en-10-comunas-precordilleranas-de-la-rm-por-remocion-en-masa-tras-lluvias.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Roja por remoción en masa en 10 comunas precordilleranas de la Región Metropolitana debido al intenso sistema frontal, abarcando comunas como San José de Maipo, Puente Alto, Las Condes y Colina."}, "summary_en": "Chile''s national emergency agency Senapred declared a Red Alert for mass movement (landslide) risk in 10 pre-Andean communes of the Metropolitan Region following an intense frontal system. The alert covers communes including San José de Maipo, Puente Alto, Las Condes and Colina. The snippet does not report channels, lead time or impacts.", "title": "Senapred declares Red Alert in 10 pre-Andean communes of the Metropolitan Region due to mass movement after rains", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(198,'','tropical_cyclone','2026-10-28T04:18:12Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [{"country": null, "name": "Directorate-General for European Civil Protection and Humanitarian Aid Operations (DG ECHO)", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.2, "countries": [{"code": "PH", "name": "Philippines"}, {"code": "VN", "name": "Viet Nam"}], "event_date": "2026-10-27", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 198, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a risk analysis report commissioned to inform preparedness and anticipatory action frameworks, with no specific warnings, forecasts or outcomes reported.", "pillars": [], "review": true, "sources": [{"language": "en", "published_at": "2026-10-27T13:52:41Z", "source_name": "PreventionWeb", "title": "Tropical cyclone risk evolution in the Philippines and Vietnam", "title_en": "Tropical cyclone risk evolution in the Philippines and Vietnam", "url": "https://www.preventionweb.net/publication/documents-and-publications/tropical-cyclone-risk-evolution-philippines-and-vietnam"}], "summaries_original": {}, "summary_en": "A report commissioned by DG ECHO analyses the evolution of tropical cyclone risk in the Philippines and Vietnam to inform preparedness and anticipatory action frameworks. The snippet does not describe monitoring, warnings, or dissemination of early warnings during a specific event, so its relevance to early warning service delivery is limited.", "title": "Tropical cyclone risk evolution in the Philippines and Vietnam", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(199,'','tsunami','2026-10-28T04:18:13Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [], "event_date": "2026-10-27", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "tsunami", "hazards": ["tsunami"], "id": 199, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports a research study on evacuation route safety and timing after earthquakes, without describing any actual warning event or its outcome.", "pillars": [1, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T14:06:19Z", "source_name": "PreventionWeb", "title": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "title_en": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "url": "https://www.preventionweb.net/news/low-cost-tool-can-help-people-plan-successful-evacuation-routes-during-tsunami"}], "summaries_original": {}, "summary_en": "Researchers Alejandra Gubler and Matías Carvajal published a study in Seismological Research Letters showing that evacuation route safety during a tsunami depends strongly on how quickly people start evacuating after an earthquake. The work proposes a low-cost tool to help people plan safer evacuation routes. The item focuses on evacuation planning as a preparedness measure rather than on a specific warning event.", "title": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "wmo_regions": []}');
INSERT INTO "stories" VALUES(200,'drought|XX|southern africa','drought','2026-10-28T04:18:14Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.6, "countries": [], "event_date": "2026-10-27", "event_location": "Southern Africa", "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "drought", "hazards": ["drought"], "id": 200, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes drought impacts on livestock and suggests improved weather forecasts with targeted support could help, but reports no specific warning issued or outcome.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T15:27:12Z", "source_name": "PreventionWeb", "title": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "title_en": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "url": "https://www.preventionweb.net/news/drought-forces-livestock-farmers-make-tough-decisions-our-model-shows-impact-inequality"}], "summaries_original": {}, "summary_en": "Drought threatens livestock and livelihoods in southern Africa and worsens inequality among pastoralist communities. The study argues that improved weather forecasts combined with targeted support could help these communities adapt and reduce impacts.", "title": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(201,'severe_storm|JP|northern japan','severe_storm','2026-10-28T04:18:14Z','2026-10-28T04:11:13Z','2026-10-28','{"actions": ["JMA announced the ''Kogarashi 1'' (first winter wind) observation for Tokyo and Kinki at 11:00", "Strong wind alerts issued for northern Japan"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-28", "event_location": "Northern Japan, Japan", "event_name": null, "first_seen": "2026-10-28T04:11:13Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 201, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-28T04:11:13Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and observations but no outcomes or impacts from the event.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-28T03:03:00Z", "source_name": "NHK ニュース 主要", "title": "冬型気圧配置 初雪や「木枯らし1号」も 北日本は暴風など警戒", "title_en": "Winter pressure pattern brings first snow and ''first north wind of winter'' (Kogarashi 1); strong winds warned in northern Japan", "url": "https://news.web.nhk/newsweb/na/nd-20261028de66726"}], "summaries_original": {"ja": "冬型の気圧配置と上空の寒気の影響で北日本を中心に雪が降り、札幌市や青森市などで初雪が観測された。気象庁は東京と近畿で「木枯らし1号」を発表し、北日本では暴風への警戒が呼びかけられた。"}, "summary_en": "A winter pressure pattern and upper-level cold air brought snow and first-snow observations to northern Japan, including Sapporo and Aomori. JMA announced the ''Kogarashi 1'' winter wind observation for Tokyo and Kinki, and strong wind warnings were issued for northern Japan.", "title": "Winter pressure pattern brings first snow and ''first north wind of winter'' (Kogarashi 1); strong winds warned in northern Japan", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(202,'earthquake|PH|sarangani','earthquake','2026-10-28T04:18:17Z','2026-10-28T04:11:13Z','2026-10-28','{"actions": ["Suspension of face-to-face classes at all levels across Sarangani province", "Suspension of government office work across Sarangani province", "Post-earthquake safety assessments ordered"], "agencies": [{"country": "PH", "name": "Sarangani Provincial Information Office", "type": "other_national_agency"}, {"country": "PH", "name": "Sarangani provincial government", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["social_media"], "confidence": 0.6, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-10-28", "event_location": "Sarangani, Philippines", "event_name": null, "first_seen": "2026-10-28T04:11:13Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 202, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:13Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports protective actions after the quake but gives no information on whether warnings or advisories preceded it or on resulting impacts.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T09:59:09Z", "source_name": "Philippine Daily Inquirer", "title": "Sarangani suspends classes, gov’t work after magnitude 5.5 quake", "title_en": "Sarangani suspends classes, gov''t work after magnitude 5.5 quake", "url": "https://newsinfo.inquirer.net/2331477/sarangani-suspends-classes-govt-work-after-magnitude-5-5-quake"}], "summaries_original": {}, "summary_en": "After a magnitude 5.5 earthquake struck Sarangani province around 7:43 a.m., the provincial government suspended classes and government work via a social media advisory to allow post-earthquake safety inspections. The item documents a post-event response advisory disseminated through social media, but does not describe monitoring, pre-event warnings or impacts.", "title": "Sarangani suspends classes, gov''t work after magnitude 5.5 quake", "wmo_regions": ["II", "V"]}');
